            .expect("no message received");

        let parsed: serde_json::Value = serde_json::from_str(&msg).unwrap();
        assert_eq!(parsed["msg_type"], "agent.session.command.response");
        assert_eq!(parsed["payload"]["request_id"], "req-456");
        assert_eq!(parsed["payload"]["command"], "session.kill");
        assert_eq!(parsed["payload"]["success"], true);

        handle.shutdown().await.ok();
        server_handle.abort();
    }

    /// Mock server that sends a heartbeat ack after registration.
    async fn start_mock_server_with_heartbeat_ack(
        port: u16,
    ) -> (tokio::task::JoinHandle<()>, mpsc::Receiver<String>) {
        let (_msg_tx, msg_rx) = mpsc::channel(100);
        let listener = TcpListener::bind(format!("127.0.0.1:{}", port))
            .await
            .expect("failed to bind mock server");

        let handle = tokio::spawn(async move {
            if let Ok((stream, _)) = listener.accept().await {
                let ws = accept_async(stream).await.expect("failed to accept ws");
                let (mut sink, mut stream) = ws.split();

                // Send registration response.
                let response = serde_json::json!({
                    "msg_type": "agent.register.response",
                    "id": "test-id",
                    "timestamp": 1234567890,
                    "payload": {
                        "status": "accepted",
                        "message": "ok"
                    }
                });
                let _ = sink.send(WsMessage::Text(response.to_string())).await;

                // Skip registration message from client.
                let _ = stream.next().await;

                // Send heartbeat ack.
                let ack = serde_json::json!({
                    "msg_type": "server.heartbeat.ack",
                    "id": "ack-1",
                    "timestamp": 1234567893,
                    "payload": {}
                });
                let _ = sink.send(WsMessage::Text(ack.to_string())).await;

                // Keep connection alive.
                while let Some(Ok(_)) = stream.next().await {}
            }
        });

        (handle, msg_rx)
    }

    #[tokio::test]
    async fn test_server_heartbeat_ack() {
        let port = 28088;
        let (server_handle, _msg_rx) = start_mock_server_with_heartbeat_ack(port).await;
        tokio::time::sleep(Duration::from_millis(100)).await;

        let metadata = AgentMetadata {
            tmux_version: "3.3".to_string(),
            os_version: "Linux".to_string(),
            nession_version: "0.1.0".to_string(),
        };

        let client = ServerClient::new(
            format!("ws://127.0.0.1:{}", port),
            "test-token",
            "test-agent-ack",
            "test-host",
            "127.0.0.1",
            8080,
            None,
            metadata,
            Arc::new(TmuxManager::new()),
            "/tmp".to_string(),
        );

        let (handle, _interval) = client.connect_and_run().await.expect("connect failed");

        // Just verify the connection stays alive (heartbeat ack is handled internally).
        tokio::time::sleep(Duration::from_millis(200)).await;

        handle.shutdown().await.ok();
        server_handle.abort();
    }
}

//! Agent-local environment-file management.

pub mod store;

pub use store::EnvStore;

//! Agent-local env-file storage under `~/.nession/agent/envs`.
//!
//! A thin, path-safe CRUD layer over `.env` files. Filenames are validated to
//! reject path traversal and are always constrained to the envs directory.

use anyhow::{Context, Result};
use nession_common::env_file::parse_env;
use nession_common::protocol::{EnvFileInfo, EnvSource};
use std::path::{Path, PathBuf};
use tokio::fs;

/// Store for agent-local env files.
#[derive(Clone)]
pub struct EnvStore {
    root: PathBuf,
}

/// Validate that `name` is a safe `.env` filename: no path separators, no
/// traversal, ends in `.env`, non-empty stem.
fn validate_name(name: &str) -> Result<()> {
    if name.is_empty() {
        anyhow::bail!("env file name is empty");
    }
    if name.contains('/') || name.contains('\\') || name.contains("..") {
        anyhow::bail!("invalid env file name: {name}");
    }
    if Path::new(name).file_name().map(|f| f.to_string_lossy()) != Some(name.into()) {
        anyhow::bail!("invalid env file name: {name}");
    }
    if !name.ends_with(".env") || name.len() <= 4 {
        anyhow::bail!("env file name must end with .env: {name}");
    }
    Ok(())
}

impl EnvStore {
    /// Create a store rooted at `root`. The directory is created lazily on the
    /// first write, so construction is infallible.
    #[must_use]
    pub fn new(root: PathBuf) -> Self {
        Self { root }
    }

    fn path_for(&self, name: &str) -> Result<PathBuf> {
        validate_name(name)?;
        Ok(self.root.join(name))
    }

    /// List all `.env` files with metadata. Missing/unreadable dir → empty.
    pub async fn list(&self, agent_id: &str) -> Result<Vec<EnvFileInfo>> {
        let mut out = Vec::new();
        let mut dir = match fs::read_dir(&self.root).await {
            Ok(d) => d,
            Err(_) => return Ok(out),
        };
        while let Some(entry) = dir.next_entry().await? {
            let file_name = entry.file_name().to_string_lossy().to_string();
            if !file_name.ends_with(".env") {
                continue;
            }
            let meta = match entry.metadata().await {
                Ok(m) if m.is_file() => m,
                _ => continue,
            };
            let modified = meta
                .modified()
                .ok()
                .and_then(|t| t.duration_since(std::time::UNIX_EPOCH).ok())
                .map(|d| d.as_secs())
                .unwrap_or(0);
            let var_count = fs::read_to_string(entry.path())
                .await
                .map(|c| parse_env(&c).len())
                .unwrap_or(0);
            out.push(EnvFileInfo {
                name: file_name,
                source: EnvSource::Agent,
                agent_id: Some(agent_id.to_string()),
                size: meta.len(),
                modified,
                var_count,
            });
        }
        out.sort_by_key(|f| f.name.to_lowercase());
        Ok(out)
    }

    /// Read a file's raw content.
    pub async fn read(&self, name: &str) -> Result<String> {
        let path = self.path_for(name)?;
        fs::read_to_string(&path)
            .await
            .with_context(|| format!("failed to read env file: {name}"))
    }

    /// True if the named file exists.
    pub async fn exists(&self, name: &str) -> Result<bool> {
        let path = self.path_for(name)?;
        Ok(fs::try_exists(&path).await.unwrap_or(false))
    }

    /// Write (create/overwrite) a file atomically. When `overwrite` is false
    /// and the file exists, returns `Ok(false)` without writing.
    pub async fn write(&self, name: &str, content: &str, overwrite: bool) -> Result<bool> {
        let path = self.path_for(name)?;
        fs::create_dir_all(&self.root)
            .await
            .with_context(|| format!("failed to create env dir: {}", self.root.display()))?;
        if !overwrite && fs::try_exists(&path).await.unwrap_or(false) {
            return Ok(false);
        }
        let tmp = self
            .root
            .join(format!(".nession-{}.tmp", uuid::Uuid::new_v4()));
        fs::write(&tmp, content.as_bytes())
            .await
            .with_context(|| format!("failed to write temp env file for {name}"))?;
        if let Err(e) = fs::rename(&tmp, &path).await {
            let _ = fs::remove_file(&tmp).await;
            return Err(e).with_context(|| format!("failed to persist env file: {name}"));
        }
        Ok(true)
    }

    /// Delete a file. Missing file is treated as success (idempotent).
    pub async fn delete(&self, name: &str) -> Result<()> {
        let path = self.path_for(name)?;
        match fs::remove_file(&path).await {
            Ok(()) => Ok(()),
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(()),
            Err(e) => Err(e).with_context(|| format!("failed to delete env file: {name}")),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn store() -> (tempfile::TempDir, EnvStore) {
        let dir = tempfile::tempdir().unwrap();
        let store = EnvStore::new(dir.path().to_path_buf());
        (dir, store)
    }

    #[test]
    fn rejects_traversal() {
        assert!(validate_name("../evil.env").is_err());
        assert!(validate_name("a/b.env").is_err());
        assert!(validate_name("noext").is_err());
        assert!(validate_name(".env").is_err());
        assert!(validate_name("good.env").is_ok());
    }

    #[tokio::test]
    async fn write_read_list_delete_roundtrip() {
        let (_d, s) = store();
        assert!(s.write("a.env", "FOO=bar\n", false).await.unwrap());
        assert_eq!(s.read("a.env").await.unwrap(), "FOO=bar\n");

        let list = s.list("agent-1").await.unwrap();
        assert_eq!(list.len(), 1);
        assert_eq!(list.first().unwrap().name, "a.env");
        assert_eq!(list.first().unwrap().var_count, 1);
        assert_eq!(list.first().unwrap().source, EnvSource::Agent);

        s.delete("a.env").await.unwrap();
        assert!(s.list("agent-1").await.unwrap().is_empty());
    }

    #[tokio::test]
    async fn write_no_overwrite_refuses_when_exists() {
        let (_d, s) = store();
        assert!(s.write("a.env", "X=1", false).await.unwrap());
        // overwrite=false and exists → returns false, content unchanged
        assert!(!s.write("a.env", "X=2", false).await.unwrap());
        assert_eq!(s.read("a.env").await.unwrap(), "X=1");
        // overwrite=true replaces
        assert!(s.write("a.env", "X=2", true).await.unwrap());
        assert_eq!(s.read("a.env").await.unwrap(), "X=2");
    }

    #[tokio::test]
    async fn delete_missing_is_ok() {
        let (_d, s) = store();
        assert!(s.delete("missing.env").await.is_ok());
    }
}

use anyhow::{Context, Result};
use base64::Engine;
use serde::{Deserialize, Serialize};
use std::fs;
use tokio::task;

use super::sandbox::PathSandbox;

/// Maximum file size for read operations (10 MB).
const MAX_READ_SIZE: u64 = 10 * 1024 * 1024;

/// A filesystem entry returned by directory listing.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FileEntry {
    pub name: String,
    pub path: String,
    pub is_dir: bool,
    pub size: u64,
    pub modified: u64,
}

/// Data returned by a file read operation.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FileData {
    pub path: String,
    /// Base64-encoded file content.
    pub content: String,
    /// MIME type (e.g. "text/plain", "application/json").
    pub mime_type: String,
}

/// High-level file operations scoped to a sandbox root.
pub struct FileOps {
    sandbox: PathSandbox,
}

impl FileOps {
    pub fn new(sandbox: PathSandbox) -> Self {
        Self { sandbox }
    }

    /// List entries in a directory. Sorted: directories first, then files,
    /// both alphabetically by name.
    pub async fn list_dir(&self, path: &str) -> Result<Vec<FileEntry>> {
        let resolved = self.sandbox.resolve(path)?;

        if !resolved.is_dir() {
            anyhow::bail!("not_a_directory: {path}");
        }

        let root = self.sandbox.root().to_path_buf();

        let entries = task::spawn_blocking(move || -> Result<Vec<FileEntry>> {
            let mut result: Vec<FileEntry> = Vec::new();
            let dir = fs::read_dir(&resolved)
                .with_context(|| format!("failed to read directory: {}", resolved.display()))?;

            for entry in dir {
                let entry = entry?;
                let metadata = entry.metadata()?;
                let entry_path = entry.path();
                let name = entry.file_name().to_string_lossy().to_string();

                // Strip sandbox root so paths are relative — downstream
                // operations resolve against the same root via the sandbox.
                let relative_path = entry_path
                    .strip_prefix(&root)
                    .map(|p| p.to_string_lossy().to_string())
                    .unwrap_or_else(|_| name.clone());

                result.push(FileEntry {
                    name,
                    path: relative_path,
                    is_dir: metadata.is_dir(),
                    size: metadata.len(),
                    modified: metadata
                        .modified()
                        .ok()
                        .and_then(|t| t.duration_since(std::time::UNIX_EPOCH).ok())
                        .map(|d| d.as_secs())
                        .unwrap_or(0),
                });
            }

            // Sort: directories first (alphabetical), then files (alphabetical).
            result.sort_by(|a, b| {
                b.is_dir
                    .cmp(&a.is_dir)
                    .then_with(|| a.name.to_lowercase().cmp(&b.name.to_lowercase()))
            });

            Ok(result)
        })
        .await??;

        Ok(entries)
    }

    /// Read the contents of a file. Returns base64-encoded content.
    /// Rejects files larger than `MAX_READ_SIZE`.
    pub async fn read_file(&self, path: &str) -> Result<FileData> {
        let resolved = self.sandbox.resolve(path)?;
        let user_path = path.to_string();
        let path_for_mime = user_path.clone();

        let content = task::spawn_blocking(move || -> Result<(Vec<u8>, String)> {
            let metadata = fs::metadata(&resolved)
                .with_context(|| format!("failed to read metadata: {}", resolved.display()))?;

            if metadata.is_dir() {
                anyhow::bail!("is_directory: cannot read a directory");
            }

            let size = metadata.len();
            if size > MAX_READ_SIZE {
                anyhow::bail!(
                    "file_too_large: file is {size} bytes, max allowed is {MAX_READ_SIZE} bytes"
                );
            }

            let data = fs::read(&resolved)
                .with_context(|| format!("failed to read file: {}", resolved.display()))?;

            // Detect MIME type from the user-supplied path extension
            // (avoids leaking the on-disk path to the caller via MIME
            // detection resolution).
            let mime = mime_guess::from_path(&path_for_mime)
                .first_or_text_plain()
                .to_string();

            Ok((data, mime))
        })
        .await??;

        let encoded = base64::engine::general_purpose::STANDARD.encode(&content.0);

        Ok(FileData {
            path: user_path,
            content: encoded,
            mime_type: content.1,
        })
    }

    /// Write content to a file. Uses atomic write (temp + rename).
    /// `content` is base64-encoded bytes.
    pub async fn write_file(&self, path: &str, content_b64: &str) -> Result<u64> {
        let resolved = self.sandbox.resolve(path)?;

        let data = base64::engine::general_purpose::STANDARD
            .decode(content_b64)
            .context("failed to decode base64 content")?;

        let len = data.len() as u64;

        task::spawn_blocking(move || -> Result<u64> {
            // Ensure parent directory exists.
            if let Some(parent) = resolved.parent() {
                fs::create_dir_all(parent).with_context(|| {
                    format!("failed to create parent dir: {}", parent.display())
                })?;
            }

            // Use a unique temp file name to avoid collisions, even for
            // extensionless files where with_extension("tmp") would give
            // the same name for every concurrent write to the same path.
            let tmp_id = uuid::Uuid::new_v4();
            let tmp_name = format!(".nession-{tmp_id}.tmp");
            let tmp = resolved.with_file_name(&tmp_name);

            fs::write(&tmp, &data)
                .with_context(|| format!("failed to write temp file: {}", tmp.display()))?;

            match fs::rename(&tmp, &resolved) {
                Ok(()) => Ok(len),
                Err(e) => {
                    // Clean up the orphaned temp file on rename failure.
                    let _ = fs::remove_file(&tmp);
                    Err(e).with_context(|| format!("failed to rename temp file: {}", tmp.display()))
                }
            }
        })
        .await??;

        Ok(len)
    }

    /// Delete a file or an empty directory.
    pub async fn delete(&self, path: &str) -> Result<()> {
        let resolved = self.sandbox.resolve(path)?;

        task::spawn_blocking(move || -> Result<()> {
            if resolved.is_dir() {
                fs::remove_dir(&resolved).with_context(|| {
                    format!("failed to remove directory: {}", resolved.display())
                })?;
            } else {
                fs::remove_file(&resolved)
                    .with_context(|| format!("failed to remove file: {}", resolved.display()))?;
            }
            Ok(())
        })
        .await??;

        Ok(())
    }

    /// Create a directory (and any missing parents).
    pub async fn create_dir(&self, path: &str) -> Result<()> {
        let resolved = self.sandbox.resolve(path)?;

        task::spawn_blocking(move || -> Result<()> {
            fs::create_dir_all(&resolved)
                .with_context(|| format!("failed to create directory: {}", resolved.display()))?;
            Ok(())
        })
        .await??;

        Ok(())
    }

    /// Rename (move) a file or directory within the sandbox.
    pub async fn rename(&self, from: &str, to: &str) -> Result<()> {
        let from_resolved = self.sandbox.resolve(from)?;
        let to_resolved = self.sandbox.resolve(to)?;

        task::spawn_blocking(move || -> Result<()> {
            // Ensure parent of destination exists.
            if let Some(parent) = to_resolved.parent() {
                fs::create_dir_all(parent).with_context(|| {
                    format!("failed to create parent dir: {}", parent.display())
                })?;
            }
            fs::rename(&from_resolved, &to_resolved).with_context(|| {
                format!(
                    "failed to rename {} to {}",
                    from_resolved.display(),
                    to_resolved.display()
                )
            })?;
            Ok(())
        })
        .await??;

        Ok(())
    }

    /// Return the sandbox root path as a string.
    pub fn root_path(&self) -> String {
        self.sandbox.root().to_string_lossy().to_string()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn setup() -> (tempfile::TempDir, FileOps) {
        let dir = tempfile::tempdir().unwrap();
        let sandbox = PathSandbox::new(dir.path()).unwrap();
        let ops = FileOps::new(sandbox);
        (dir, ops)
    }

    #[tokio::test]
    async fn test_list_empty_dir() {
        let (_dir, ops) = setup();
        let entries = ops.list_dir("").await.unwrap();
        assert!(entries.is_empty());
    }

    #[tokio::test]
    async fn test_list_dir_with_files() {
        let (dir, ops) = setup();
        fs::write(dir.path().join("a.txt"), b"a").unwrap();
        fs::write(dir.path().join("b.txt"), b"bb").unwrap();
        fs::create_dir(dir.path().join("subdir")).unwrap();

        let entries = ops.list_dir("").await.unwrap();
        assert_eq!(entries.len(), 3);
        // Directories first.
        assert!(entries[0].is_dir);
        assert_eq!(entries[0].name, "subdir");
        assert_eq!(entries[1].name, "a.txt");
        assert_eq!(entries[2].name, "b.txt");
        assert_eq!(entries[2].size, 2);
    }

    #[tokio::test]
    async fn test_list_dir_returns_paths_relative_to_sandbox_root() {
        let (dir, ops) = setup();
        fs::write(dir.path().join("a.txt"), b"a").unwrap();
        fs::create_dir(dir.path().join("subdir")).unwrap();

        let entries = ops.list_dir("").await.unwrap();
        assert_eq!(entries.len(), 2);

        let subdir = entries.iter().find(|e| e.name == "subdir").unwrap();
        let file = entries.iter().find(|e| e.name == "a.txt").unwrap();

        // Paths must be relative to sandbox root, not absolute OS paths.
        assert_eq!(subdir.path, "subdir");
        assert_eq!(file.path, "a.txt");

        // Verify round-trip: pass a path from list_dir back to read_file.
        let content = ops.read_file(&file.path).await.unwrap();
        let decoded = base64::engine::general_purpose::STANDARD
            .decode(&content.content)
            .unwrap();
        assert_eq!(String::from_utf8(decoded).unwrap(), "a");
    }

    #[tokio::test]
    async fn test_list_dir_nested_path_is_relative() {
        let (dir, ops) = setup();
        fs::create_dir_all(dir.path().join("deep/nested")).unwrap();
        fs::write(dir.path().join("deep/nested/file.txt"), b"nested").unwrap();

        let entries = ops.list_dir("deep/nested").await.unwrap();
        assert_eq!(entries.len(), 1);

        let file = &entries[0];
        assert_eq!(file.name, "file.txt");
        // Path must be relative, not absolute.
        assert_eq!(file.path, "deep/nested/file.txt");

        // Round-trip through read_file.
        let data = ops.read_file(&file.path).await.unwrap();
        let decoded = base64::engine::general_purpose::STANDARD
            .decode(&data.content)
            .unwrap();
        assert_eq!(String::from_utf8(decoded).unwrap(), "nested");
    }

    #[tokio::test]
    async fn test_read_write_roundtrip() {
        let (_dir, ops) = setup();
        let content = "Hello, Nession! 你好 🚀";
        let b64 = base64::engine::general_purpose::STANDARD.encode(content.as_bytes());

        let written = ops.write_file("test.txt", &b64).await.unwrap();
        assert_eq!(written, content.len() as u64);

        let file_data = ops.read_file("test.txt").await.unwrap();
        let decoded = base64::engine::general_purpose::STANDARD
            .decode(&file_data.content)
            .unwrap();
        assert_eq!(String::from_utf8(decoded).unwrap(), content);
        assert_eq!(file_data.mime_type, "text/plain");
    }

    #[tokio::test]
    async fn test_read_nonexistent_file_fails() {
        let (_dir, ops) = setup();
        let result = ops.read_file("nonexistent.txt").await;
        assert!(result.is_err());
    }

    #[tokio::test]
    async fn test_read_directory_fails() {
        let (dir, ops) = setup();
        fs::create_dir(dir.path().join("mydir")).unwrap();
        let result = ops.read_file("mydir").await;
        assert!(result.is_err());
        assert!(result.unwrap_err().to_string().contains("is_directory"));
    }

    #[tokio::test]
    async fn test_delete_file() {
        let (dir, ops) = setup();
        fs::write(dir.path().join("del.txt"), b"delete me").unwrap();
        ops.delete("del.txt").await.unwrap();
        assert!(!dir.path().join("del.txt").exists());
    }

    #[tokio::test]
    async fn test_delete_nonexistent_fails() {
        let (_dir, ops) = setup();
        let result = ops.delete("nope.txt").await;
        assert!(result.is_err());
    }

    #[tokio::test]
    async fn test_create_dir() {
        let (dir, ops) = setup();
        ops.create_dir("a/b/c").await.unwrap();
        assert!(dir.path().join("a/b/c").is_dir());
    }

    #[tokio::test]
    async fn test_rename_file() {
        let (dir, ops) = setup();
        fs::write(dir.path().join("old.txt"), b"old").unwrap();
        ops.rename("old.txt", "new.txt").await.unwrap();
        assert!(!dir.path().join("old.txt").exists());
        assert_eq!(
            fs::read_to_string(dir.path().join("new.txt")).unwrap(),
            "old"
        );
    }

    #[tokio::test]
    async fn test_write_creates_parent_dirs() {
        let (dir, ops) = setup();
        let b64 = base64::engine::general_purpose::STANDARD.encode(b"deep");
        ops.write_file("deep/nested/file.txt", &b64).await.unwrap();
        assert_eq!(
            fs::read_to_string(dir.path().join("deep/nested/file.txt")).unwrap(),
            "deep"
        );
    }
}

use anyhow::{Context, Result};
use std::path::{Component, Path, PathBuf};

/// Restricts file operations to a root directory.
///
/// All paths are canonicalized and verified to stay within the sandbox
/// root. Symlinks are resolved before the bounds check. Attempts to
/// escape via `..` or symlinks outside root return `permission_denied`.
#[derive(Debug, Clone)]
pub struct PathSandbox {
    /// Canonicalized absolute root directory.
    root: PathBuf,
}

impl PathSandbox {
    /// Create a new sandbox rooted at `root`.
    ///
    /// The root path is canonicalized immediately. Returns an error if
    /// the root does not exist or cannot be accessed.
    pub fn new(root: impl AsRef<Path>) -> Result<Self> {
        let root = std::fs::canonicalize(root.as_ref())
            .with_context(|| format!("sandbox root does not exist: {}", root.as_ref().display()))?;
        Ok(Self { root })
    }

    /// Resolve a user-supplied path relative to the sandbox root.
    ///
    /// Returns the resolved path; existing components are canonicalized.
    /// Returns an error with code `permission_denied` if the resolved
    /// path lies outside the root.
    pub fn resolve(&self, path: &str) -> Result<PathBuf> {
        // Normalize: strip leading '/' to make it relative to root.
        // Defensive: also strip the sandbox root's own directory name if
        // the path already starts with it. Without this, clients that send
        // paths like "/root/.bashrc" (absolute paths on a root="/root"
        // sandbox) end up doubled to "/root/root/.bashrc" after joining.
        let relative = path.trim_start_matches('/');
        let relative = if let Some(root_name) = self.root.file_name() {
            Path::new(relative)
                .strip_prefix(root_name)
                .map(|p| p.as_os_str().to_string_lossy().into_owned())
                .unwrap_or_else(|_| relative.to_string())
        } else {
            relative.to_string()
        };
        let combined = self.root.join(&relative);

        // Early-detection heuristic for `..` traversal attempts.
        // This catches obvious escapes before touching the filesystem,
        // but the real security guarantee is the canonicalize +
        // starts_with check below.
        let normalized = normalize_path(&combined);
        if !normalized.starts_with(&self.root) {
            anyhow::bail!("permission_denied: path outside sandbox root");
        }

        // Canonicalize unconditionally — avoids a TOCTOU race between
        // an explicit exists() check and the actual canonicalization.
        let resolved = match std::fs::canonicalize(&combined) {
            Ok(p) => p,
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
                // Walk up the ancestor chain to find the first existing
                // directory, then append the non-existent suffix.
                // This handles paths like "a/b/c" where none of the
                // components exist yet (common for create_dir, write_file).
                //
                // NOTE: Use `Option<PathBuf>` for suffix to avoid
                // `join(empty_path)` on macOS, which spuriously adds a
                // trailing slash (e.g. `"a".join("")` → `"a/"`).
                let mut ancestor = combined.as_path();
                let mut suffix: Option<PathBuf> = None;
                loop {
                    match std::fs::canonicalize(ancestor) {
                        Ok(canonical) => {
                            if !canonical.starts_with(&self.root) {
                                anyhow::bail!("permission_denied: path outside sandbox root");
                            }
                            return Ok(match suffix {
                                Some(s) => canonical.join(&s),
                                None => canonical,
                            });
                        }
                        Err(inner) if inner.kind() == std::io::ErrorKind::NotFound => {
                            let name = ancestor.file_name().context("path has no filename")?;
                            suffix = Some(match suffix {
                                Some(s) => PathBuf::from(name).join(&s),
                                None => PathBuf::from(name),
                            });
                            ancestor = ancestor.parent().context("path has no parent")?;
                        }
                        Err(inner) => {
                            return Err(anyhow::Error::from(inner))
                                .with_context(|| format!("failed to resolve path: {path}"))
                        }
                    }
                }
            }
            Err(e) => return Err(anyhow::Error::from(e)).context("failed to resolve path"),
        };

        // Verify the resolved path is within the root.
        if !resolved.starts_with(&self.root) {
            anyhow::bail!("permission_denied: path outside sandbox root");
        }

        Ok(resolved)
    }

    /// Return the sandbox root path.
    pub fn root(&self) -> &Path {
        &self.root
    }
}

/// Early-detection heuristic: resolve `.` and `..` components without
/// touching the filesystem.
///
/// This provides a **logical** (not canonical) normalization useful for
/// detecting obvious directory traversal attempts before filesystem
/// operations are attempted.  It is NOT a security boundary — the real
/// guarantee comes from `canonicalize` + `starts_with` after resolution.
fn normalize_path(path: &Path) -> PathBuf {
    let mut components = Vec::new();
    for component in path.components() {
        match component {
            Component::ParentDir => {
                components.pop();
            }
            Component::CurDir => {}
            c => components.push(c.as_os_str()),
        }
    }
    let mut result = PathBuf::new();
    for c in components {
        result.push(c);
    }
    result
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::fs;
    use std::os::unix::fs::symlink;

    fn setup_sandbox() -> (tempfile::TempDir, PathSandbox) {
        let dir = tempfile::tempdir().unwrap();
        let sandbox = PathSandbox::new(dir.path()).unwrap();
        (dir, sandbox)
    }

    #[test]
    fn test_resolve_simple_path() {
        let (dir, sandbox) = setup_sandbox();
        let file_path = dir.path().join("test.txt");
        fs::write(&file_path, b"hello").unwrap();

        let resolved = sandbox.resolve("test.txt").unwrap();
        assert_eq!(resolved, file_path.canonicalize().unwrap());
    }

    #[test]
    fn test_resolve_nonexistent_path() {
        let (dir, sandbox) = setup_sandbox();
        let resolved = sandbox.resolve("new_file.txt").unwrap();
        assert_eq!(
            resolved,
            dir.path().canonicalize().unwrap().join("new_file.txt")
        );
    }

    #[test]
    fn test_resolve_subdirectory() {
        let (dir, sandbox) = setup_sandbox();
        let subdir = dir.path().join("sub");
        fs::create_dir(&subdir).unwrap();
        let file = subdir.join("nested.txt");
        fs::write(&file, b"nested").unwrap();

        let resolved = sandbox.resolve("sub/nested.txt").unwrap();
        assert_eq!(resolved, file.canonicalize().unwrap());
    }

    #[test]
    fn test_resolve_rejects_dot_dot_escape() {
        let (_dir, sandbox) = setup_sandbox();
        let result = sandbox.resolve("../etc/passwd");
        assert!(result.is_err());
        let err = result.unwrap_err().to_string();
        assert!(err.contains("permission_denied") || err.contains("outside sandbox"));
    }

    #[test]
    fn test_resolve_absolute_path_strips_leading_slash() {
        let (dir, sandbox) = setup_sandbox();
        // Leading `/` is stripped, so `/etc/passwd` → `etc/passwd`
        // relative to sandbox root. This is an in-sandbox non-existent path,
        // so it resolves successfully to `<root>/etc/passwd`.
        let result = sandbox.resolve("/etc/passwd").unwrap();
        let expected = dir.path().canonicalize().unwrap().join("etc/passwd");
        assert_eq!(result, expected);
    }

    #[test]
    fn test_resolve_rejects_symlink_escape() {
        let (dir, sandbox) = setup_sandbox();
        // Create a symlink pointing outside the sandbox.
        let link_path = dir.path().join("escape_link");
        symlink("/etc/passwd", &link_path).unwrap();

        let result = sandbox.resolve("escape_link");
        assert!(result.is_err());
        let err = result.unwrap_err().to_string();
        assert!(err.contains("permission_denied") || err.contains("outside sandbox"));
    }

    #[test]
    fn test_resolve_allows_symlink_within_sandbox() {
        let (dir, sandbox) = setup_sandbox();
        let target = dir.path().join("target.txt");
        fs::write(&target, b"target").unwrap();
        let link_path = dir.path().join("link.txt");
        symlink(&target, &link_path).unwrap();

        let resolved = sandbox.resolve("link.txt").unwrap();
        assert_eq!(resolved, target.canonicalize().unwrap());
    }

    #[test]
    fn test_resolve_with_leading_slash() {
        let (dir, sandbox) = setup_sandbox();
        let file = dir.path().join("slash_test.txt");
        fs::write(&file, b"slash").unwrap();

        let resolved = sandbox.resolve("/slash_test.txt").unwrap();
        assert_eq!(resolved, file.canonicalize().unwrap());
    }

    /// Regression test: when a client sends an absolute path whose first
    /// component matches the sandbox root's own directory name, the root
    /// must NOT be doubled. E.g., sandbox at `/root` + path `root/.bashrc`
    /// must resolve to `/root/.bashrc`, not `/root/root/.bashrc`.
    #[test]
    fn test_resolve_strips_duplicated_root_name() {
        // Create a sandbox in a parent dir whose name matches the first
        // path component we'll resolve (simulates "/root" + "root/.bashrc").
        let parent = tempfile::tempdir().unwrap();
        let root_dir_name = "testroot";
        let root_path = parent.path().join(root_dir_name);
        fs::create_dir(&root_path).unwrap();

        let sandbox = PathSandbox::new(&root_path).unwrap();

        // Create a target file inside the sandbox.
        let target = root_path.join(".bashrc");
        fs::write(&target, b"hello").unwrap();

        // 1. Relative path with root name duplicated (the failing case).
        let dup_relative = format!("{}/.bashrc", root_dir_name);
        let resolved = sandbox.resolve(&dup_relative).unwrap();
        assert_eq!(resolved, target.canonicalize().unwrap());

        // 2. Absolute path that starts with the root name.
        let dup_absolute = format!("/{}/.bashrc", root_dir_name);
        let resolved = sandbox.resolve(&dup_absolute).unwrap();
        assert_eq!(resolved, target.canonicalize().unwrap());

        // 3. Regular relative path (no duplication) still works.
        let resolved = sandbox.resolve(".bashrc").unwrap();
        assert_eq!(resolved, target.canonicalize().unwrap());

        // 4. Absolute path without root-name duplication still works.
        let resolved = sandbox.resolve("/.bashrc").unwrap();
        assert_eq!(resolved, target.canonicalize().unwrap());
    }

    #[test]
    fn test_sandbox_nonexistent_root() {
        let result = PathSandbox::new("/tmp/nession-nonexistent-dir-xyz");
        assert!(result.is_err());
    }
}

//! nession-agent – distributed tmux agent.
//!
//! The agent runs on a machine with tmux and:
//! - Accepts P2P WebSocket connections from CLI clients (the agent server)
//! - Connects to the central nession-server for discovery and coordination
//! - Sends periodic heartbeats with session metrics
//! - Watches for tmux session changes and syncs them to the server

pub mod config;
pub mod connection;
pub mod env;
pub mod fs;
pub mod server;
pub mod sync;
pub mod tmux;

//! nession-agent binary – startup logic that wires all components together.
//!
//! Startup sequence:
//! 1. Parse configuration (TOML file or defaults)
//! 2. Initialize tracing/logging
//! 3. Create TmuxManager
//! 4. Start Agent WebSocket server (P2P client connections)
//! 5. Connect to central server via ServerClient
//! 6. Start HeartbeatLoop (periodic heartbeats)
//! 7. Start SessionWatcher (session change detection)
//! 8. Wait for Ctrl+C shutdown signal
//! 9. Gracefully shut down all components

use anyhow::{Context, Result};
use nession_agent::config::AgentConfig;
use nession_agent::connection::ServerClient;
use nession_agent::server::AgentServer;
use nession_agent::sync::heartbeat::HeartbeatLoop;
use nession_agent::sync::session_watcher::SessionWatcher;
use nession_agent::tmux::manager::TmuxManager;
use nession_common::protocol::AgentMetadata;
use std::path::Path;
use std::sync::Arc;
use tracing::{error, info, warn};

#[tokio::main]
async fn main() -> Result<()> {
    // 1. Load configuration
    let config = load_config()?;

    // 2. Initialize tracing
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| tracing_subscriber::EnvFilter::new("info")),
        )
        .init();

    info!("nession-agent {} starting", env!("CARGO_PKG_VERSION"));
    info!("Agent ID: {}", config.agent_id);
    info!("Server URL: {}", config.server_url);
    info!("Listen address: {}", config.listen_address);

    // 3. Create TmuxManager
    let tmux = TmuxManager::new();

    // Check tmux availability
    match tmux.check_tmux_available().await {
        Ok(true) => info!("tmux is available"),
        Ok(false) => warn!("tmux does not appear to be available"),
        Err(e) => warn!("Could not check tmux availability: {}", e),
    }

    // 4. Start Agent WebSocket server
    let tls_option = load_tls(&config)?;
    let file_root = config
        .file_root
        .as_deref()
        .unwrap_or(&config.default_working_dir);
    let agent_id = if config.agent_id.is_empty() {
        get_hostname()
    } else {
        config.agent_id.clone()
    };
    let agent_server = AgentServer::new(
        &config.listen_address,
        &agent_id,
        tls_option,
        config.default_working_dir.clone(),
        file_root,
    )
    .context("failed to create agent server")?;
    let server_handle = agent_server
        .start()
        .await
        .context("failed to start agent server")?;
    info!(
        "Agent WebSocket server started on {}",
        config.listen_address
    );

    // 5. Connect to central server
    let hostname = get_hostname();
    // Use advertise_address (IP) if configured, otherwise auto-detect
    let ip_address = config.advertise_address.unwrap_or_else(get_ip_address);
    let port = extract_port(&config.listen_address);

    let tmux_version = get_tmux_version().await;
    let os_version = format!("{} {}", std::env::consts::OS, std::env::consts::ARCH);

    let metadata = AgentMetadata {
        tmux_version,
        os_version,
        nession_version: env!("CARGO_PKG_VERSION").to_string(),
    };

    let tmux_for_client = Arc::new(TmuxManager::new());

    // Skip server connection if server_url is empty (standalone mode).
    // The supervisor reconnects on its own, so we capture the handle and the
    // server-advertised heartbeat interval (falling back to the local config).
    let (client_handle, heartbeat_interval_secs) = if config.server_url.trim().is_empty() {
        info!("No server_url configured — running in standalone mode");
        (None, config.heartbeat_interval_secs)
    } else {
        let server_client = ServerClient::new(
            &config.server_url,
            &config.auth_token,
            &config.agent_id,
            &hostname,
            &ip_address,
            port,
            config.connect_url.clone(),
            metadata,
            tmux_for_client,
            config.default_working_dir.clone(),
        );

        // Attempt to connect with a timeout so the agent can still serve
        // local clients even if the central server is unreachable. The
        // supervisor keeps retrying in the background regardless.
        tokio::select! {
            result = server_client.connect_and_run() => {
                match result {
                    Ok((handle, server_interval)) => {
                        let interval = server_interval.unwrap_or(config.heartbeat_interval_secs);
                        info!("Connected to central server (heartbeat interval: {}s)", interval);
                        (Some(handle), interval)
                    }
                    Err(e) => {
                        error!("Failed to connect to central server: {:#}", e);
                        (None, config.heartbeat_interval_secs)
                    }
                }
            }
            _ = tokio::time::sleep(std::time::Duration::from_secs(30)) => {
                warn!("Timed out connecting to central server after 30s, continuing without sync");
                (None, config.heartbeat_interval_secs)
            }
        }
    };

    // 6. Start HeartbeatLoop
    let heartbeat_shutdown = if let Some(ref handle) = client_handle {
        let heartbeat =
            HeartbeatLoop::new(handle.clone(), TmuxManager::new(), heartbeat_interval_secs);
        let shutdown_handle = heartbeat.shutdown_handle();
        tokio::spawn(async move {
            if let Err(e) = heartbeat.run().await {
                error!("Heartbeat loop error: {:#}", e);
            }
        });
        info!(
            "Heartbeat loop started (interval: {}s)",
            heartbeat_interval_secs
        );
        Some(shutdown_handle)
    } else {
        None
    };

    // 7. Start SessionWatcher
    let watcher_shutdown = if let Some(ref handle) = client_handle {
        let watcher = SessionWatcher::new(
            handle.clone(),
            TmuxManager::new(),
            config.session_poll_interval_secs,
        );
        let shutdown_handle = watcher.shutdown_handle();
        tokio::spawn(async move {
            if let Err(e) = watcher.run().await {
                error!("Session watcher error: {:#}", e);
            }
        });
        info!(
            "Session watcher started (interval: {}s)",
            config.session_poll_interval_secs
        );
        Some(shutdown_handle)
    } else {
        None
    };

    // 8. Wait for shutdown signal (Ctrl+C or SIGTERM)
    info!("Agent is running. Press Ctrl+C to stop.");
    wait_for_shutdown().await?;
    info!("Shutdown signal received, stopping components...");

    // 9. Graceful shutdown of all components
    if let Err(e) = server_handle.shutdown().await {
        error!("Error shutting down agent server: {:#}", e);
    }
    if let Some(ref handle) = heartbeat_shutdown {
        if let Err(e) = handle.shutdown().await {
            error!("Error shutting down heartbeat loop: {:#}", e);
        }
    }
    if let Some(ref handle) = watcher_shutdown {
        if let Err(e) = handle.shutdown().await {
            error!("Error shutting down session watcher: {:#}", e);
        }
    }

    info!("nession-agent stopped");
    Ok(())
}

/// Load agent configuration from a TOML file, falling back to defaults.
fn load_config() -> Result<AgentConfig> {
    let config_path = std::env::args()
        .nth(1)
        .unwrap_or_else(|| "config.toml".to_string());

    if Path::new(&config_path).exists() {
        let config_str = std::fs::read_to_string(&config_path)
            .with_context(|| format!("failed to read config file: {config_path}"))?;
        let config: AgentConfig = toml::from_str(&config_str)
            .with_context(|| format!("failed to parse config file: {config_path}"))?;
        Ok(config)
    } else {
        info!("No config file found at '{}', using defaults", config_path);
        Ok(AgentConfig::default())
    }
}

/// Load TLS certificates from the paths specified in the config.
/// Returns `None` if no TLS paths are configured (plain WebSocket).
fn load_tls(
    config: &AgentConfig,
) -> Result<
    Option<(
        Vec<rustls::pki_types::CertificateDer<'static>>,
        rustls::pki_types::PrivateKeyDer<'static>,
    )>,
> {
    match (&config.tls_cert_path, &config.tls_key_path) {
        (Some(cert), Some(key)) => AgentServer::load_tls(Some(cert), Some(key)),
        (None, None) => Ok(None),
        _ => anyhow::bail!("both tls_cert_path and tls_key_path must be set (or both unset)"),
    }
}

/// Wait for a shutdown signal (SIGINT/SIGTERM).
async fn wait_for_shutdown() -> anyhow::Result<()> {
    #[cfg(unix)]
    {
        use tokio::signal::unix::{signal, SignalKind};
        let mut sigint =
            signal(SignalKind::interrupt()).context("failed to register SIGINT handler")?;
        let mut sigterm =
            signal(SignalKind::terminate()).context("failed to register SIGTERM handler")?;
        tokio::select! {
            _ = sigint.recv() => {
                info!("Received SIGINT");
            }
            _ = sigterm.recv() => {
                info!("Received SIGTERM");
            }
        }
    }

    #[cfg(not(unix))]
    {
        tokio::signal::ctrl_c()
            .await
            .context("failed to listen for ctrl+c")?;
        info!("Received Ctrl+C");
    }
    Ok(())
}

/// Get the system hostname.
fn get_hostname() -> String {
    // Try HOSTNAME env var first, then fall back to "unknown"
    std::env::var("HOSTNAME")
        .or_else(|_| std::env::var("HOST"))
        .unwrap_or_else(|_| "unknown".to_string())
}

/// Get the local IP address (best-effort).
fn get_ip_address() -> String {
    // Simple approach: try to determine the local IP by connecting to a
    // remote address (doesn't actually send data).
    std::net::UdpSocket::bind("0.0.0.0:0")
        .and_then(|socket| {
            socket.connect("8.8.8.8:80")?;
            socket.local_addr()
        })
        .map(|addr| addr.ip().to_string())
        .unwrap_or_else(|_| "127.0.0.1".to_string())
}

/// Extract the port number from a `host:port` address string.
fn extract_port(addr: &str) -> u16 {
    // Handle both IPv4 (host:port) and IPv6 ([host]:port) formats.
    addr.rsplit(':')
        .next()
        .and_then(|p| p.parse().ok())
        .unwrap_or(0)
}

/// Get the tmux version string by running `tmux -V`.
async fn get_tmux_version() -> String {
    tokio::process::Command::new("tmux")
        .arg("-V")
        .output()
        .await
        .ok()
        .and_then(|output| {
            if output.status.success() {
                Some(String::from_utf8_lossy(&output.stdout).trim().to_string())
            } else {
                None
            }
        })
        .unwrap_or_else(|| "unknown".to_string())
}

//! Agent WebSocket server implementation.
//!
//! Provides a [`AgentServer`] that listens for P2P client connections over
//! WebSocket (with optional TLS) and routes terminal I/O to/from per-client
//! PTY sessions. Also exposes session management operations (list, create,
//! kill) via the [`TmuxManager`].
//!
//! # Protocol
//!
//! All messages are JSON-encoded [`Message`] values exchanged as WebSocket
//! text frames. Each message carries a `msg_type` that determines how it is
//! dispatched:
//!
//! | Direction       | `msg_type`       | Purpose                          |
//! |-----------------|------------------|----------------------------------|
//! | client → agent  | `session.list`   | List tmux sessions               |
//! | client → agent  | `session.create` | Create a new tmux session        |
//! | client → agent  | `session.kill`   | Kill a tmux session              |
//! | client → agent  | `client.attach`  | Attach a PTY to a session        |
//! | client → agent  | `client.detach`  | Detach and close the PTY         |
//! | client → agent  | `terminal.input` | Send keystrokes to the PTY       |
//! | client → agent  | `terminal.resize`| Resize the PTY                   |
//! | agent → client  | `terminal.output`| PTY stdout data (base64)         |
//! | agent → client  | `error`          | Error response                   |
//! | agent → client  | `ok`             | Success response (with payload)  |

use crate::fs::ops::FileOps;
use crate::tmux::manager::{SessionInfo, TmuxManager};
use anyhow::{Context, Result};
use futures_util::{SinkExt, StreamExt};
use serde::{Deserialize, Serialize};
use std::net::SocketAddr;
use std::pin::Pin;
use std::sync::Arc;
use tokio::net::TcpListener;
use tokio::sync::{mpsc, Mutex};
use tokio_tungstenite::tungstenite::Message as WsMessage;
use tokio_tungstenite::WebSocketStream;
use tracing::{error, info, warn};

/// A stream that can be either plain TCP or TLS-wrapped.
#[allow(clippy::large_enum_variant)]
enum TcpOrTls {
    Plain(tokio::net::TcpStream),
    Tls(tokio_rustls::server::TlsStream<tokio::net::TcpStream>),
}

impl tokio::io::AsyncRead for TcpOrTls {
    fn poll_read(
        self: Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
        buf: &mut tokio::io::ReadBuf<'_>,
    ) -> std::task::Poll<std::io::Result<()>> {
        match self.get_mut() {
            TcpOrTls::Plain(s) => Pin::new(s).poll_read(cx, buf),
            TcpOrTls::Tls(s) => Pin::new(s).poll_read(cx, buf),
        }
    }
}

impl tokio::io::AsyncWrite for TcpOrTls {
    fn poll_write(
        self: Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
        buf: &[u8],
    ) -> std::task::Poll<std::io::Result<usize>> {
        match self.get_mut() {
            TcpOrTls::Plain(s) => Pin::new(s).poll_write(cx, buf),
            TcpOrTls::Tls(s) => Pin::new(s).poll_write(cx, buf),
        }
    }

    fn poll_flush(
        self: Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
    ) -> std::task::Poll<std::io::Result<()>> {
        match self.get_mut() {
            TcpOrTls::Plain(s) => Pin::new(s).poll_flush(cx),
            TcpOrTls::Tls(s) => Pin::new(s).poll_flush(cx),
        }
    }

    fn poll_shutdown(
        self: Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
    ) -> std::task::Poll<std::io::Result<()>> {
        match self.get_mut() {
            TcpOrTls::Plain(s) => Pin::new(s).poll_shutdown(cx),
            TcpOrTls::Tls(s) => Pin::new(s).poll_shutdown(cx),
        }
    }
}

// ---------------------------------------------------------------------------
// Protocol types
// ---------------------------------------------------------------------------

/// Message type constants for the agent protocol.
pub mod msg_types {
    // Client → Agent
    pub const SESSION_LIST: &str = "session.list";
    pub const SESSION_CREATE: &str = "session.create";
    pub const SESSION_KILL: &str = "session.kill";
    pub const CLIENT_ATTACH: &str = "client.attach";
