/// Protocol message envelope. All messages share this shape; `payload`
/// varies by `msg_type`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Message<P> {
    pub msg_type: String,
    pub id: String,
    pub timestamp: u64,
    pub payload: P,
}

