#[cfg(test)]
mod tests {
    use super::*;

    fn make_session(name: &str, attached: u32, windows: u32) -> SessionInfo {
        SessionInfo {
            name: name.to_string(),
            created_at: 1000,
            window_count: windows,
            attached_clients: attached,
            width: 80,
            height: 24,
        }
    }

    #[test]
    fn test_session_changed_detects_window_count_change() {
        let prev = make_session("test", 0, 1);
        let current = make_session("test", 0, 2);
        assert!(session_changed(&prev, &current));
    }

    #[test]
    fn test_session_changed_detects_attached_clients_change() {
        let prev = make_session("test", 0, 1);
        let current = make_session("test", 1, 1);
        assert!(session_changed(&prev, &current));
    }

    #[test]
    fn test_session_changed_detects_size_change() {
        let prev = make_session("test", 0, 1);
        let mut current = prev.clone();
        current.width = 120;
        current.height = 40;
        assert!(session_changed(&prev, &current));
    }

    #[test]
    fn test_session_changed_no_change() {
        let session = make_session("test", 1, 2);
        assert!(!session_changed(&session, &session));
    }

    #[test]
    fn test_session_changed_created_at_ignored() {
        // created_at differences should not trigger a change.
        let mut prev = make_session("test", 1, 2);
        let current = {
            let mut s = prev.clone();
            s.created_at = 9999;
            s
        };
        // created_at differs but nothing else.
        prev.created_at = 1000;
        assert!(!session_changed(&prev, &current));
    }
}

use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};
use std::path::PathBuf;
use tokio::fs;
use tokio::process::Command;

/// Fixed-path script names, keyed by session + env-file name so they are
/// reused (overwritten) across repeated source / unsource operations.
fn source_script_path(session: &str, name: &str) -> PathBuf {
    let safe = name.replace(['/', '\\'], "_");
    PathBuf::from(format!("/tmp/nession-source-{session}-{safe}"))
}

fn unsource_script_path(session: &str, name: &str) -> PathBuf {
    let safe = name.replace(['/', '\\'], "_");
    PathBuf::from(format!("/tmp/nession-unsource-{session}-{safe}"))
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct SessionInfo {
    pub name: String,
    pub created_at: u64,
    pub window_count: u32,
    pub attached_clients: u32,
    pub width: u16,
    pub height: u16,
}

pub struct TmuxManager;

impl TmuxManager {
    pub fn new() -> Self {
        Self
    }

    pub async fn list_sessions(&self) -> Result<Vec<SessionInfo>> {
        let output = Command::new("tmux")
            .args([
                "list-sessions",
                "-F",
                "#{session_name}\t#{session_created}\t#{session_windows}\t#{session_attached}\t#{window_width}\t#{window_height}",
            ])
            .output()
            .await?;

        if !output.status.success() {
            // tmux server not running, return empty list
            return Ok(vec![]);
        }

        let stdout = String::from_utf8_lossy(&output.stdout);
        let sessions: Vec<SessionInfo> = stdout
            .lines()
            .filter_map(|line| {
                let parts: Vec<&str> = line.split('\t').collect();
                if parts.len() == 6 {
                    Some(SessionInfo {
                        name: parts
                            .first()
                            .map(std::string::ToString::to_string)
                            .unwrap_or_default(),
                        created_at: parts.get(1).and_then(|s| s.parse().ok())?,
                        window_count: parts.get(2).and_then(|s| s.parse().ok())?,
                        attached_clients: parts.get(3).and_then(|s| s.parse().ok())?,
                        width: parts.get(4).and_then(|s| s.parse().ok())?,
                        height: parts.get(5).and_then(|s| s.parse().ok())?,
                    })
                } else {
                    None
                }
            })
            .collect();

        Ok(sessions)
    }

    pub async fn create_session(
        &self,
        name: &str,
        width: u16,
        height: u16,
        working_dir: &str,
        env: &[(String, String)],
    ) -> Result<()> {
        let mut cmd = Command::new("tmux");
        cmd.args([
            "new-session",
            "-d",
            "-s",
            name,
            "-x",
            &width.to_string(),
            "-y",
            &height.to_string(),
            "-c",
            working_dir,
        ]);

        // Inject env vars via `-e KEY=VALUE`. Supported since tmux 3.0; on older
        // tmux the flag is rejected and session creation fails loudly rather
        // than silently dropping the environment.
        for (key, value) in env {
            cmd.arg("-e").arg(format!("{key}={value}"));
        }

        let status = cmd.status().await?;

        if !status.success() {
            anyhow::bail!("Failed to create session: {name}");
        }

        Ok(())
    }

    /// Write a shell script with `export` lines and source it into the
    /// session. The command line is cleared afterwards via ANSI escape so
    /// it barely flashes on screen.
    pub async fn source_env(
        &self,
        session_name: &str,
        env_name: &str,
        vars: &[(String, String)],
    ) -> Result<()> {
        let path = source_script_path(session_name, env_name);
        let mut content = String::new();
        for (k, v) in vars {
            content.push_str(&format!("export {k}='{}'\n", v.replace('\'', "'\\''")));
        }
        fs::write(&path, &content)
            .await
            .with_context(|| format!("failed to write source script: {}", path.display()))?;

        // Leading space + HISTCONTROL=ignorespace keeps the command out of
        // shell history. ANSI \033[1A (cursor up) + \033[2K (clear line)
        // removes it from view immediately after execution.
        let cmd = format!(" . {}; printf '\\033[1A\\033[2K'", path.display());
        self.send_keys(session_name, &cmd).await
    }

    /// Write a shell script with `unset` lines and source it into the
    /// session, clearing the command from view.
    pub async fn unsource_env(
        &self,
        session_name: &str,
        env_name: &str,
        keys: &[String],
    ) -> Result<()> {
        let path = unsource_script_path(session_name, env_name);
        let content = keys.iter().fold(String::new(), |mut s, k| {
            s.push_str(&format!("unset {k}\n"));
            s
        });
        fs::write(&path, &content)
            .await
            .with_context(|| format!("failed to write unsource script: {}", path.display()))?;

        // Leading space keeps it out of history (HISTCONTROL=ignorespace).
        let cmd = format!(" . {}; printf '\\033[1A\\033[2K'", path.display());
        self.send_keys(session_name, &cmd).await
    }

    pub async fn kill_session(&self, name: &str) -> Result<()> {
        let status = Command::new("tmux")
            .args(["kill-session", "-t", name])
            .status()
            .await?;

        if !status.success() {
            anyhow::bail!("Failed to kill session: {name}");
        }

        Ok(())
    }

    pub async fn send_keys(&self, session_name: &str, keys: &str) -> Result<()> {
        let status = Command::new("tmux")
            .args(["send-keys", "-t", session_name, keys, "Enter"])
            .status()
            .await?;

        if !status.success() {
            anyhow::bail!("Failed to send keys to session: {session_name}");
        }

        Ok(())
    }

    pub async fn check_tmux_available(&self) -> Result<bool> {
        let status = Command::new("tmux").arg("-V").status().await?;

        Ok(status.success())
    }
}

impl Default for TmuxManager {
    fn default() -> Self {
        Self::new()
    }
}

use anyhow::Result;
use portable_pty::{native_pty_system, CommandBuilder, PtySize};
use std::collections::VecDeque;
use std::io::{Read, Write};
use std::sync::{Arc, Condvar, Mutex};
use std::thread;
use tokio::task;

/// Buffer shared between the PTY reader thread and `read_output` callers.
///
/// The reader thread pushes bytes into `data` and notifies via `cvar`
/// whenever new data (or EOF / error) arrives. `read_output` waits on
/// `cvar` with a bounded timeout.
struct ReadBuffer {
    /// Queued bytes ready for consumption.
    data: VecDeque<u8>,
    /// Set when the reader thread has exited (child closed or error).
    eof: bool,
    /// Last error observed by the reader thread (if any).
    error: Option<String>,
}

/// PTY control mode for real-time terminal I/O with tmux sessions.
///
/// Unlike command mode ([`TmuxManager`]), which sends discrete tmux commands,
/// `PtySession` provides a raw terminal pipe to an attached tmux session —
/// suitable for streaming keystrokes and screen updates to/from a remote
/// client over WebSocket.
///
/// Architecture: a dedicated background thread continuously reads from the
/// PTY master and buffers output into an internal ring buffer. `read_output`
/// consumes that buffer. `write_input` writes directly on a blocking thread.
/// This keeps all PTY blocking confined to dedicated OS threads, never
/// starving the tokio worker pool or deadlocking on shared mutexes.
pub struct PtySession {
    /// The master side of the PTY, kept for resize + writer cloning.
    master: Arc<Mutex<Box<dyn portable_pty::MasterPty + Send>>>,
    /// Writer half, taken once at attach time and shared for writes.
    writer: Arc<Mutex<Box<dyn Write + Send>>>,
    /// Child handle so we can wait / kill it on close.
    child: Arc<Mutex<Option<Box<dyn portable_pty::Child + Send>>>>,
    /// Shared read buffer fed by the background reader thread.
    read_buf: Arc<(Mutex<ReadBuffer>, Condvar)>,
    /// Session name this PTY is attached to.
    session_name: String,
    /// Whether the session has been closed.
    closed: Arc<Mutex<bool>>,
    /// Handle to the reader thread so we can join it on close.
    reader_handle: Arc<Mutex<Option<thread::JoinHandle<()>>>>,
}

impl PtySession {
    /// Internal helper: open a PTY and spawn a command on its slave side.
    async fn spawn_inner(
        cmd: CommandBuilder,
        session_name: String,
        width: u16,
        height: u16,
    ) -> Result<Self> {
        let pty_system = native_pty_system();

        let size = PtySize {
            rows: height,
            cols: width,
            pixel_width: 0,
            pixel_height: 0,
        };

        let pair = pty_system.openpty(size)?;

        let pair_master = pair.master;
        let pair_slave = pair.slave;

        pair_master.resize(size)?;

        // Take the writer once (portable-pty's `take_writer` consumes the
        // write slot). Readers are cloned on demand for the background
        // reader thread.
        let writer = pair_master.take_writer()?;

        // Spawn the child on the slave side of the PTY.
        let child = pair_slave.spawn_command(cmd)?;
        // The slave side is no longer needed once the child is spawned.
        drop(pair_slave);

        let master = Arc::new(Mutex::new(pair_master));
        let read_buf = Arc::new((
            Mutex::new(ReadBuffer {
                data: VecDeque::new(),
                eof: false,
                error: None,
            }),
            Condvar::new(),
        ));

        // Spawn a dedicated OS thread to continuously drain the PTY.
        let reader_buf_clone = Arc::clone(&read_buf);
        let reader_master_clone = Arc::clone(&master);
        let reader_handle = thread::Builder::new()
            .name(format!("nession-pty-reader-{session_name}"))
            .spawn(move || {
                // Clone a reader from the master once, then loop reading
                // 4 KiB chunks. The lock on `master` is held only for the
                // duration of the clone.
                let mut reader = match reader_master_clone
                    .lock()
                    .ok()
                    .and_then(|m| m.try_clone_reader().ok())
                {
                    Some(r) => r,
                    None => {
                        let (lock, cvar) = &*reader_buf_clone;
                        let mut buf = lock
                            .lock()
                            .unwrap_or_else(std::sync::PoisonError::into_inner);
                        buf.error = Some("failed to clone PTY reader".into());
                        buf.eof = true;
                        cvar.notify_all();
                        return;
                    }
                };
                // Drop the master lock — the reader we hold is independent.
                drop(reader_master_clone);

                let mut chunk = [0u8; 4096];
                loop {
                    let n = match reader.read(&mut chunk) {
                        Ok(0) => {
                            // EOF
                            let (lock, cvar) = &*reader_buf_clone;
                            let mut buf = lock
                                .lock()
                                .unwrap_or_else(std::sync::PoisonError::into_inner);
                            buf.eof = true;
                            cvar.notify_all();
                            return;
                        }
                        Ok(n) => n,
                        Err(e) => {
                            let (lock, cvar) = &*reader_buf_clone;
                            let mut buf = lock
                                .lock()
                                .unwrap_or_else(std::sync::PoisonError::into_inner);
                            buf.error = Some(e.to_string());
                            buf.eof = true;
                            cvar.notify_all();
                            return;
                        }
                    };
                    let (lock, cvar) = &*reader_buf_clone;
                    let mut buf = lock
                        .lock()
                        .unwrap_or_else(std::sync::PoisonError::into_inner);
                    buf.data.extend(chunk.get(..n).unwrap_or(&[]));
                    cvar.notify_all();
                }
            })
            .map_err(|e| anyhow::anyhow!("failed to spawn PTY reader thread: {e}"))?;

        Ok(Self {
            master,
            writer: Arc::new(Mutex::new(writer)),
            child: Arc::new(Mutex::new(Some(child))),
            read_buf,
            session_name,
            closed: Arc::new(Mutex::new(false)),
            reader_handle: Arc::new(Mutex::new(Some(reader_handle))),
        })
    }

    /// Attach to a tmux session by spawning `tmux attach-session` inside a PTY.
    ///
    /// The child process inherits the slave side of the PTY; the master side
    /// is retained here for read/write/resize operations.
    ///
    /// Two session options are set before attaching (both best-effort):
    ///
    /// - `status off` — the web UI renders its own session header, so tmux's
    ///   status bar is redundant; worse, over a raw PTY pipe its periodic
    ///   redraws (every `status-interval`) accumulate in the terminal
    ///   scrollback instead of overwriting in place, producing repeated
    ///   `[session] 0:bash* …` lines.
    /// - `mouse on` — makes tmux handle wheel events itself (entering
    ///   copy-mode / scrolling its scrollback). Without it, xterm.js forwards
    ///   the wheel to the PTY as arrow-key escapes, which the shell interprets
    ///   as ↑/↓ command-history navigation. tmux defaults to `mouse off`, so
    ///   the container agent needs this even though a developer's local
    ///   `~/.tmux.conf` may already enable it.
    pub async fn attach(session_name: &str, width: u16, height: u16) -> Result<Self> {
        // Apply per-session display options (idempotent, best-effort).
        // Failure here shouldn't block attaching — fall through to attach.
        for (option, value) in [("status", "off"), ("mouse", "on")] {
            let _ = tokio::process::Command::new("tmux")
                .args(["set-option", "-t", session_name, option, value])
                .status()
                .await;
        }

        let mut cmd = CommandBuilder::new("tmux");
        cmd.args(["attach-session", "-t", session_name]);
        // tmux requires TERM to be set when attaching via PTY
        cmd.env("TERM", "xterm-256color");
        Self::spawn_inner(cmd, session_name.to_string(), width, height).await
    }

    /// Create a PtySession with an arbitrary command.
    ///
    /// This is primarily useful for testing without requiring a real tmux
    /// session. In production code, prefer [`attach`].
    pub async fn spawn_command(
        program: &str,
        args: &[&str],
        width: u16,
        height: u16,
    ) -> Result<Self> {
        let mut cmd = CommandBuilder::new(program);
        cmd.args(args);
        let session_name = format!("[test:{program}]");
        Self::spawn_inner(cmd, session_name, width, height).await
    }

    /// Read terminal output from the PTY's stdout.
    ///
    /// Returns:
    /// - `Ok(n > 0)` — `n` bytes were copied into `buf`.
    /// - `Ok(0)` — true EOF (the child exited).
    /// - `Err(PtyError::Timeout)` — no data within `timeout_ms`; caller
    ///   should retry.
    /// - `Err(other)` — an I/O error occurred.
    ///
    /// Runs entirely in `spawn_blocking` against the internal read buffer,
    /// so it never blocks a tokio worker longer than the timeout.
    pub async fn read_output(&self, buf: &mut [u8], timeout_ms: u64) -> Result<usize> {
        let read_buf = Arc::clone(&self.read_buf);
        let ptr_addr = buf.as_mut_ptr() as usize;
        let len = buf.len();
        let n = task::spawn_blocking(move || {
            let (lock, cvar) = &*read_buf;
            let mut guard = lock
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);

            // Wait for data or EOF, bounded by timeout.
            let deadline = std::time::Instant::now() + std::time::Duration::from_millis(timeout_ms);
            while guard.data.is_empty() && !guard.eof {
                let now = std::time::Instant::now();
                if now >= deadline {
                    break;
                }
                let wait_result = cvar
                    .wait_timeout(guard, deadline - now)
                    .unwrap_or_else(std::sync::PoisonError::into_inner);
                guard = wait_result.0;
            }

            if let Some(err) = guard.error.as_ref() {
                if guard.data.is_empty() {
                    return Err(anyhow::anyhow!("PTY reader error: {err}"));
                }
            }

            // Distinguish true EOF from a timeout-with-no-data.
            // If data is empty AND not EOF, we simply timed out — return
            // a specific error so the caller can retry rather than
            // treating this as stream end.
            if guard.data.is_empty() {
                if guard.eof {
                    return Ok(0); // true EOF
                } else {
                    return Err(anyhow::anyhow!("PTY_READ_TIMEOUT"));
                }
            }

            let to_copy = guard.data.len().min(len);
            if to_copy > 0 {
                let ptr = ptr_addr as *mut u8;
                let slice = unsafe { std::slice::from_raw_parts_mut(ptr, len) };
                for slot in slice.iter_mut().take(to_copy) {
                    *slot = guard.data.pop_front().unwrap_or(0);
                }
            }
            Ok(to_copy)
        })
        .await??;
        Ok(n)
    }

    /// Write terminal input to the PTY's stdin.
    pub async fn write_input(&self, data: &[u8]) -> Result<usize> {
        let writer = Arc::clone(&self.writer);
        let data = data.to_vec();
        let n = task::spawn_blocking(move || {
            let mut guard = writer
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            guard.write_all(&data)?;
            guard.flush()?;
            Ok::<usize, anyhow::Error>(data.len())
        })
        .await??;
        Ok(n)
    }

    /// Resize the terminal. Sends SIGWINCH to the child via the PTY master.
    pub async fn resize(&self, width: u16, height: u16) -> Result<()> {
        let master = Arc::clone(&self.master);
        let size = PtySize {
            rows: height,
            cols: width,
            pixel_width: 0,
            pixel_height: 0,
        };
        task::spawn_blocking(move || {
            let guard = master
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            guard.resize(size)?;
            Ok::<(), anyhow::Error>(())
        })
        .await??;
        Ok(())
    }

    /// Clean up the PTY connection: terminate the child and mark the session
    /// as closed. Idempotent.
    pub async fn close(&self) -> Result<()> {
        let already = {
            let mut closed = self
                .closed
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            if *closed {
                true
            } else {
                *closed = true;
                false
            }
        };
        if already {
            return Ok(());
        }

        let child = Arc::clone(&self.child);
        let reader_handle = Arc::clone(&self.reader_handle);
        task::spawn_blocking(move || {
            // Kill the child first so the reader thread sees EOF.
            let mut child_guard = child
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            if let Some(mut c) = child_guard.take() {
                let _ = c.kill();
                let _ = c.wait();
            }
            drop(child_guard);

            // Join the reader thread (it should exit soon after the child dies).
            let mut handle_guard = reader_handle
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            if let Some(h) = handle_guard.take() {
                let _ = h.join();
            }
        })
        .await?;
        Ok(())
    }

    /// The tmux session name this PTY is attached to.
    pub fn session_name(&self) -> &str {
        &self.session_name
    }

    /// Whether `close()` has been called.
    pub async fn is_closed(&self) -> bool {
        *self
            .closed
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
    }
}

impl Drop for PtySession {
    fn drop(&mut self) {
        let already = {
            let mut closed = match self.closed.lock() {
                Ok(c) => c,
                Err(p) => p.into_inner(),
            };
            if *closed {
                true
            } else {
                *closed = true;
                false
            }
        };
        if already {
            return;
        }

        // Best-effort kill of the child, then join the reader thread.
        if let Ok(mut child_guard) = self.child.lock() {
            if let Some(mut c) = child_guard.take() {
                let _ = c.kill();
            }
        }
        // We intentionally do NOT join the reader thread in Drop: joining
        // blocks, and Drop must not block. The thread will observe EOF
        // once the child's slave side is closed by the kernel on process
        // exit, and will clean itself up.
    }
}

//! Client WebSocket connection to central server.

use anyhow::{Context, Result};
use futures_util::{SinkExt, StreamExt};
use serde_json::json;
use std::time::{SystemTime, UNIX_EPOCH};
use tokio::net::TcpStream;
use tokio_tungstenite::{
    connect_async, tungstenite::protocol::Message, MaybeTlsStream, WebSocketStream,
};
use tracing::{debug, info};

/// Client connection to the central server.
#[derive(Debug)]
pub struct ClientConnection {
    ws_stream: WebSocketStream<MaybeTlsStream<TcpStream>>,
    authenticated: bool,
}

/// Agent information returned from the server.
#[derive(Debug, Clone, serde::Deserialize)]
#[allow(dead_code)]
pub struct AgentInfo {
    pub agent_id: String,
    pub hostname: String,
    pub ip_address: String,
    pub port: u16,
    pub status: String,
    pub session_count: u32,
    pub last_heartbeat: String,
}

/// Session information returned from the server.
#[derive(Debug, Clone, serde::Deserialize)]
pub struct SessionInfo {
    pub session_id: String,
    pub agent_id: String,
    pub session_name: String,
    pub status: String,
    pub window_count: u32,
    pub attached_clients: u32,
}

/// P2P connection info returned from the server for direct agent connection.
#[derive(Debug, Clone, serde::Deserialize)]
pub struct P2PAttachInfo {
    pub agent_address: String,
    #[allow(dead_code)]
    pub connection_token: String,
    pub session_name: String,
}

/// Result of an attach request to the central server.
#[derive(Debug, Clone)]
pub enum AttachResponse {
    /// P2P mode: connect directly to agent at the given address.
    P2P(P2PAttachInfo),
    /// Relay mode: the server is relaying I/O on the existing connection.
    Relay,
}

impl ClientConnection {
    /// Connect to the server with WebSocket (supports TLS).
    pub async fn connect(server_url: &str, auth_token: &str) -> Result<Self> {
        info!("Connecting to server: {}", server_url);

        let (ws_stream, _) = connect_async(server_url)
            .await
            .with_context(|| format!("Failed to connect to server at {server_url}"))?;

        info!("WebSocket connection established");

        let mut conn = Self {
            ws_stream,
            authenticated: false,
        };

        // Authenticate
        conn.authenticate(auth_token).await?;

        Ok(conn)
    }

    /// Authenticate with the server.
    async fn authenticate(&mut self, auth_token: &str) -> Result<()> {
        let msg_id = format!(
            "auth_{}",
            SystemTime::now().duration_since(UNIX_EPOCH)?.as_millis()
        );
        let timestamp = SystemTime::now().duration_since(UNIX_EPOCH)?.as_secs();

        let auth_msg = json!({
            "msg_type": "client.auth",
            "id": msg_id,
            "timestamp": timestamp,
            "payload": {
                "auth_token": auth_token
            }
        });

        debug!("Sending auth message: {}", auth_msg);
        self.ws_stream
            .send(Message::Text(auth_msg.to_string()))
            .await?;

        // Wait for auth response
        if let Some(msg) = self.ws_stream.next().await {
            match msg {
                Ok(Message::Text(text)) => {
                    let response: serde_json::Value = serde_json::from_str(&text)?;
                    let msg_type = response
                        .get("msg_type")
                        .and_then(|v| v.as_str())
                        .unwrap_or("");

                    if msg_type == "client.auth.response" {
                        let status = response
                            .get("payload")
                            .and_then(|v| v.get("status"))
                            .and_then(|v| v.as_str())
                            .unwrap_or("");
                        let message = response
                            .get("payload")
                            .and_then(|v| v.get("message"))
                            .and_then(|v| v.as_str())
                            .unwrap_or("");

                        if status == "success" {
                            self.authenticated = true;
                            info!("Authentication successful");
                            Ok(())
                        } else {
                            anyhow::bail!("Authentication failed: {message}")
                        }
                    } else {
                        anyhow::bail!(
                            "Unexpected response: expected client.auth.response, got {msg_type}"
                        )
                    }
                }
                Ok(_) => anyhow::bail!("Unexpected message type from server"),
                Err(e) => anyhow::bail!("Error receiving auth response: {e}"),
            }
        } else {
            anyhow::bail!("Server closed connection during authentication")
        }
    }

    /// List all agents from the server.
    pub async fn list_agents(&mut self) -> Result<Vec<AgentInfo>> {
        if !self.authenticated {
            anyhow::bail!("Not authenticated");
        }

        let msg_id = format!(
            "agents_{}",
            SystemTime::now().duration_since(UNIX_EPOCH)?.as_millis()
        );
        let timestamp = SystemTime::now().duration_since(UNIX_EPOCH)?.as_secs();

        let request = json!({
            "msg_type": "client.agents.list",
            "id": msg_id,
            "timestamp": timestamp,
            "payload": {}
        });

        debug!("Sending agents list request: {}", request);
        self.ws_stream
            .send(Message::Text(request.to_string()))
            .await?;

        // Wait for response
        if let Some(msg) = self.ws_stream.next().await {
            match msg {
                Ok(Message::Text(text)) => {
                    let response: serde_json::Value = serde_json::from_str(&text)?;
                    let msg_type = response
                        .get("msg_type")
                        .and_then(|v| v.as_str())
                        .unwrap_or("");

                    if msg_type == "client.agents.list.response" {
                        let agents: Vec<AgentInfo> = serde_json::from_value(
                            response
                                .get("payload")
                                .and_then(|v| v.get("agents"))
                                .cloned()
                                .unwrap_or(serde_json::Value::Null),
                        )?;
                        Ok(agents)
                    } else {
                        anyhow::bail!(
                            "Unexpected response: expected client.agents.list.response, got {msg_type}"
                        )
                    }
                }
                Ok(_) => anyhow::bail!("Unexpected message type from server"),
                Err(e) => anyhow::bail!("Error receiving agents list: {e}"),
            }
        } else {
            anyhow::bail!("Server closed connection")
        }
    }

    /// List all sessions from the server, optionally filtered by agent_id.
    pub async fn list_sessions(&mut self, agent_id: Option<&str>) -> Result<Vec<SessionInfo>> {
        if !self.authenticated {
            anyhow::bail!("Not authenticated");
        }

        let msg_id = format!(
            "sessions_{}",
            SystemTime::now().duration_since(UNIX_EPOCH)?.as_millis()
        );
        let timestamp = SystemTime::now().duration_since(UNIX_EPOCH)?.as_secs();

        let mut payload = json!({});
        if let Some(agent) = agent_id {
            if let Some(obj) = payload.as_object_mut() {
                obj.insert("agent_id".to_string(), json!(agent));
            }
        }

        let request = json!({
            "msg_type": "client.sessions.list",
            "id": msg_id,
            "timestamp": timestamp,
            "payload": payload
        });

        debug!("Sending sessions list request: {}", request);
        self.ws_stream
            .send(Message::Text(request.to_string()))
            .await?;

        // Wait for response
        if let Some(msg) = self.ws_stream.next().await {
            match msg {
                Ok(Message::Text(text)) => {
                    let response: serde_json::Value = serde_json::from_str(&text)?;
                    let msg_type = response
                        .get("msg_type")
                        .and_then(|v| v.as_str())
                        .unwrap_or("");

                    if msg_type == "client.sessions.list.response" {
                        let sessions: Vec<SessionInfo> = serde_json::from_value(
                            response
                                .get("payload")
                                .and_then(|v| v.get("sessions"))
                                .cloned()
                                .unwrap_or(serde_json::Value::Null),
                        )?;
                        Ok(sessions)
                    } else {
                        anyhow::bail!(
                            "Unexpected response: expected client.sessions.list.response, got {msg_type}"
                        )
                    }
                }
                Ok(_) => anyhow::bail!("Unexpected message type from server"),
                Err(e) => anyhow::bail!("Error receiving sessions list: {e}"),
            }
        } else {
            anyhow::bail!("Server closed connection")
        }
    }

    /// Request to attach to a session. Sends `client.session.attach` with the
    /// given preferred mode. Returns either P2P connection info (to connect
    /// directly to the agent) or Relay (the server relays I/O).
    pub async fn request_attach(
        &mut self,
        session_id: &str,
        preferred_mode: &str,
    ) -> Result<AttachResponse> {
        if !self.authenticated {
            anyhow::bail!("Not authenticated");
        }

        let msg_id = format!(
            "attach_{}",
            SystemTime::now().duration_since(UNIX_EPOCH)?.as_millis()
        );
        let timestamp = SystemTime::now().duration_since(UNIX_EPOCH)?.as_secs();

        let request = json!({
            "msg_type": "client.session.attach",
            "id": msg_id,
            "timestamp": timestamp,
            "payload": {
                "session_id": session_id,
                "preferred_mode": preferred_mode
            }
        });

        debug!("Sending session attach request: {}", request);
        self.ws_stream
            .send(Message::Text(request.to_string()))
            .await?;

        // Wait for response
        if let Some(msg) = self.ws_stream.next().await {
            match msg {
                Ok(Message::Text(text)) => {
                    let response: serde_json::Value = serde_json::from_str(&text)?;
                    let msg_type = response
                        .get("msg_type")
                        .and_then(|v| v.as_str())
                        .unwrap_or("");

                    if msg_type != "client.session.attach.response" {
                        anyhow::bail!(
                            "Unexpected response: expected client.session.attach.response, got {msg_type}"
                        );
                    }

                    let status = response
                        .get("payload")
                        .and_then(|v| v.get("status"))
                        .and_then(|v| v.as_str())
                        .unwrap_or("");
                    if status != "success" {
                        let message = response
                            .get("payload")
                            .and_then(|v| v.get("message"))
                            .and_then(|v| v.as_str())
                            .unwrap_or("unknown error");
                        anyhow::bail!("Attach request failed: {message}");
                    }

                    let mode = response
                        .get("payload")
                        .and_then(|v| v.get("mode"))
                        .and_then(|v| v.as_str())
                        .unwrap_or("relay");
                    if mode == "relay" {
                        Ok(AttachResponse::Relay)
                    } else {
                        let p2p: P2PAttachInfo = serde_json::from_value(
                            response
                                .get("payload")
                                .cloned()
                                .unwrap_or(serde_json::Value::Null),
                        )?;
                        Ok(AttachResponse::P2P(p2p))
                    }
                }
                Ok(_) => anyhow::bail!("Unexpected message type from server"),
                Err(e) => anyhow::bail!("Error receiving attach response: {e}"),
            }
        } else {
            anyhow::bail!("Server closed connection")
        }
    }

    /// Split the underlying WebSocket stream for relay-mode terminal I/O.
    /// Returns (sink, stream) halves that can be used as a TerminalTransport.
    pub fn into_relay_transport(self) -> WebSocketStream<MaybeTlsStream<TcpStream>> {
        self.ws_stream
    }

    /// Close the connection gracefully.
    pub async fn close(&mut self) -> Result<()> {
        info!("Closing connection");
        self.ws_stream.close(None).await?;
        Ok(())
    }
}

/// Connect to an agent's WebSocket server for P2P terminal I/O.
/// `agent_address` is a complete WebSocket URL (e.g. "ws://agent.example.com/ws").
/// Returns the WebSocketStream for use as a TerminalTransport.
pub async fn connect_to_agent(
    agent_address: &str,
) -> Result<WebSocketStream<MaybeTlsStream<TcpStream>>> {
    info!("Connecting to agent at: {}", agent_address);

    let (ws_stream, _) = connect_async(agent_address)
        .await
        .with_context(|| format!("Failed to connect to agent at {agent_address}"))?;

    info!("Agent WebSocket connection established");
    Ok(ws_stream)
}

/// Create a new tmux session directly on an agent via its WebSocket server.
///
/// Connects to the agent at `agent_address` (host:port), sends a
/// `session.create` message, and waits for the response. The agent does not
/// require authentication for management operations.
///
/// Returns the name of the created session on success.
pub async fn create_session_on_agent(
    agent_address: &str,
    session_name: &str,
    width: u16,
    height: u16,
) -> Result<String> {
    use futures_util::StreamExt;

    let url = format!("ws://{agent_address}");
    info!("Connecting to agent at {} to create session", url);

    let (mut ws_stream, _) = connect_async(&url)
        .await
        .with_context(|| format!("Failed to connect to agent at {url}"))?;

    let msg_id = format!(
        "create_{}",
        SystemTime::now().duration_since(UNIX_EPOCH)?.as_millis()
    );
    let timestamp = SystemTime::now().duration_since(UNIX_EPOCH)?.as_secs();

    let request = json!({
        "msg_type": "session.create",
        "id": msg_id,
        "timestamp": timestamp,
        "payload": {
            "name": session_name,
            "width": width,
            "height": height
        }
    });

    debug!("Sending session.create to agent: {}", request);
    ws_stream
        .send(Message::Text(request.to_string()))
        .await
        .with_context(|| "Failed to send session.create to agent")?;

    // Wait for response
    if let Some(msg) = ws_stream.next().await {
        match msg {
            Ok(Message::Text(text)) => {
                let response: serde_json::Value = serde_json::from_str(&text)?;
                let resp_type = response
                    .get("msg_type")
                    .and_then(|v| v.as_str())
                    .unwrap_or("");

                if resp_type == "ok" {
                    let name = response
                        .get("payload")
                        .and_then(|v| v.get("name"))
                        .and_then(|v| v.as_str())
                        .unwrap_or(session_name)
                        .to_string();
                    info!("Session '{}' created on agent", name);
                    Ok(name)
                } else if resp_type == "error" {
                    let code = response
                        .get("payload")
                        .and_then(|v| v.get("code"))
                        .and_then(|v| v.as_str())
                        .unwrap_or("unknown");
                    let message = response
                        .get("payload")
                        .and_then(|v| v.get("message"))
                        .and_then(|v| v.as_str())
                        .unwrap_or("unknown error");
                    anyhow::bail!("Agent error ({code}): {message}")
                } else {
                    anyhow::bail!(
                        "Unexpected response from agent: expected 'ok' or 'error', got '{resp_type}'"
                    )
                }
            }
            Ok(_) => anyhow::bail!("Unexpected message type from agent"),
            Err(e) => anyhow::bail!("Error receiving response from agent: {e}"),
        }
    } else {
        anyhow::bail!("Agent closed connection during session creation")
    }
}

/// Kill a tmux session directly on an agent via its WebSocket server.
///
/// Connects to the agent at `agent_address` (host:port), sends a
/// `session.kill` message, and waits for the response.
///
/// Returns the name of the killed session on success.
pub async fn kill_session_on_agent(agent_address: &str, session_name: &str) -> Result<String> {
    use futures_util::StreamExt;

