    let request = json!({
        "msg_type": "session.kill",
        "id": msg_id,
        "timestamp": timestamp,
        "payload": {
            "name": session_name
        }
    });

    debug!("Sending session.kill to agent: {}", request);
    ws_stream
        .send(Message::Text(request.to_string()))
        .await
        .with_context(|| "Failed to send session.kill to agent")?;

    // Wait for response
    if let Some(msg) = ws_stream.next().await {
        match msg {
            Ok(Message::Text(text)) => {
                let response: serde_json::Value = serde_json::from_str(&text)?;
                let resp_type = response
                    .get("msg_type")
                    .and_then(|v| v.as_str())
                    .unwrap_or("");

                if resp_type == "ok" {
                    let name = response
                        .get("payload")
                        .and_then(|v| v.get("name"))
                        .and_then(|v| v.as_str())
                        .unwrap_or(session_name)
                        .to_string();
                    info!("Session '{}' killed on agent", name);
                    Ok(name)
                } else if resp_type == "error" {
                    let code = response
                        .get("payload")
                        .and_then(|v| v.get("code"))
                        .and_then(|v| v.as_str())
                        .unwrap_or("unknown");
                    let message = response
                        .get("payload")
                        .and_then(|v| v.get("message"))
                        .and_then(|v| v.as_str())
                        .unwrap_or("unknown error");
                    anyhow::bail!("Agent error ({code}): {message}")
                } else {
                    anyhow::bail!(
                        "Unexpected response from agent: expected 'ok' or 'error', got '{resp_type}'"
                    )
                }
            }
            Ok(_) => anyhow::bail!("Unexpected message type from agent"),
            Err(e) => anyhow::bail!("Error receiving response from agent: {e}"),
        }
    } else {
        anyhow::bail!("Agent closed connection during session kill")
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::net::SocketAddr;
    use tokio::net::TcpListener;
    use tokio_tungstenite::accept_async;

    /// Start a mock WebSocket server that accepts connections and echoes messages.
    async fn start_mock_server(port: u16) -> (tokio::task::JoinHandle<()>, SocketAddr) {
        let listener = TcpListener::bind(format!("127.0.0.1:{}", port))
            .await
            .expect("failed to bind mock server");
        let addr = listener.local_addr().unwrap();

        let handle = tokio::spawn(async move {
            if let Ok((stream, _)) = listener.accept().await {
                let ws = accept_async(stream).await.expect("failed to accept ws");
                let (mut sink, mut stream) = ws.split();

                // Echo messages back
                while let Some(Ok(msg)) = stream.next().await {
                    if let Message::Text(text) = msg {
                        let parsed: serde_json::Value = serde_json::from_str(&text).unwrap();
                        let msg_type = parsed
                            .get("msg_type")
                            .and_then(|v| v.as_str())
                            .unwrap_or("");

                        let response = match msg_type {
                            "client.auth" => {
                                let token = parsed
                                    .get("payload")
                                    .and_then(|v| v.get("auth_token"))
                                    .and_then(|v| v.as_str())
                                    .unwrap_or("");

                                if token == "valid_token" {
                                    json!({
                                        "msg_type": "client.auth.response",
                                        "id": parsed.get("id").unwrap(),
                                        "timestamp": 0,
                                        "payload": {
                                            "status": "success",
                                            "message": "ok"
                                        }
                                    })
                                } else {
                                    json!({
                                        "msg_type": "client.auth.response",
                                        "id": parsed.get("id").unwrap(),
                                        "timestamp": 0,
                                        "payload": {
                                            "status": "failed",
                                            "message": "invalid token"
                                        }
                                    })
                                }
                            }
                            "client.agents.list" => {
                                json!({
                                    "msg_type": "client.agents.list.response",
                                    "id": parsed.get("id").unwrap(),
                                    "timestamp": 0,
                                    "payload": {
                                        "agents": [
                                            {
                                                "agent_id": "agent1",
                                                "hostname": "host1",
                                                "ip_address": "127.0.0.1",
                                                "port": 8080,
                                                "status": "online",
                                                "session_count": 2,
                                                "last_heartbeat": "2024-01-01T00:00:00Z"
                                            }
                                        ]
                                    }
                                })
                            }
                            "client.sessions.list" => {
