                                    .get("payload")
                                    .and_then(|v| v.get("preferred_mode"))
                                    .and_then(|v| v.as_str())
                                    .unwrap_or("auto");

                                if preferred_mode == "relay" {
                                    json!({
                                        "msg_type": "client.session.attach.response",
                                        "id": parsed.get("id").unwrap(),
                                        "timestamp": 0,
                                        "payload": {
                                            "status": "success",
                                            "mode": "relay"
                                        }
                                    })
                                } else {
                                    json!({
                                        "msg_type": "client.session.attach.response",
                                        "id": parsed.get("id").unwrap(),
                                        "timestamp": 0,
                                        "payload": {
                                            "status": "success",
                                            "mode": "p2p",
                                            "agent_address": "ws://127.0.0.1:9090",
                                            "connection_token": "token123",
                                            "session_name": "session1"
                                        }
                                    })
                                }
                            }
                            _ => {
