    /// Start a mock agent server for testing create_session_on_agent and kill_session_on_agent
    async fn start_mock_agent_server(port: u16) -> (tokio::task::JoinHandle<()>, SocketAddr) {
        let listener = TcpListener::bind(format!("127.0.0.1:{}", port))
            .await
            .expect("failed to bind mock agent server");
        let addr = listener.local_addr().unwrap();

        let handle = tokio::spawn(async move {
            if let Ok((stream, _)) = listener.accept().await {
                let ws = accept_async(stream).await.expect("failed to accept ws");
                let (mut sink, mut stream) = ws.split();

                // Echo messages back
                while let Some(Ok(msg)) = stream.next().await {
                    if let Message::Text(text) = msg {
                        let parsed: serde_json::Value = serde_json::from_str(&text).unwrap();
                        let msg_type = parsed
                            .get("msg_type")
                            .and_then(|v| v.as_str())
                            .unwrap_or("");

                        let response = match msg_type {
                            "session.create" => {
                                let name = parsed
                                    .get("payload")
                                    .and_then(|v| v.get("name"))
                                    .and_then(|v| v.as_str())
                                    .unwrap_or("unknown");

                                json!({
                                    "msg_type": "ok",
                                    "id": parsed.get("id").unwrap(),
                                    "timestamp": 0,
                                    "payload": {
                                        "name": name
                                    }
                                })
                            }
                            "session.kill" => {
                                let name = parsed
                                    .get("payload")
                                    .and_then(|v| v.get("name"))
                                    .and_then(|v| v.as_str())
                                    .unwrap_or("unknown");

                                json!({
                                    "msg_type": "ok",
                                    "id": parsed.get("id").unwrap(),
                                    "timestamp": 0,
                                    "payload": {
                                        "name": name
                                    }
                                })
                            }
                            _ => {
                                json!({
                                    "msg_type": "error",
                                    "id": parsed.get("id").unwrap(),
                                    "timestamp": 0,
                                    "payload": {
                                        "code": "unknown_message_type",
                                        "message": format!("unknown message type: {}", msg_type)
                                    }
                                })
                            }
                        };

                        let _ = sink.send(Message::Text(response.to_string())).await;
                    }
                }
            }
        });

        (handle, addr)
    }

