//! Agent CLI commands implementation.

use crate::utils::{pid_file, process};
use anyhow::{Context, Result};
use nession_agent::config::AgentConfig;
use std::fs;
use std::path::Path;
use std::process::{Command, Stdio};
use std::time::Duration;
use tracing::{error, info};

/// Start the agent process.
pub async fn start(config_path: String, foreground: bool, pid_file: String) -> Result<()> {
    // Ensure component directories exist before any file operations (PID file)
    nession_common::paths::ensure_component_dirs()
        .context("failed to create nession component directories")?;

    // Check if agent is already running
    if let Ok(pid) = pid_file::read_pid_file(&pid_file) {
        if pid_file::is_process_running(pid) {
            anyhow::bail!("Agent is already running with PID {pid}");
        } else {
            // Process not running but PID file exists, clean it up
            let _ = fs::remove_file(&pid_file);
        }
    }

    // Load configuration
    let config = load_agent_config(&config_path)?;

    if foreground {
        // Run in foreground
        info!("Starting agent in foreground mode");
        println!("Starting nession-agent with config: {config_path}");
        println!("Agent ID: {}", config.agent_id);
        println!("Press Ctrl+C to stop");

        // Write PID file for the current process (foreground mode)
        let pid = std::process::id();
        pid_file::write_pid_file(&pid_file, pid)?;

        // Run the agent directly (this will block)
        let result = run_agent_foreground(config).await;

        // Clean up PID file on exit
        let _ = fs::remove_file(&pid_file);

        result?;
    } else {
        // Run in background
        info!("Starting agent in background mode");

        // Get current executable path
        let exe = std::env::current_exe()?;

        // Spawn the agent process with proper daemonization on Unix
        let mut cmd = Command::new(&exe);
        cmd.args(["agent", "start", "--config", &config_path, "--foreground"])
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null());

        // On Unix, detach the child process from the parent's session
        #[cfg(unix)]
        {
            use std::os::unix::process::CommandExt;
            unsafe {
                cmd.pre_exec(|| {
                    // Create a new session to detach from parent
                    libc::setsid();
                    Ok(())
                });
            }
        }

        let _child = cmd.spawn().context("failed to spawn agent process")?;

        // Give the child a moment to write its PID file
        tokio::time::sleep(Duration::from_millis(500)).await;

        // Read the PID from the file written by the child
        match pid_file::read_pid_file(&pid_file) {
            Ok(pid) => {
                println!("Agent started in background with PID {pid}");
                println!("PID file: {pid_file}");
            }
            Err(_) => {
                println!("Agent started in background (waiting for PID file...)");
                // Wait a bit more and try again
                tokio::time::sleep(Duration::from_secs(1)).await;
                if let Ok(pid) = pid_file::read_pid_file(&pid_file) {
                    println!("Agent started in background with PID {pid}");
                } else {
                    println!("Agent is starting, check logs for status");
                }
            }
        }
        println!("Config: {config_path}");
    }

    Ok(())
}

/// Stop the agent process.
pub async fn stop(pid_file: String) -> Result<()> {
    // Read PID file
    let pid = match pid_file::read_pid_file(&pid_file) {
        Ok(pid) => pid,
        Err(_) => {
            println!("Agent is not running (no PID file found)");
            return Ok(());
        }
    };

    // Check if process is running
    if !pid_file::is_process_running(pid) {
        println!("Agent process {pid} is not running");
        // Clean up stale PID file
        let _ = fs::remove_file(&pid_file);
        return Ok(());
    }

    println!("Stopping agent (PID {pid})...");

    // Send SIGTERM
    #[cfg(unix)]
    {
        use nix::sys::signal::{kill, Signal};
        use nix::unistd::Pid;

        let nix_pid = Pid::from_raw(pid as i32);
        kill(nix_pid, Signal::SIGTERM).context("failed to send SIGTERM")?;
    }

    // Wait for graceful shutdown (5 seconds)
    let timeout = Duration::from_secs(5);
    let start = std::time::Instant::now();

    while start.elapsed() < timeout {
        if !pid_file::is_process_running(pid) {
            println!("Agent stopped successfully");
            // Clean up PID file
            let _ = fs::remove_file(&pid_file);
            return Ok(());
        }
        tokio::time::sleep(Duration::from_millis(100)).await;
    }

    // Process didn't stop gracefully, try SIGKILL
    println!("Agent didn't stop gracefully, sending SIGKILL...");

    #[cfg(unix)]
    {
        use nix::sys::signal::{kill, Signal};
        use nix::unistd::Pid;

        let nix_pid = Pid::from_raw(pid as i32);
        kill(nix_pid, Signal::SIGKILL).context("failed to send SIGKILL")?;
    }

    // Wait a bit more for SIGKILL
    tokio::time::sleep(Duration::from_millis(500)).await;

    if pid_file::is_process_running(pid) {
        error!("Failed to stop agent process {}", pid);
        anyhow::bail!("Failed to stop agent process");
    }

    println!("Agent stopped (force killed)");
    // Clean up PID file
    let _ = fs::remove_file(&pid_file);

    Ok(())
}

/// Show agent status.
pub async fn status(pid_file: String) -> Result<()> {
    // Read PID file
    let pid = match pid_file::read_pid_file(&pid_file) {
        Ok(pid) => pid,
        Err(_) => {
            println!("Status: stopped (no PID file)");
            return Ok(());
        }
    };

    // Check if process is running
    if !pid_file::is_process_running(pid) {
        println!("Status: stopped (process not running)");
        // Clean up stale PID file
        let _ = fs::remove_file(&pid_file);
        return Ok(());
    }

    // Get process start time for uptime calculation
    let uptime = process::get_process_uptime(pid).map(pid_file::format_duration);

    println!("Status: running");
    println!("PID: {pid}");
    if let Some(uptime_str) = uptime {
        println!("Uptime: {uptime_str}");
    }

    // Try to load config to show additional info
    if let Ok(config) = load_agent_config("agent-config.toml") {
        println!("Agent ID: {}", config.agent_id);
        println!("Server URL: {}", config.server_url);
        println!("Listen address: {}", config.listen_address);
    }

    Ok(())
}

/// Load agent configuration from file or use defaults.
fn load_agent_config(path: &str) -> Result<AgentConfig> {
    if Path::new(path).exists() {
        let config_str = fs::read_to_string(path)
            .with_context(|| format!("failed to read config file: {path}"))?;
        let config: AgentConfig = toml::from_str(&config_str)
            .with_context(|| format!("failed to parse config file: {path}"))?;
        Ok(config)
    } else {
        info!("No config file found at '{}', using defaults", path);
        Ok(AgentConfig::default())
    }
}

/// Run the agent in foreground mode (blocks until shutdown).
async fn run_agent_foreground(config: AgentConfig) -> Result<()> {
    // Initialize tracing for foreground mode
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| tracing_subscriber::EnvFilter::new("info")),
        )
        .init();

    info!("nession-agent {} starting", env!("CARGO_PKG_VERSION"));
    info!("Agent ID: {}", config.agent_id);
    info!("Server URL: {}", config.server_url);
    info!("Listen address: {}", config.listen_address);

    // Import and run the agent components
    use nession_agent::connection::ServerClient;
    use nession_agent::server::AgentServer;
    use nession_agent::sync::heartbeat::HeartbeatLoop;
    use nession_agent::sync::session_watcher::SessionWatcher;
    use nession_agent::tmux::manager::TmuxManager;
    use nession_common::protocol::AgentMetadata;
    use std::sync::Arc;

    // Start Agent WebSocket server
    let tls_option = load_tls(&config)?;
    let file_root = config
        .file_root
        .as_deref()
        .unwrap_or(&config.default_working_dir);
    let agent_id = if config.agent_id.is_empty() {
        get_hostname()
    } else {
        config.agent_id.clone()
    };
    let agent_server = AgentServer::new(
        &config.listen_address,
        &agent_id,
        tls_option,
        config.default_working_dir.clone(),
        file_root,
    )
    .context("failed to create agent server")?;
    let server_handle = agent_server
        .start()
        .await
        .context("failed to start agent server")?;
    info!(
        "Agent WebSocket server started on {}",
        config.listen_address
    );

    // Connect to central server
    let hostname = get_hostname();
    let ip_address = get_ip_address();
    let port = extract_port(&config.listen_address);
    let tmux_version = get_tmux_version().await;
    let os_version = format!("{} {}", std::env::consts::OS, std::env::consts::ARCH);

    let metadata = AgentMetadata {
        tmux_version,
        os_version,
        nession_version: env!("CARGO_PKG_VERSION").to_string(),
    };

    let server_client = ServerClient::new(
        &config.server_url,
        &config.auth_token,
        &config.agent_id,
        &hostname,
        &ip_address,
        port,
        None, // connect_url — not used in CLI bare-metal agent mode
        metadata,
        Arc::new(TmuxManager::new()),
        config.default_working_dir.clone(),
    );

    let (client_handle, heartbeat_interval_secs) = tokio::select! {
        result = server_client.connect_and_run() => {
            match result {
                Ok((handle, server_interval)) => {
                    let interval = server_interval.unwrap_or(config.heartbeat_interval_secs);
                    info!("Connected to central server (heartbeat interval: {}s)", interval);
                    (Some(handle), interval)
                }
                Err(e) => {
                    error!("Failed to connect to central server: {:#}", e);
                    (None, config.heartbeat_interval_secs)
                }
            }
        }
        _ = tokio::time::sleep(Duration::from_secs(30)) => {
            info!("Timed out connecting to central server after 30s, continuing without sync");
            (None, config.heartbeat_interval_secs)
        }
    };

    // Start HeartbeatLoop
    let heartbeat_shutdown = if let Some(ref handle) = client_handle {
        let heartbeat =
            HeartbeatLoop::new(handle.clone(), TmuxManager::new(), heartbeat_interval_secs);
        let shutdown_handle = heartbeat.shutdown_handle();
        tokio::spawn(async move {
            if let Err(e) = heartbeat.run().await {
                error!("Heartbeat loop error: {:#}", e);
            }
        });
        Some(shutdown_handle)
    } else {
        None
    };

    // Start SessionWatcher
    let watcher_shutdown = if let Some(ref handle) = client_handle {
        let watcher = SessionWatcher::new(
            handle.clone(),
            TmuxManager::new(),
            config.session_poll_interval_secs,
        );
        let shutdown_handle = watcher.shutdown_handle();
        tokio::spawn(async move {
            if let Err(e) = watcher.run().await {
                error!("Session watcher error: {:#}", e);
            }
        });
        Some(shutdown_handle)
    } else {
        None
    };

    // Wait for shutdown signal
    info!("Agent is running. Press Ctrl+C to stop.");
    wait_for_shutdown().await?;
    info!("Shutdown signal received, stopping components...");

    // Graceful shutdown
    if let Err(e) = server_handle.shutdown().await {
        error!("Error shutting down agent server: {:#}", e);
    }
    if let Some(ref handle) = heartbeat_shutdown {
        if let Err(e) = handle.shutdown().await {
            error!("Error shutting down heartbeat loop: {:#}", e);
        }
    }
    if let Some(ref handle) = watcher_shutdown {
        if let Err(e) = handle.shutdown().await {
            error!("Error shutting down session watcher: {:#}", e);
        }
    }

    info!("nession-agent stopped");
    Ok(())
}

/// Load TLS certificates from config.
fn load_tls(
    config: &AgentConfig,
) -> Result<
    Option<(
        Vec<rustls::pki_types::CertificateDer<'static>>,
        rustls::pki_types::PrivateKeyDer<'static>,
    )>,
> {
    match (&config.tls_cert_path, &config.tls_key_path) {
        (Some(cert), Some(key)) => {
            use nession_agent::server::AgentServer;
            AgentServer::load_tls(Some(cert), Some(key))
        }
        (None, None) => Ok(None),
        _ => anyhow::bail!("both tls_cert_path and tls_key_path must be set (or both unset)"),
    }
}

/// Wait for shutdown signal (SIGINT/SIGTERM).
async fn wait_for_shutdown() -> anyhow::Result<()> {
    #[cfg(unix)]
    {
        use tokio::signal::unix::{signal, SignalKind};
        let mut sigint =
            signal(SignalKind::interrupt()).context("failed to register SIGINT handler")?;
        let mut sigterm =
            signal(SignalKind::terminate()).context("failed to register SIGTERM handler")?;
        tokio::select! {
            _ = sigint.recv() => {
                info!("Received SIGINT");
            }
            _ = sigterm.recv() => {
                info!("Received SIGTERM");
            }
        }
    }

    #[cfg(not(unix))]
    {
        tokio::signal::ctrl_c()
            .await
            .context("failed to listen for ctrl+c")?;
        info!("Received Ctrl+C");
    }
    Ok(())
}

/// Get the system hostname.
fn get_hostname() -> String {
    std::env::var("HOSTNAME")
        .or_else(|_| std::env::var("HOST"))
        .unwrap_or_else(|_| "unknown".to_string())
}

/// Get the local IP address.
fn get_ip_address() -> String {
    std::net::UdpSocket::bind("0.0.0.0:0")
        .and_then(|socket| {
            socket.connect("8.8.8.8:80")?;
            socket.local_addr()
        })
        .map(|addr| addr.ip().to_string())
        .unwrap_or_else(|_| "127.0.0.1".to_string())
}

/// Extract port from address string.
fn extract_port(addr: &str) -> u16 {
    addr.rsplit(':')
        .next()
        .and_then(|p| p.parse().ok())
        .unwrap_or(0)
}

/// Get tmux version.
async fn get_tmux_version() -> String {
    tokio::process::Command::new("tmux")
        .arg("-V")
        .output()
        .await
        .ok()
        .and_then(|output| {
            if output.status.success() {
                Some(String::from_utf8_lossy(&output.stdout).trim().to_string())
            } else {
                None
            }
        })
        .unwrap_or_else(|| "unknown".to_string())
}

//! Client-facing CLI commands implementation.

use anyhow::{Context, Result};
use std::time::{SystemTime, UNIX_EPOCH};

use crate::client::connection::ClientConnection;

/// List agents from the server and display them in a formatted table.
pub async fn list_agents(server_url: &str, auth_token: &str) -> Result<()> {
    // Connect to the server
    let mut conn = ClientConnection::connect(server_url, auth_token)
        .await
        .with_context(|| "Failed to connect to server. Is the server running?")?;

    // Fetch agents
    let agents = conn.list_agents().await?;

    // Close connection
    conn.close().await.ok();

    // Display results
    if agents.is_empty() {
        println!("No agents registered.");
        return Ok(());
    }

    println!();
    println!("Agents:");
    println!(
        "{:<16}{:<18}{:<10}{:<12}{:<15}",
        "ID", "HOSTNAME", "STATUS", "SESSIONS", "LAST HEARTBEAT"
    );

    for agent in &agents {
        let heartbeat_ago = format_time_ago(&agent.last_heartbeat);
        println!(
            "{:<16}{:<18}{:<10}{:<12}{:<15}",
            agent.agent_id, agent.hostname, agent.status, agent.session_count, heartbeat_ago,
        );
    }
    println!();
    println!("{} agent(s) total", agents.len());

    Ok(())
}

/// List sessions from the server and display them in a formatted table.
pub async fn list_sessions(
    server_url: &str,
    auth_token: &str,
    agent_id: Option<&str>,
) -> Result<()> {
    // Connect to the server
    let mut conn = ClientConnection::connect(server_url, auth_token)
        .await
        .with_context(|| "Failed to connect to server. Is the server running?")?;

    // Fetch sessions
    let sessions = conn.list_sessions(agent_id).await?;

    // Close connection
    conn.close().await.ok();

    // Display results
    if sessions.is_empty() {
        if let Some(aid) = agent_id {
            println!("No sessions found for agent '{aid}'.");
        } else {
            println!("No sessions found.");
        }
        return Ok(());
    }

    println!();
    println!("Sessions:");
    println!(
        "{:<34}{:<16}{:<14}{:<12}{:<10}ATTACHED",
        "SESSION ID", "AGENT", "NAME", "STATUS", "WINDOWS"
    );

    for session in &sessions {
        println!(
            "{:<34}{:<16}{:<14}{:<12}{:<10}{}",
            session.session_id,
            session.agent_id,
            session.session_name,
            session.status,
            session.window_count,
            session.attached_clients,
        );
    }
    println!();
    println!("{} session(s) total", sessions.len());

    Ok(())
}

/// Attach to a remote tmux session.
///
/// Connects to the server, requests to attach to the specified session,
/// and then establishes either a P2P or relay connection to the agent.
/// Terminal I/O is forwarded bidirectionally until the session ends or
/// the user detaches.
///
/// # Arguments
///
/// * `server_url` - URL of the nession server
/// * `auth_token` - Authentication token
/// * `session_id` - Session ID in format "agent_id:session_name"
/// * `force_mode` - Optional mode override ("p2p" or "relay")
pub async fn attach_session(
    server_url: &str,
    auth_token: &str,
    session_id: &str,
    force_mode: Option<&str>,
) -> Result<()> {
    // Connect to server
    let mut conn = ClientConnection::connect(server_url, auth_token)
        .await
        .with_context(|| "Failed to connect to server. Is the server running?")?;

    // Determine preferred mode
    let preferred_mode = match force_mode {
        Some("relay") => "relay",
        Some("p2p") | None => "p2p",
        Some(other) => {
            anyhow::bail!("Invalid mode '{other}'. Use 'p2p' or 'relay'.");
        }
    };

    println!("Requesting to attach to session '{session_id}' (mode: {preferred_mode})...");

    // Request attach
    let attach_resp = conn
        .request_attach(session_id, preferred_mode)
        .await
        .with_context(|| "Failed to attach to session")?;

    match attach_resp {
        crate::client::connection::AttachResponse::P2P(p2p_info) => {
            println!(
                "Connecting to agent at {} (P2P mode)...",
                p2p_info.agent_address
            );

            // Connect directly to agent
            let agent_ws = crate::client::connection::connect_to_agent(&p2p_info.agent_address)
                .await
                .with_context(|| {
                    format!("Failed to connect to agent at {}", p2p_info.agent_address)
                })?;

            // Create WebSocket transport
            let transport = crate::terminal::raw::WebSocketTransport::new(agent_ws);

            // Send client.attach to agent with session name
            use nession_agent::server::websocket::{
                msg_types as agent_msg_types, ClientAttachPayload, Message as AgentMessage,
            };
            let (cols, rows) = crate::terminal::raw::RawTerminal::size()?;
            let attach_msg = AgentMessage {
                msg_type: agent_msg_types::CLIENT_ATTACH.to_string(),
                id: uuid::Uuid::new_v4().to_string(),
                timestamp: std::time::SystemTime::now()
                    .duration_since(std::time::UNIX_EPOCH)
                    .unwrap_or_default()
                    .as_secs(),
                payload: ClientAttachPayload {
                    session_name: p2p_info.session_name.clone(),
                    width: cols,
                    height: rows,
                },
            };
            let attach_json = serde_json::to_string(&attach_msg)?;
            use crate::terminal::TerminalTransport;
            let mut transport = transport;
            transport.send_text(attach_json).await?;

            println!(
                "Attached to session '{}'. Press Ctrl+B then D to detach.",
                p2p_info.session_name
            );

            // Create cancellation channel
            let (cancel_tx, cancel_rx) = tokio::sync::watch::channel(false);

            // Spawn Ctrl+C handler
            let cancel_tx_clone = cancel_tx.clone();
            tokio::spawn(async move {
                tokio::signal::ctrl_c().await.ok();
                let _ = cancel_tx_clone.send(true);
            });

            // Create and run terminal session
            let session =
                crate::terminal::TerminalSession::new(p2p_info.session_name, transport, cancel_rx);

            // Detach key: Ctrl+B followed by 'd'
            let detach_key = crossterm::event::KeyEvent::new(
                crossterm::event::KeyCode::Char('b'),
                crossterm::event::KeyModifiers::CONTROL,
            );

            session.run(Some(detach_key)).await?;

            println!("\nDetached from session.");
        }
        crate::client::connection::AttachResponse::Relay => {
            println!("Using relay mode (server proxies I/O)...");

            // Use server connection as relay transport
            let relay_ws = conn.into_relay_transport();
            let transport = crate::terminal::raw::WebSocketTransport::new(relay_ws);

            // For relay mode, the server expects us to send terminal protocol messages
            // The server will forward them to the agent
            use nession_agent::server::websocket::{
                msg_types as agent_msg_types, ClientAttachPayload, Message as AgentMessage,
            };
            let (cols, rows) = crate::terminal::raw::RawTerminal::size()?;

            // Parse session_name from session_id (format: agent_id:session_name)
            let session_name = session_id.split(':').nth(1).unwrap_or(session_id);

            let attach_msg = AgentMessage {
                msg_type: agent_msg_types::CLIENT_ATTACH.to_string(),
                id: uuid::Uuid::new_v4().to_string(),
                timestamp: std::time::SystemTime::now()
                    .duration_since(std::time::UNIX_EPOCH)
                    .unwrap_or_default()
                    .as_secs(),
                payload: ClientAttachPayload {
                    session_name: session_name.to_string(),
                    width: cols,
                    height: rows,
                },
            };
            let attach_json = serde_json::to_string(&attach_msg)?;
            use crate::terminal::TerminalTransport;
            let mut transport = transport;
            transport.send_text(attach_json).await?;

            println!("Attached to session '{session_name}' via relay.");

            // Create cancellation channel
            let (cancel_tx, cancel_rx) = tokio::sync::watch::channel(false);

            // Spawn Ctrl+C handler
            let cancel_tx_clone = cancel_tx.clone();
            tokio::spawn(async move {
                tokio::signal::ctrl_c().await.ok();
                let _ = cancel_tx_clone.send(true);
            });

            // Create and run terminal session
            let session = crate::terminal::TerminalSession::new(
                session_name.to_string(),
                transport,
                cancel_rx,
            );

            // Detach key: Ctrl+B followed by 'd'
            let detach_key = crossterm::event::KeyEvent::new(
                crossterm::event::KeyCode::Char('b'),
                crossterm::event::KeyModifiers::CONTROL,
            );

            session.run(Some(detach_key)).await?;

            println!("\nDetached from session.");
        }
    }

    Ok(())
}

/// Create a new tmux session on an agent.
///
/// Connects to the server to look up the agent's address, then connects
/// directly to the agent to send the `session.create` command.
///
/// # Arguments
///
/// * `server_url` - URL of the nession server
/// * `auth_token` - Authentication token
/// * `agent_id` - ID of the agent to create the session on
/// * `session_name` - Name for the new session
/// * `width` - Terminal width in columns
/// * `height` - Terminal height in rows
pub async fn create_session(
    server_url: &str,
    auth_token: &str,
    agent_id: &str,
    session_name: &str,
    width: u16,
    height: u16,
) -> Result<()> {
    // Connect to server to look up agent address
    let mut conn = ClientConnection::connect(server_url, auth_token)
        .await
        .with_context(|| "Failed to connect to server. Is the server running?")?;

    // Find the agent
    let agents = conn.list_agents().await?;
    conn.close().await.ok();

    let agent = agents
        .iter()
        .find(|a| a.agent_id == agent_id)
        .with_context(|| format!("Agent '{agent_id}' not found. Is it registered?"))?;

    if agent.status != "online" {
        anyhow::bail!(
            "Agent '{}' is not online (status: {}). Cannot create session.",
            agent_id,
            agent.status
        );
    }

    let agent_address = format!("{}:{}", agent.ip_address, agent.port);
    println!("Creating session '{session_name}' on agent '{agent_id}' ({width}x{height})...");

    let created_name = crate::client::connection::create_session_on_agent(
        &agent_address,
        session_name,
        width,
        height,
    )
    .await
    .with_context(|| format!("Failed to create session '{session_name}' on agent '{agent_id}'"))?;

    println!("Session '{created_name}' created successfully.");

    Ok(())
}

/// Kill a tmux session on an agent.
///
/// Parses the session_id (format: `agent_id:session_name`), looks up the
/// agent's address from the server, then connects directly to the agent
/// to send the `session.kill` command.
///
/// # Arguments
///
/// * `server_url` - URL of the nession server
/// * `auth_token` - Authentication token
/// * `session_id` - Session ID in format "agent_id:session_name"
pub async fn kill_session(server_url: &str, auth_token: &str, session_id: &str) -> Result<()> {
    // Parse session_id (format: agent_id:session_name)
    let (agent_id, session_name) = session_id.split_once(':').with_context(|| {
        format!("Invalid session ID '{session_id}'. Expected format: agent_id:session_name")
    })?;

    // Connect to server to look up agent address
    let mut conn = ClientConnection::connect(server_url, auth_token)
        .await
        .with_context(|| "Failed to connect to server. Is the server running?")?;

    // Find the agent
    let agents = conn.list_agents().await?;
    conn.close().await.ok();

    let agent = agents
        .iter()
        .find(|a| a.agent_id == agent_id)
        .with_context(|| format!("Agent '{agent_id}' not found. Is it registered?"))?;

    let agent_address = format!("{}:{}", agent.ip_address, agent.port);
    println!("Killing session '{session_name}' on agent '{agent_id}'...");

    let killed_name =
        crate::client::connection::kill_session_on_agent(&agent_address, session_name)
            .await
            .with_context(|| {
                format!("Failed to kill session '{session_name}' on agent '{agent_id}'")
            })?;

    println!("Session '{killed_name}' killed successfully.");

    Ok(())
}

/// Format a timestamp string (ISO 8601 or Unix seconds) into "Xs ago" or "Xm ago".
fn format_time_ago(timestamp: &str) -> String {
    // Try to parse as a datetime
    if let Ok(dt) = chrono::DateTime::parse_from_rfc3339(timestamp) {
        let now = chrono::Utc::now();
        let dt_utc = dt.with_timezone(&chrono::Utc);
        let elapsed = now.signed_duration_since(dt_utc);
        let secs = elapsed.num_seconds();

        if secs < 0 {
            return "just now".to_string();
        }
        if secs < 60 {
            return format!("{secs}s ago");
        }
        let mins = secs / 60;
        if mins < 60 {
            return format!("{mins}m ago");
        }
        let hours = mins / 60;
        if hours < 24 {
            return format!("{hours}h ago");
        }
        let days = hours / 24;
        return format!("{days}d ago");
    }

    // Try to parse as unix timestamp (seconds)
    if let Ok(unix_secs) = timestamp.parse::<i64>() {
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs() as i64;
        let elapsed = now - unix_secs;

        if elapsed < 0 {
            return "just now".to_string();
        }
        if elapsed < 60 {
            return format!("{elapsed}s ago");
        }
        let mins = elapsed / 60;
        if mins < 60 {
            return format!("{mins}m ago");
        }
        let hours = mins / 60;
        if hours < 24 {
            return format!("{hours}h ago");
        }
        let days = hours / 24;
        return format!("{days}d ago");
    }

    // Fallback: return the original string
    timestamp.to_string()
}

