//! SemVer parsing and comparison.

use semver::Version;

#[derive(Debug, PartialEq, Eq)]
pub enum VersionStatus {
    UpToDate,
    UpdateAvailable { current: Version, latest: Version },
    DevelopmentVersion { current: String, latest: Version },
}

pub fn parse_semver(raw: &str) -> Option<Version> {
    let stripped = raw.strip_prefix('v').unwrap_or(raw);
    Version::parse(stripped).ok()
}

pub fn compare_versions(current_raw: &str, latest: &Version) -> VersionStatus {
    match parse_semver(current_raw) {
        Some(current) if current == *latest => VersionStatus::UpToDate,
        Some(current) if current < *latest => VersionStatus::UpdateAvailable {
            current,
            latest: latest.clone(),
        },
        Some(_current) => VersionStatus::DevelopmentVersion {
            current: current_raw.to_string(),
            latest: latest.clone(),
        },
        None => VersionStatus::DevelopmentVersion {
            current: current_raw.to_string(),
            latest: latest.clone(),
        },
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parse_with_v_prefix() {
        let v = parse_semver("v0.5.0").unwrap();
        assert_eq!(v.major, 0);
        assert_eq!(v.minor, 5);
        assert_eq!(v.patch, 0);
    }

    #[test]
    fn parse_without_v_prefix() {
        let v = parse_semver("1.2.3").unwrap();
        assert_eq!(v.to_string(), "1.2.3");
    }

    #[test]
    fn parse_dev_version_returns_none() {
        // "0.4.0-dev" is valid semver (pre-release tag).
        // It should parse successfully, not return None.
        let v = parse_semver("0.4.0-dev");
        assert!(v.is_some());
    }

    #[test]
    fn parse_prerelease_is_valid_semver() {
        let v = parse_semver("v1.0.0-beta.1").unwrap();
        assert!(v.pre.as_str() == "beta.1");
    }

    #[test]
    fn compare_up_to_date() {
        let latest = Version::new(0, 4, 2);
        let status = compare_versions("0.4.2", &latest);
        assert_eq!(status, VersionStatus::UpToDate);
    }

    #[test]
    fn compare_update_available() {
        let latest = Version::new(0, 5, 0);
        let status = compare_versions("0.4.2", &latest);
        assert!(matches!(status, VersionStatus::UpdateAvailable { .. }));
    }

    #[test]
    fn compare_development_version() {
        let latest = Version::new(0, 4, 2);
        let status = compare_versions("0.5.0", &latest);
        assert!(matches!(status, VersionStatus::DevelopmentVersion { .. }));
    }

    #[test]
    fn compare_dev_string_treated_as_dev() {
        let latest = Version::new(0, 4, 2);
        // "0.5.0-dev" parses as 0.5.0 with pre-release "dev", which is > 0.4.2,
        // so it should return DevelopmentVersion.
        let status = compare_versions("0.5.0-dev", &latest);
        assert!(matches!(status, VersionStatus::DevelopmentVersion { .. }));
    }

    #[test]
    fn parse_v_prefix_prerelease() {
        let v = parse_semver("v0.5.0-rc.1").unwrap();
        assert_eq!(v.major, 0);
        assert_eq!(v.minor, 5);
        assert_eq!(v.patch, 0);
        assert_eq!(v.pre.as_str(), "rc.1");
    }

    #[test]
    fn parse_unknown_marker_returns_none() {
        assert!(parse_semver("unknown").is_none());
    }

    #[test]
    fn compare_none_version_returns_dev() {
        let latest = Version::new(0, 4, 2);
        let status = compare_versions("unknown", &latest);
        assert!(matches!(status, VersionStatus::DevelopmentVersion { .. }));
    }

    #[test]
    fn compare_update_available_has_correct_values() {
        let latest = Version::new(0, 5, 0);
        let status = compare_versions("0.4.2", &latest);
        match status {
            VersionStatus::UpdateAvailable { current, latest: l } => {
                assert_eq!(current.to_string(), "0.4.2");
                assert_eq!(l.to_string(), "0.5.0");
            }
            other => panic!("expected UpdateAvailable, got {other:?}"),
        }
    }
}

//! Utility modules for CLI commands.
//!
//! This module contains shared utilities used by agent, server, and client
//! commands, including PID file management and process monitoring.

pub mod pid_file;
pub mod process;

//! PID file management utilities for daemon processes.
//!
//! Provides functions to create, read, and manage PID files for
//! background processes like agents and servers.

use anyhow::{Context, Result};
use std::fs;
use std::path::Path;

/// Write the current process ID to a file.
///
/// Creates or overwrites the file at `path` with the given PID.
/// Returns the PID that was written.
pub fn write_pid_file(path: &str, pid: u32) -> Result<()> {
    fs::write(path, pid.to_string())
        .with_context(|| format!("Failed to write PID file: {path}"))?;
    Ok(())
}

/// Read a PID from a file.
///
/// Returns the PID stored in the file at `path`.
/// Returns an error if the file doesn't exist or contains invalid data.
pub fn read_pid_file(path: &str) -> Result<u32> {
    let content =
        fs::read_to_string(path).with_context(|| format!("Failed to read PID file: {path}"))?;
    let pid: u32 = content
        .trim()
        .parse()
        .with_context(|| format!("Failed to parse PID from file: {path}"))?;
    Ok(pid)
}

/// Check if a process with the given PID is currently running.
///
/// Returns `true` if the process exists, `false` otherwise.
/// On Unix systems, this sends a signal 0 to check process existence.
#[cfg(unix)]
pub fn is_process_running(pid: u32) -> bool {
    use nix::sys::signal::kill;
    use nix::unistd::Pid;

    kill(Pid::from_raw(pid as i32), None).is_ok()
}

#[cfg(not(unix))]
pub fn is_process_running(pid: u32) -> bool {
    // On non-Unix systems, we can't easily check process existence
    // This is a placeholder implementation
    false
}

/// Check if a process is running based on its PID file.
///
/// Returns `true` if the PID file exists and the process is running.
/// Returns `false` if the file doesn't exist, is invalid, or the process is not running.
#[allow(dead_code)]
pub fn is_process_running_from_pid_file(path: &str) -> bool {
    if !Path::new(path).exists() {
        return false;
    }

    match read_pid_file(path) {
        Ok(pid) => is_process_running(pid),
        Err(_) => false,
    }
}

/// Format a duration in seconds into a human-readable string.
///
/// Examples:
/// - 30 seconds -> "30 seconds"
/// - 90 seconds -> "1 minute 30 seconds"
/// - 3661 seconds -> "1 hour 1 minute 1 second"
pub fn format_duration(seconds: u64) -> String {
    let hours = seconds / 3600;
    let minutes = (seconds % 3600) / 60;
    let secs = seconds % 60;

    let mut parts = Vec::new();

    if hours > 0 {
        parts.push(format!(
            "{} hour{}",
            hours,
            if hours == 1 { "" } else { "s" }
        ));
    }

    if minutes > 0 {
        parts.push(format!(
            "{} minute{}",
            minutes,
            if minutes == 1 { "" } else { "s" }
        ));
    }

    if secs > 0 || parts.is_empty() {
        parts.push(format!(
            "{} second{}",
            secs,
            if secs == 1 { "" } else { "s" }
        ));
    }

    parts.join(" ")
}

