    pub ip_address: String,
    pub port: u16,
    pub registered_at: i64,
    pub last_heartbeat: i64,
    pub status: String,
    pub auth_token_hash: String,
    pub metadata: String,
}

#[derive(Debug, Clone)]
pub struct SessionRow {
    pub session_id: String,
    pub agent_id: String,
    pub session_name: String,
    pub created_at: i64,
    pub last_activity: i64,
    pub status: String,
    pub window_count: u32,
    pub attached_clients: u32,
    pub metadata: String,
}

impl Database {
    pub async fn new(db_path: &str) -> Result<Self> {
        let conn = Connection::open(db_path)?;

        // Create tables
        conn.execute_batch(
            "CREATE TABLE IF NOT EXISTS agents (
                agent_id TEXT PRIMARY KEY,
                hostname TEXT NOT NULL,
                ip_address TEXT NOT NULL,
                port INTEGER NOT NULL,
                registered_at INTEGER NOT NULL,
                last_heartbeat INTEGER NOT NULL,
                status TEXT NOT NULL,
                auth_token_hash TEXT NOT NULL,
                metadata TEXT
            );

            CREATE TABLE IF NOT EXISTS sessions (
                session_id TEXT PRIMARY KEY,
                agent_id TEXT NOT NULL,
                session_name TEXT NOT NULL,
                created_at INTEGER NOT NULL,
                last_activity INTEGER NOT NULL,
                status TEXT NOT NULL,
                window_count INTEGER NOT NULL,
                attached_clients INTEGER NOT NULL,
                metadata TEXT
            );

            CREATE INDEX IF NOT EXISTS idx_agents_status ON agents(status);
            CREATE INDEX IF NOT EXISTS idx_sessions_agent_id ON sessions(agent_id);",
        )?;

        Ok(Self {
            conn: Arc::new(Mutex::new(conn)),
        })
    }

    pub async fn insert_agent(
        &self,
        agent_id: &str,
        hostname: &str,
        ip_address: &str,
        port: u16,
        auth_token_hash: &str,
        metadata: &str,
    ) -> Result<()> {
        let conn = self.conn.lock().await;
        let now = chrono::Utc::now().timestamp();

        conn.execute(
            "INSERT OR REPLACE INTO agents (agent_id, hostname, ip_address, port, registered_at, last_heartbeat, status, auth_token_hash, metadata)
             VALUES (?1, ?2, ?3, ?4, ?5, ?5, 'online', ?6, ?7)",
            rusqlite::params![agent_id, hostname, ip_address, port, now, auth_token_hash, metadata],
        )?;

        Ok(())
    }

    pub async fn list_agents(&self) -> Result<Vec<AgentRow>> {
        let conn = self.conn.lock().await;
        let mut stmt = conn.prepare(
            "SELECT agent_id, hostname, ip_address, port, registered_at, last_heartbeat, status, auth_token_hash, metadata FROM agents"
        )?;

        let agents = stmt
            .query_map([], |row| {
                Ok(AgentRow {
                    agent_id: row.get(0)?,
                    hostname: row.get(1)?,
                    ip_address: row.get(2)?,
                    port: row.get(3)?,
                    registered_at: row.get(4)?,
                    last_heartbeat: row.get(5)?,
                    status: row.get(6)?,
                    auth_token_hash: row.get(7)?,
                    metadata: row.get(8)?,
                })
            })?
            .collect::<Result<Vec<_>>>()?;

        Ok(agents)
    }

    pub async fn insert_session(
        &self,
        session: &crate::registry::session::SessionInfo,
        status: &str,
    ) -> Result<()> {
        let conn = self.conn.lock().await;
        let now = chrono::Utc::now().timestamp();

        conn.execute(
            "INSERT OR REPLACE INTO sessions (session_id, agent_id, session_name, created_at, last_activity, status, window_count, attached_clients, metadata)
             VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8, '')",
            rusqlite::params![
                session.session_id,
                session.agent_id,
                session.session_name,
                session.created_at.timestamp(),
                now,
                status,
                session.window_count,
                session.attached_clients,
            ],
        )?;

        Ok(())
    }

    pub async fn update_session_status(&self, session_id: &str, status: &str) -> Result<()> {
        let conn = self.conn.lock().await;
        conn.execute(
            "UPDATE sessions SET status = ?1, last_activity = ?2 WHERE session_id = ?3",
            rusqlite::params![status, chrono::Utc::now().timestamp(), session_id],
        )?;
        Ok(())
    }

    pub async fn delete_session(&self, session_id: &str) -> Result<()> {
        let conn = self.conn.lock().await;
        conn.execute(
            "DELETE FROM sessions WHERE session_id = ?1",
            rusqlite::params![session_id],
        )?;
        Ok(())
    }

    pub async fn delete_sessions_by_agent(&self, agent_id: &str) -> Result<()> {
        let conn = self.conn.lock().await;
        conn.execute(
            "DELETE FROM sessions WHERE agent_id = ?1",
            rusqlite::params![agent_id],
        )?;
        Ok(())
    }

    pub async fn list_all_sessions(&self) -> Result<Vec<SessionRow>> {
        let conn = self.conn.lock().await;
        let mut stmt = conn.prepare(
            "SELECT session_id, agent_id, session_name, created_at, last_activity, status, window_count, attached_clients, metadata FROM sessions"
        )?;

        let sessions = stmt
            .query_map([], |row| {
                Ok(SessionRow {
                    session_id: row.get(0)?,
                    agent_id: row.get(1)?,
                    session_name: row.get(2)?,
                    created_at: row.get(3)?,
                    last_activity: row.get(4)?,
                    status: row.get(5)?,
                    window_count: row.get(6)?,
                    attached_clients: row.get(7)?,
                    metadata: row.get(8)?,
                })
            })?
            .collect::<Result<Vec<_>>>()?;

        Ok(sessions)
    }

    pub async fn list_sessions_older_than(&self, duration_secs: i64) -> Result<Vec<SessionRow>> {
        let conn = self.conn.lock().await;
        let cutoff = chrono::Utc::now().timestamp() - duration_secs;
        let mut stmt = conn.prepare(
            "SELECT session_id, agent_id, session_name, created_at, last_activity, status, window_count, attached_clients, metadata FROM sessions WHERE last_activity < ?1 AND status = 'recovering'"
        )?;

        let sessions = stmt
            .query_map([cutoff], |row| {
                Ok(SessionRow {
                    session_id: row.get(0)?,
                    agent_id: row.get(1)?,
                    session_name: row.get(2)?,
                    created_at: row.get(3)?,
                    last_activity: row.get(4)?,
                    status: row.get(5)?,
                    window_count: row.get(6)?,
                    attached_clients: row.get(7)?,
                    metadata: row.get(8)?,
                })
            })?
            .collect::<Result<Vec<_>>>()?;

        Ok(sessions)
    }
}

//! Server-side environment-file management: storage, usage tracking, and
//! snapshot resolution.

pub mod store;
pub mod usage;

pub use store::EnvStore;
pub use usage::EnvUsageRegistry;

use std::sync::Arc;

/// Bundles the server-side env store with the in-memory usage registry so a
/// single `Arc` can be threaded through the connection handlers.
pub struct EnvService {
    pub store: EnvStore,
    pub usage: EnvUsageRegistry,
}

impl EnvService {
    /// Construct the service rooted at the given server env directory.
    #[must_use]
    pub fn new(root: std::path::PathBuf) -> Arc<Self> {
        Arc::new(Self {
            store: EnvStore::new(root),
            usage: EnvUsageRegistry::new(),
        })
    }
}

//! Server-side env-file storage under `~/.nession/server/envs`.
//!
//! Mirrors the agent-local store but tags files with `EnvSource::Server`.
//! Filenames are validated to reject path traversal.

use anyhow::{Context, Result};
use nession_common::env_file::parse_env;
use nession_common::protocol::{EnvFileInfo, EnvSource};
use std::path::{Path, PathBuf};
use tokio::fs;

/// Store for server-managed env files.
#[derive(Clone)]
pub struct EnvStore {
    root: PathBuf,
}

/// Validate that `name` is a safe `.env` filename.
fn validate_name(name: &str) -> Result<()> {
    if name.is_empty() {
        anyhow::bail!("env file name is empty");
    }
    if name.contains('/') || name.contains('\\') || name.contains("..") {
        anyhow::bail!("invalid env file name: {name}");
    }
    if Path::new(name).file_name().map(|f| f.to_string_lossy()) != Some(name.into()) {
        anyhow::bail!("invalid env file name: {name}");
    }
    if !name.ends_with(".env") || name.len() <= 4 {
        anyhow::bail!("env file name must end with .env: {name}");
    }
    Ok(())
}

impl EnvStore {
    /// Create a store rooted at `root`. The directory is created lazily on the
    /// first write, so construction is infallible.
    #[must_use]
    pub fn new(root: PathBuf) -> Self {
        Self { root }
    }

    fn path_for(&self, name: &str) -> Result<PathBuf> {
        validate_name(name)?;
        Ok(self.root.join(name))
    }

    /// List all `.env` files with metadata. Missing/unreadable dir → empty.
    pub async fn list(&self) -> Result<Vec<EnvFileInfo>> {
        let mut out = Vec::new();
        let mut dir = match fs::read_dir(&self.root).await {
            Ok(d) => d,
            Err(_) => return Ok(out),
        };
        while let Some(entry) = dir.next_entry().await? {
            let file_name = entry.file_name().to_string_lossy().to_string();
            if !file_name.ends_with(".env") {
                continue;
            }
            let meta = match entry.metadata().await {
                Ok(m) if m.is_file() => m,
                _ => continue,
            };
            let modified = meta
                .modified()
                .ok()
                .and_then(|t| t.duration_since(std::time::UNIX_EPOCH).ok())
                .map(|d| d.as_secs())
                .unwrap_or(0);
            let var_count = fs::read_to_string(entry.path())
                .await
                .map(|c| parse_env(&c).len())
                .unwrap_or(0);
            out.push(EnvFileInfo {
                name: file_name,
                source: EnvSource::Server,
                agent_id: None,
                size: meta.len(),
                modified,
                var_count,
            });
        }
        out.sort_by_key(|f| f.name.to_lowercase());
        Ok(out)
    }

    /// Read a file's raw content.
    pub async fn read(&self, name: &str) -> Result<String> {
        let path = self.path_for(name)?;
        fs::read_to_string(&path)
            .await
            .with_context(|| format!("failed to read env file: {name}"))
    }

    /// True if the named file exists.
    pub async fn exists(&self, name: &str) -> Result<bool> {
        let path = self.path_for(name)?;
        Ok(fs::try_exists(&path).await.unwrap_or(false))
    }

    /// Write (create/overwrite) a file atomically. When `overwrite` is false
    /// and the file exists, returns `Ok(false)` without writing.
    pub async fn write(&self, name: &str, content: &str, overwrite: bool) -> Result<bool> {
        let path = self.path_for(name)?;
        fs::create_dir_all(&self.root)
            .await
            .with_context(|| format!("failed to create env dir: {}", self.root.display()))?;
        if !overwrite && fs::try_exists(&path).await.unwrap_or(false) {
            return Ok(false);
        }
        let tmp = self
            .root
            .join(format!(".nession-{}.tmp", uuid::Uuid::new_v4()));
        fs::write(&tmp, content.as_bytes())
            .await
            .with_context(|| format!("failed to write temp env file for {name}"))?;
        if let Err(e) = fs::rename(&tmp, &path).await {
            let _ = fs::remove_file(&tmp).await;
            return Err(e).with_context(|| format!("failed to persist env file: {name}"));
        }
        Ok(true)
    }

    /// Delete a file. Missing file is treated as success (idempotent).
    pub async fn delete(&self, name: &str) -> Result<()> {
        let path = self.path_for(name)?;
        match fs::remove_file(&path).await {
            Ok(()) => Ok(()),
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(()),
            Err(e) => Err(e).with_context(|| format!("failed to delete env file: {name}")),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn store_in(dir: &tempfile::TempDir) -> EnvStore {
        EnvStore::new(dir.path().to_path_buf())
    }

    #[test]
    fn rejects_traversal() {
        assert!(validate_name("../evil.env").is_err());
        assert!(validate_name("a/b.env").is_err());
        assert!(validate_name("noext").is_err());
        assert!(validate_name("good.env").is_ok());
    }

    #[tokio::test]
    async fn roundtrip() {
        let dir = tempfile::tempdir().unwrap();
        let s = store_in(&dir);
        assert!(s.write("a.env", "FOO=bar\n", false).await.unwrap());
        assert_eq!(s.read("a.env").await.unwrap(), "FOO=bar\n");
        let list = s.list().await.unwrap();
        assert_eq!(list.len(), 1);
        assert_eq!(list.first().unwrap().source, EnvSource::Server);
        assert!(list.first().unwrap().agent_id.is_none());
        s.delete("a.env").await.unwrap();
        assert!(s.list().await.unwrap().is_empty());
    }

    #[tokio::test]
    async fn no_overwrite_refuses() {
        let dir = tempfile::tempdir().unwrap();
        let s = store_in(&dir);
        assert!(s.write("a.env", "X=1", false).await.unwrap());
        assert!(!s.write("a.env", "X=2", false).await.unwrap());
        assert_eq!(s.read("a.env").await.unwrap(), "X=1");
    }
}

//! In-memory registry tracking which env files are applied to which sessions.
//!
//! Powers two features:
//! - **In-use lock (SC5/EC10):** an env file applied to a running session may
//!   not be edited until every using session releases it.
//! - **Visibility (SC4):** clients can see which env files are active on a
//!   session, their source, phase (create/attach), and who applied them.
//!
//! State is intentionally in-memory: create-time usage is released when the
//! session is destroyed, and attach-time usage when the client detaches. On a
//! server restart all sessions are re-synced as `recovering`, so stale locks
//! never outlive the process.

use nession_common::protocol::{ActiveEnvFile, EnvFileRef, EnvSource};
use std::collections::HashMap;
use std::sync::RwLock;

/// A single env-file application on a session.
#[derive(Debug, Clone)]
struct Usage {
    name: String,
    source: EnvSource,
    agent_id: Option<String>,
    /// "create" or "attach".
    phase: String,
    /// Identifier of the client that applied it (best-effort).
    applied_by: Option<String>,
}

impl Usage {
    fn to_active(&self) -> ActiveEnvFile {
        ActiveEnvFile {
            name: self.name.clone(),
            source: self.source,
            agent_id: self.agent_id.clone(),
            phase: self.phase.clone(),
            applied_by: self.applied_by.clone(),
        }
    }

    /// Whether this usage refers to the same file as `key`.
    fn matches(&self, key: &FileKey) -> bool {
        self.name == key.name && self.source == key.source && self.agent_id == key.agent_id
    }
}

/// Identity of an env file for lock checks (name + source + owning agent).
#[derive(Debug, Clone, PartialEq, Eq)]
struct FileKey {
    name: String,
    source: EnvSource,
    agent_id: Option<String>,
}

impl FileKey {
    fn from_ref(r: &EnvFileRef) -> Self {
        Self {
            name: r.name.clone(),
            source: r.source,
            agent_id: r.agent_id.clone(),
        }
    }
}

/// Tracks env-file usage across sessions.
pub struct EnvUsageRegistry {
    // session_id -> list of usages
    sessions: RwLock<HashMap<String, Vec<Usage>>>,
}

impl Default for EnvUsageRegistry {
    fn default() -> Self {
        Self::new()
    }
}

impl EnvUsageRegistry {
    #[must_use]
    pub fn new() -> Self {
        Self {
            sessions: RwLock::new(HashMap::new()),
        }
    }

    /// Record env files applied to a session at create time.
    /// Skips files that already have a usage record for the same phase (idempotent).
    pub fn record_create(&self, session_id: &str, files: &[EnvFileRef], applied_by: Option<&str>) {
        let mut sessions = self
            .sessions
            .write()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let entry = sessions.entry(session_id.to_string()).or_default();
        for f in files {
            let key = FileKey::from_ref(f);
            if entry.iter().any(|u| u.matches(&key) && u.phase == "create") {
                continue;
            }
            entry.push(Usage {
                name: f.name.clone(),
                source: f.source,
                agent_id: f.agent_id.clone(),
                phase: "create".to_string(),
                applied_by: applied_by.map(str::to_string),
            });
        }
    }

    /// Record env files applied to a session at attach time.
    /// Skips files that already have a usage record for the same phase (idempotent).
    pub fn record_attach(&self, session_id: &str, files: &[EnvFileRef], applied_by: Option<&str>) {
        let mut sessions = self
            .sessions
            .write()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let entry = sessions.entry(session_id.to_string()).or_default();
        for f in files {
            let key = FileKey::from_ref(f);
            if entry.iter().any(|u| u.matches(&key) && u.phase == "attach") {
                continue;
            }
            entry.push(Usage {
                name: f.name.clone(),
                source: f.source,
                agent_id: f.agent_id.clone(),
                phase: "attach".to_string(),
                applied_by: applied_by.map(str::to_string),
            });
        }
    }

    /// Remove specific attach-time usages for a session (on detach).
    /// Only removes entries whose phase is "attach" and that match one of the
    /// given files (optionally scoped to the applying client).
    pub fn remove_attach(&self, session_id: &str, files: &[EnvFileRef], applied_by: Option<&str>) {
        let mut sessions = self
            .sessions
            .write()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        if let Some(usages) = sessions.get_mut(session_id) {
            let keys: Vec<FileKey> = files.iter().map(FileKey::from_ref).collect();
            usages.retain(|u| {
                if u.phase != "attach" {
                    return true;
                }
                let key = FileKey {
                    name: u.name.clone(),
                    source: u.source,
                    agent_id: u.agent_id.clone(),
                };
                let file_matches = keys.contains(&key);
                let owner_matches = applied_by.is_none_or(|by| u.applied_by.as_deref() == Some(by));
                // Keep entries that don't match the (file, owner) selection.
                !(file_matches && owner_matches)
            });
            if usages.is_empty() {
                sessions.remove(session_id);
            }
        }
    }

    /// Drop all usage for a session (on session destroy / gone).
    pub fn clear_session(&self, session_id: &str) {
        let mut sessions = self
            .sessions
            .write()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        sessions.remove(session_id);
    }

    /// Return the active env files for a session (for visibility).
    #[must_use]
    pub fn active_for(&self, session_id: &str) -> Vec<ActiveEnvFile> {
        let sessions = self
            .sessions
            .read()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        sessions
            .get(session_id)
            .map(|u| u.iter().map(Usage::to_active).collect())
            .unwrap_or_default()
    }

    /// Return the session ids currently using the given file.
    #[must_use]
    pub fn sessions_using(
        &self,
        name: &str,
        source: EnvSource,
        agent_id: Option<&str>,
    ) -> Vec<String> {
        let key = FileKey {
            name: name.to_string(),
            source,
            agent_id: agent_id.map(str::to_string),
        };
        let sessions = self
            .sessions
            .read()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let mut result: Vec<String> = sessions
            .iter()
            .filter(|(_, usages)| usages.iter().any(|u| u.matches(&key)))
            .map(|(sid, _)| sid.clone())
            .collect();
        result.sort();
        result
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn file_ref(name: &str) -> EnvFileRef {
        EnvFileRef {
            name: name.to_string(),
            source: EnvSource::Server,
            agent_id: None,
        }
    }

    #[test]
    fn create_then_lock_visible() {
        let reg = EnvUsageRegistry::new();
        reg.record_create("agent:s1", &[file_ref("a.env")], Some("alice"));
        assert_eq!(
            reg.sessions_using("a.env", EnvSource::Server, None),
            vec!["agent:s1".to_string()]
        );
        let active = reg.active_for("agent:s1");
        assert_eq!(active.len(), 1);
        assert_eq!(active.first().unwrap().phase, "create");
        assert_eq!(active.first().unwrap().applied_by.as_deref(), Some("alice"));
    }

    #[test]
    fn clear_session_releases_lock() {
        let reg = EnvUsageRegistry::new();
        reg.record_create("agent:s1", &[file_ref("a.env")], None);
        reg.clear_session("agent:s1");
        assert!(reg
            .sessions_using("a.env", EnvSource::Server, None)
            .is_empty());
    }

    #[test]
    fn remove_attach_scoped_to_owner() {
        let reg = EnvUsageRegistry::new();
        reg.record_attach("agent:s1", &[file_ref("a.env")], Some("alice"));
        reg.record_attach("agent:s1", &[file_ref("b.env")], Some("bob"));
        // Bob detaching removes only his file.
        reg.remove_attach("agent:s1", &[file_ref("b.env")], Some("bob"));
        let names: Vec<String> = reg
            .active_for("agent:s1")
            .into_iter()
            .map(|a| a.name)
            .collect();
        assert_eq!(names, vec!["a.env".to_string()]);
    }

    #[test]
    fn remove_attach_does_not_touch_create() {
        let reg = EnvUsageRegistry::new();
        reg.record_create("agent:s1", &[file_ref("a.env")], None);
        reg.remove_attach("agent:s1", &[file_ref("a.env")], None);
        // create-phase usage survives an attach removal
        assert_eq!(reg.active_for("agent:s1").len(), 1);
    }

    #[test]
    fn record_attach_is_idempotent() {
        let reg = EnvUsageRegistry::new();
        let f = file_ref("a.env");
        // Same file attached twice should only produce one record.
        reg.record_attach("agent:s1", &[f.clone()], Some("alice"));
        reg.record_attach("agent:s1", &[f], Some("alice"));
        assert_eq!(reg.active_for("agent:s1").len(), 1);
    }

    #[test]
    fn multiple_sessions_using_same_file() {
        let reg = EnvUsageRegistry::new();
        reg.record_create("agent:s1", &[file_ref("shared.env")], None);
        reg.record_attach("agent:s2", &[file_ref("shared.env")], None);
        assert_eq!(
            reg.sessions_using("shared.env", EnvSource::Server, None),
            vec!["agent:s1".to_string(), "agent:s2".to_string()]
        );
    }
}

pub mod broker;
