use anyhow::Context;
use std::path::Path;
use tracing::{error, info};
use tracing_subscriber::{layer::SubscriberExt, util::SubscriberInitExt, EnvFilter};

use nession_common::config::ServerConfig;
use nession_server::db::Database;
use nession_server::server::WebSocketServer;

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    // Initialize tracing/logging
    tracing_subscriber::registry()
        .with(
            EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "nession_server=info,tower_http=info".into()),
        )
        .with(tracing_subscriber::fmt::layer())
        .init();

    info!("Starting nession-server");

    // Load configuration
    let config = load_config()?;
    info!(
        "Configuration loaded: listen_address={}, db_path={}",
        config.listen_address, config.db_path
    );

    // Ensure component directories exist
    nession_common::paths::ensure_component_dirs()
        .context("failed to create nession component directories")?;

    // Initialize database
    info!("Initializing database at {}", config.db_path);
    let database = Database::new(&config.db_path).await?;
    info!("Database initialized successfully");

    // Create and run WebSocket server
    info!("Creating WebSocket server");
    let mut server = WebSocketServer::new(config, std::sync::Arc::new(database)).await?;

    info!("Starting WebSocket server");
    if let Err(e) = server.run().await {
        error!("Server error: {}", e);
        return Err(e);
    }

    Ok(())
}

fn load_config() -> anyhow::Result<ServerConfig> {
    let config_path = "config.toml";

    if Path::new(config_path).exists() {
        info!("Loading configuration from {}", config_path);
        let config_str = std::fs::read_to_string(config_path)?;
        let config: ServerConfig = toml::from_str(&config_str)?;
        Ok(config)
    } else {
        info!("No config.toml found, using default configuration");
        Ok(ServerConfig {
            listen_address: "127.0.0.1:8080".to_string(),
            tls_cert_path: String::new(),
            tls_key_path: String::new(),
            auth_token: String::new(),
            heartbeat_interval_secs: 10,
            heartbeat_timeout_secs: 30,
            db_path: nession_common::paths::server_db_path()
                .unwrap_or_else(|_| std::path::PathBuf::from("nession.db"))
                .to_string_lossy()
                .into_owned(),
        })
    }
}

use chrono::{DateTime, Utc};
use nession_common::protocol::AgentMetadata;
use std::collections::HashMap;
use std::sync::Arc;
use tokio::sync::RwLock;

#[derive(Debug, Clone)]
pub struct AgentInfo {
    pub agent_id: String,
    pub hostname: String,
    pub ip_address: String,
    pub port: u16,
    /// Public WebSocket URL clients use to connect to this agent.
    /// When `None`, the server constructs `ws://{ip_address}:{port}/ws`.
    pub connect_url: Option<String>,
    pub registered_at: DateTime<Utc>,
    pub last_heartbeat: DateTime<Utc>,
    pub status: AgentStatus,
    pub metadata: AgentMetadata,
    pub session_count: u32,
    pub active_sessions: u32,
}

#[derive(Debug, Clone, PartialEq)]
pub enum AgentStatus {
    Online,
    Offline,
    Degraded,
}

pub struct AgentRegistry {
    agents: Arc<RwLock<HashMap<String, AgentInfo>>>,
    heartbeat_timeout_secs: u64,
}

impl AgentRegistry {
    pub fn new(heartbeat_timeout_secs: u64) -> Self {
        Self {
            agents: Arc::new(RwLock::new(HashMap::new())),
            heartbeat_timeout_secs,
        }
    }

    pub async fn register(&self, info: AgentInfo) {
        let mut agents = self.agents.write().await;
        agents.insert(info.agent_id.clone(), info);
    }

    pub async fn update_heartbeat(&self, agent_id: &str, session_count: u32, active_sessions: u32) {
        let mut agents = self.agents.write().await;
        if let Some(agent) = agents.get_mut(agent_id) {
            agent.last_heartbeat = Utc::now();
            agent.status = AgentStatus::Online;
            agent.session_count = session_count;
            agent.active_sessions = active_sessions;
        }
    }

    pub async fn get(&self, agent_id: &str) -> Option<AgentInfo> {
        let agents = self.agents.read().await;
        agents.get(agent_id).cloned()
    }

    pub async fn list(&self) -> Vec<AgentInfo> {
        let agents = self.agents.read().await;
        agents.values().cloned().collect()
    }

    pub async fn check_offline_agents(&self) -> Vec<String> {
        let mut agents = self.agents.write().await;
        let now = Utc::now();
        let mut offline = vec![];

        for (agent_id, agent) in agents.iter_mut() {
            if agent.status == AgentStatus::Online {
                let elapsed = (now - agent.last_heartbeat).num_seconds().unsigned_abs();
                if elapsed > self.heartbeat_timeout_secs {
                    agent.status = AgentStatus::Offline;
                    offline.push(agent_id.clone());
                }
            }
        }

        offline
    }

    pub async fn unregister(&self, agent_id: &str) {
        let mut agents = self.agents.write().await;
        agents.remove(agent_id);
    }
}

pub mod agent;
pub mod session;

pub use agent::{AgentInfo, AgentRegistry, AgentStatus};
pub use session::{SessionInfo, SessionRegistry, SessionStatus};

use crate::db::Database;
use chrono::{DateTime, Utc};
use std::collections::HashMap;
use std::sync::Arc;
use tokio::sync::RwLock;

#[derive(Debug, Clone)]
pub struct SessionInfo {
    pub session_id: String,
    pub agent_id: String,
    pub session_name: String,
    pub status: SessionStatus,
    pub window_count: u32,
    pub attached_clients: u32,
    pub created_at: DateTime<Utc>,
    pub last_activity: DateTime<Utc>,
}

#[derive(Debug, Clone, PartialEq)]
pub enum SessionStatus {
    Active,
    Detached,
    Recovering,
    Orphaned,
    Zombie,
}

pub struct SessionRegistry {
    sessions: Arc<RwLock<HashMap<String, SessionInfo>>>,
    db: Arc<Database>,
}

impl SessionRegistry {
    pub fn new(db: Arc<Database>) -> Self {
        Self {
            sessions: Arc::new(RwLock::new(HashMap::new())),
            db,
        }
    }

    pub async fn load_from_db(&self) {
        match self.db.list_all_sessions().await {
            Ok(rows) => {
                let mut sessions = self.sessions.write().await;
                for row in rows {
                    let created_at =
                        DateTime::from_timestamp(row.created_at, 0).unwrap_or(Utc::now());
                    let last_activity =
                        DateTime::from_timestamp(row.last_activity, 0).unwrap_or(Utc::now());
                    let status = match row.status.as_str() {
                        "active" => SessionStatus::Active,
                        "detached" => SessionStatus::Detached,
                        "zombie" => SessionStatus::Zombie,
                        _ => SessionStatus::Recovering,
                    };
                    let info = SessionInfo {
                        session_id: row.session_id.clone(),
                        agent_id: row.agent_id,
                        session_name: row.session_name,
                        status,
                        window_count: row.window_count,
                        attached_clients: row.attached_clients,
                        created_at,
                        last_activity,
                    };
                    tracing::info!(
                        "Loaded session {} (agent: {}, status: {:?})",
                        info.session_id,
                        info.agent_id,
                        info.status
                    );
                    sessions.insert(row.session_id, info);
                }
                tracing::info!(
                    "Loaded {} sessions from database (recovering)",
                    sessions.len()
                );
            }
            Err(e) => {
                tracing::error!("Failed to load sessions from database: {:#}", e);
            }
        }
    }

    pub async fn update_session(&self, session: SessionInfo) {
        let status_str = match session.status {
            SessionStatus::Active => "active",
            SessionStatus::Detached => "detached",
            SessionStatus::Recovering => "recovering",
            SessionStatus::Orphaned => "orphaned",
            SessionStatus::Zombie => "zombie",
        };

        // Write through to SQLite first, then update in-memory.
        // DB write failure is logged but does not block the in-memory update.
        if let Err(e) = self.db.insert_session(&session, status_str).await {
            tracing::error!("Failed to persist session {}: {:#}", session.session_id, e);
        }

        let mut sessions = self.sessions.write().await;
        sessions.insert(session.session_id.clone(), session);
    }

    pub async fn get(&self, session_id: &str) -> Option<SessionInfo> {
        let sessions = self.sessions.read().await;
        sessions.get(session_id).cloned()
    }

    pub async fn list(&self) -> Vec<SessionInfo> {
        let sessions = self.sessions.read().await;
        sessions.values().cloned().collect()
    }

    pub async fn list_by_agent(&self, agent_id: &str) -> Vec<SessionInfo> {
        let sessions = self.sessions.read().await;
        sessions
            .values()
            .filter(|s| s.agent_id == agent_id)
            .cloned()
            .collect()
    }

    pub async fn remove(&self, session_id: &str) {
        if let Err(e) = self.db.delete_session(session_id).await {
            tracing::error!("Failed to delete session {} from DB: {:#}", session_id, e);
        }
        let mut sessions = self.sessions.write().await;
        sessions.remove(session_id);
    }

    pub async fn remove_by_agent(&self, agent_id: &str) {
        if let Err(e) = self.db.delete_sessions_by_agent(agent_id).await {
            tracing::error!(
                "Failed to delete sessions for agent {} from DB: {:#}",
                agent_id,
                e
            );
        }
        let mut sessions = self.sessions.write().await;
        sessions.retain(|_, s| s.agent_id != agent_id);
    }
}

use std::collections::HashMap;
use tokio::sync::{oneshot, RwLock};
use tokio_tungstenite::tungstenite::Message as WsMessage;
use tracing::{debug, warn};

/// Sender for outgoing WebSocket messages.
///
/// Wraps an `mpsc::UnboundedSender` so that the concrete sink type (which differs
/// between plain-TCP and TLS paths) is hidden behind a transport-agnostic channel.
/// The WebSocket loop spawns a small relay task that drains the receiver and
/// forwards each message to the real sink.
#[derive(Clone)]
pub struct WsMessageSender(tokio::sync::mpsc::UnboundedSender<WsMessage>);

impl WsMessageSender {
    pub fn new() -> (Self, tokio::sync::mpsc::UnboundedReceiver<WsMessage>) {
        let (tx, rx) = tokio::sync::mpsc::unbounded_channel();
        (Self(tx), rx)
    }

    pub fn send(
        &self,
        msg: WsMessage,
    ) -> Result<(), tokio::sync::mpsc::error::SendError<WsMessage>> {
        self.0.send(msg)
    }
}

/// Per-agent control state: the message sender and pending command receivers.
pub struct AgentControl {
    pub sender: WsMessageSender,
    pub pending_commands: HashMap<String, oneshot::Sender<serde_json::Value>>,
}

/// Bridges client requests to agent control connections.
///
/// Uses a nested map: agent_id → (request_id → oneshot::Sender).
/// When an agent disconnects, `unregister_agent` drops the inner map,
/// resolving all pending oneshots with `RecvError` automatically.
pub struct CommandBroker {
    agents: RwLock<HashMap<String, AgentControl>>,
}

impl Default for CommandBroker {
    fn default() -> Self {
        Self::new()
    }
}

impl CommandBroker {
    pub fn new() -> Self {
        Self {
            agents: RwLock::new(HashMap::new()),
        }
    }

    /// Register an agent's control connection sender.
    pub async fn register_agent(&self, agent_id: &str, sender: WsMessageSender) {
        let mut agents = self.agents.write().await;
        agents.insert(
            agent_id.to_string(),
            AgentControl {
                sender,
                pending_commands: HashMap::new(),
            },
        );
        debug!("CommandBroker: registered agent {}", agent_id);
    }

    /// Remove an agent and resolve all its pending commands with errors.
    pub async fn unregister_agent(&self, agent_id: &str) {
        let mut agents = self.agents.write().await;
        if agents.remove(agent_id).is_some() {
            debug!("CommandBroker: unregistered agent {}", agent_id);
        }
    }

    /// Send a command to an agent and return a oneshot receiver for the response.
    ///
    /// If the agent is not found, returns a receiver that immediately errors.
    pub async fn send_command(
        &self,
        agent_id: &str,
        msg_type: &str,
        request_id: &str,
        payload: serde_json::Value,
    ) -> oneshot::Receiver<serde_json::Value> {
        let (tx, rx) = oneshot::channel();

        let mut agents = self.agents.write().await;
        let agent = match agents.get_mut(agent_id) {
            Some(a) => a,
            None => {
                warn!("CommandBroker: agent {} not found", agent_id);
                drop(tx);
                return rx;
            }
        };

        agent.pending_commands.insert(request_id.to_string(), tx);

        let msg = nession_common::protocol::Message {
            msg_type: msg_type.to_string(),
            id: uuid::Uuid::new_v4().to_string(),
            timestamp: std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap_or_default()
                .as_secs(),
            payload,
        };

        let json = match serde_json::to_string(&msg) {
            Ok(j) => j,
            Err(e) => {
                warn!("CommandBroker: failed to serialize command: {}", e);
                agent.pending_commands.remove(request_id);
                return rx;
            }
        };

        let sender = agent.sender.clone();
        drop(agents);

        let req_id = request_id.to_string();
        let aid = agent_id.to_string();
        let mt = msg_type.to_string();

        // Send the command through the channel
        match sender.send(WsMessage::Text(json)) {
            Ok(_) => {
                debug!(
                    "CommandBroker: sent {} to agent {} (req: {})",
                    mt, aid, req_id
                );
            }
            Err(e) => {
                warn!(
                    "CommandBroker: failed to send command to agent {}: {}",
                    aid, e
                );
            }
        }

        rx
    }

    /// Resolve a pending command with a response from the agent.
    /// Returns true if a pending command was found and resolved.
    pub async fn resolve_command(
        &self,
        agent_id: &str,
        request_id: &str,
        response: serde_json::Value,
    ) -> bool {
        let mut agents = self.agents.write().await;
        let agent = match agents.get_mut(agent_id) {
            Some(a) => a,
            None => return false,
        };

        if let Some(tx) = agent.pending_commands.remove(request_id) {
            let _ = tx.send(response);
            true
        } else {
            debug!(
                "CommandBroker: no pending command {} for agent {}",
                request_id, agent_id
            );
            false
        }
    }
}

use serde_json::json;
use std::sync::Arc;
use std::time::Duration;
use tokio_tungstenite::tungstenite::Message;
use tracing::{info, warn};

use crate::env::EnvService;
use crate::registry::{AgentInfo, AgentRegistry, AgentStatus, SessionRegistry, SessionStatus};
use crate::server::command_broker::CommandBroker;
use nession_common::env_file::parse_env;
use nession_common::protocol::{
    AgentRegisterPayload, EnvFileRef, EnvSnapshot, EnvSource, ProtocolMessage,
};

/// Action returned by the connection handler after processing a message.
pub enum HandlerAction {
    /// Send an optional reply message back to the sender.
    Reply(Option<Message>),
    /// Enter relay mode: forward messages between this client and the agent
    /// at the given WebSocket address.
    Relay { agent_ws_url: String },
    /// Close the connection.
    Close,
}

pub struct ConnectionHandler {
    agent_registry: Arc<AgentRegistry>,
    session_registry: Arc<SessionRegistry>,
    command_broker: Arc<CommandBroker>,
    env_service: Arc<EnvService>,
    server_auth_token: String,
    /// Heartbeat interval (seconds) advertised to agents on registration.
    heartbeat_interval_secs: u64,
    authenticated_client: bool,
    registered_agent_id: Option<String>,
}

impl ConnectionHandler {
    pub fn new(
        agent_registry: Arc<AgentRegistry>,
        session_registry: Arc<SessionRegistry>,
        command_broker: Arc<CommandBroker>,
        env_service: Arc<EnvService>,
        server_auth_token: String,
        heartbeat_interval_secs: u64,
    ) -> Self {
        Self {
            agent_registry,
            session_registry,
            command_broker,
            env_service,
            server_auth_token,
            heartbeat_interval_secs,
            authenticated_client: false,
            registered_agent_id: None,
        }
    }

    pub fn registered_agent_id(&self) -> Option<&String> {
        self.registered_agent_id.as_ref()
    }

    pub async fn handle_message(&mut self, msg: Message) -> anyhow::Result<HandlerAction> {
        match msg {
            Message::Text(text) => {
                let protocol_msg: ProtocolMessage<serde_json::Value> = serde_json::from_str(&text)?;
                self.handle_protocol_message(protocol_msg).await
            }
            Message::Close(_) => {
                info!("Client disconnected");
                Ok(HandlerAction::Close)
            }
            _ => Ok(HandlerAction::Reply(None)),
        }
    }

    async fn handle_protocol_message(
        &mut self,
        msg: ProtocolMessage<serde_json::Value>,
    ) -> anyhow::Result<HandlerAction> {
        // Log all agent-originated messages at info for diagnostics
        if msg.msg_type.starts_with("agent.") {
            info!(
                "Received agent message: type={}, id={}",
                msg.msg_type, msg.id
            );
        }
        match msg.msg_type.as_str() {
            "agent.register" => self.handle_agent_register(msg).await,
            "agent.heartbeat" => self.handle_agent_heartbeat(msg).await,
            "agent.session.update" => self.handle_agent_session_update(msg).await,
            "agent.session.command.response" => self.handle_agent_command_response(msg).await,
            "client.auth" => self.handle_client_auth(msg).await,
            "client.agents.list" => self.handle_client_agents_list(msg).await,
            "client.sessions.list" => self.handle_client_sessions_list(msg).await,
            "client.session.attach" => self.handle_client_session_attach(msg).await,
            "client.session.create" => self.handle_client_session_create(msg).await,
            "client.session.kill" => self.handle_client_session_kill(msg).await,
            "client.env.list" => self.handle_client_env_list(msg).await,
            "client.env.get" => self.handle_client_env_get(msg).await,
            "client.env.write" => self.handle_client_env_write(msg).await,
            "client.env.delete" => self.handle_client_env_delete(msg).await,
            "client.session.env.apply" => self.handle_client_session_env_apply(msg).await,
            "client.session.env.unset" => self.handle_client_session_env_unset(msg).await,
            "client.session.env.active" => self.handle_client_session_env_active(msg).await,
            _ => {
                warn!("Unknown message type: {}", msg.msg_type);
                Ok(HandlerAction::Reply(None))
            }
        }
    }

    async fn handle_agent_register(
        &mut self,
        msg: ProtocolMessage<serde_json::Value>,
    ) -> anyhow::Result<HandlerAction> {
        let payload: AgentRegisterPayload = serde_json::from_value(msg.payload)?;

        // Empty server auth_token means no-auth mode: accept any agent
        let auth_ok =
            self.server_auth_token.is_empty() || payload.auth_token == self.server_auth_token;

        if !auth_ok {
            info!("Agent {} rejected: invalid auth token", payload.agent_id);
            return Ok(HandlerAction::Reply(Some(Message::Text(
                json!({
                    "msg_type": "agent.register.response",
                    "id": msg.id,
                    "timestamp": current_timestamp(),
                    "payload": {
                        "status": "rejected",
                        "message": "Invalid auth token"
                    }
                })
                .to_string(),
            ))));
        }

        let agent_info = AgentInfo {
            agent_id: payload.agent_id.clone(),
            hostname: payload.hostname,
            ip_address: payload.ip_address,
            port: payload.port,
            connect_url: payload.connect_url.clone(),
            registered_at: chrono::Utc::now(),
            last_heartbeat: chrono::Utc::now(),
            status: AgentStatus::Online,
            metadata: payload.metadata,
            session_count: 0,
            active_sessions: 0,
        };

        self.agent_registry.register(agent_info).await;
        self.registered_agent_id = Some(payload.agent_id.clone());

        info!("Agent {} registered successfully", payload.agent_id);

        Ok(HandlerAction::Reply(Some(Message::Text(
            json!({
                "msg_type": "agent.register.response",
                "id": msg.id,
                "timestamp": current_timestamp(),
                "payload": {
                    "status": "accepted",
                    "message": "Registration successful",
                    "heartbeat_interval_secs": self.heartbeat_interval_secs
                }
            })
            .to_string(),
        ))))
    }

    async fn handle_agent_heartbeat(
        &mut self,
        msg: ProtocolMessage<serde_json::Value>,
    ) -> anyhow::Result<HandlerAction> {
        let payload: serde_json::Value = msg.payload;
        let agent_id = payload
            .get("agent_id")
            .and_then(|v| v.as_str())
            .unwrap_or("");

        if self.agent_registry.get(agent_id).await.is_none() {
            warn!("Heartbeat from unregistered agent: {}", agent_id);
            return Ok(HandlerAction::Reply(None));
        }

        let session_count = u32::try_from(
            payload
                .get("session_count")
                .and_then(serde_json::Value::as_u64)
                .unwrap_or(0),
        )
        .unwrap_or(0);
        let active_sessions = u32::try_from(
            payload
                .get("active_sessions")
                .and_then(serde_json::Value::as_u64)
                .unwrap_or(0),
        )
        .unwrap_or(0);

        info!(
            "Heartbeat from {}: sessions={}, active={}",
            agent_id, session_count, active_sessions
        );

        self.agent_registry
            .update_heartbeat(agent_id, session_count, active_sessions)
            .await;

        // Acknowledge so the agent can confirm the link is healthy in both
        // directions and reset its own miss counter.
        Ok(HandlerAction::Reply(Some(Message::Text(
            json!({
                "msg_type": "server.heartbeat.ack",
                "id": msg.id,
                "timestamp": current_timestamp(),
                "payload": {
                    "agent_id": agent_id,
                    "server_time": current_timestamp()
                }
            })
            .to_string(),
        ))))
    }

    async fn handle_agent_session_update(
        &mut self,
        msg: ProtocolMessage<serde_json::Value>,
    ) -> anyhow::Result<HandlerAction> {
        let payload: serde_json::Value = msg.payload;
        let agent_id = payload
            .get("agent_id")
            .and_then(|v| v.as_str())
            .unwrap_or("");
        let session_name = payload
            .get("session_name")
            .and_then(|v| v.as_str())
            .unwrap_or("");
        let status_str = payload.get("status").and_then(|v| v.as_str()).unwrap_or("");

        if self.agent_registry.get(agent_id).await.is_none() {
            warn!("Session update from unregistered agent: {}", agent_id);
            return Ok(HandlerAction::Reply(None));
        }

        let session_id = format!("{agent_id}:{session_name}");

        if status_str == "gone" {
            info!("Session {} removed (agent: {})", session_name, agent_id);
            self.session_registry.remove(&session_id).await;
            return Ok(HandlerAction::Reply(None));
        }

        let status = match status_str {
            "active" => crate::registry::session::SessionStatus::Active,
            "detached" => crate::registry::session::SessionStatus::Detached,
            "recovering" => crate::registry::session::SessionStatus::Recovering,
            "orphaned" => crate::registry::session::SessionStatus::Orphaned,
            "zombie" => crate::registry::session::SessionStatus::Zombie,
            _ => {
                warn!("Unknown session status '{}' for {}", status_str, session_id);
                return Ok(HandlerAction::Reply(None));
            }
        };

        let window_count = u32::try_from(
            payload
                .get("window_count")
                .and_then(serde_json::Value::as_u64)
                .unwrap_or(0),
        )
        .unwrap_or(0);
        let attached_clients = u32::try_from(
            payload
                .get("attached_clients")
                .and_then(serde_json::Value::as_u64)
                .unwrap_or(0),
        )
        .unwrap_or(0);

        let session_info = crate::registry::session::SessionInfo {
            session_id: session_id.clone(),
            agent_id: agent_id.to_string(),
            session_name: session_name.to_string(),
            status,
            window_count,
            attached_clients,
            created_at: chrono::Utc::now(),
            last_activity: chrono::Utc::now(),
        };

        info!(
            "Session {} updated (agent: {}, status: {:?}, windows: {}, clients: {})",
            session_name, agent_id, session_info.status, window_count, attached_clients
        );
        self.session_registry.update_session(session_info).await;

        Ok(HandlerAction::Reply(None))
    }

    async fn handle_client_auth(
        &mut self,
        msg: ProtocolMessage<serde_json::Value>,
    ) -> anyhow::Result<HandlerAction> {
        let payload: serde_json::Value = msg.payload;
        let auth_token = payload
            .get("auth_token")
            .and_then(|v| v.as_str())
            .unwrap_or("");

        // Empty server auth_token means no-auth mode: accept any client
        let auth_ok = self.server_auth_token.is_empty() || auth_token == self.server_auth_token;

        if auth_ok {
            self.authenticated_client = true;
            info!("Client authenticated successfully");

            Ok(HandlerAction::Reply(Some(Message::Text(
                json!({
                    "msg_type": "client.auth.response",
                    "id": msg.id,
                    "timestamp": current_timestamp(),
                    "payload": {
                        "status": "success",
                        "message": "Authentication successful"
                    }
                })
                .to_string(),
            ))))
        } else {
            info!("Client authentication failed");

            Ok(HandlerAction::Reply(Some(Message::Text(
                json!({
                    "msg_type": "client.auth.response",
                    "id": msg.id,
                    "timestamp": current_timestamp(),
                    "payload": {
                        "status": "failed",
                        "message": "Invalid auth token"
                    }
                })
                .to_string(),
            ))))
        }
    }

    /// Handle `client.agents.list` - returns all registered agents.
    async fn handle_client_agents_list(
        &mut self,
        msg: ProtocolMessage<serde_json::Value>,
    ) -> anyhow::Result<HandlerAction> {
        if !self.authenticated_client {
            warn!("Unauthenticated client requested agents list");
            return Ok(HandlerAction::Reply(Some(Message::Text(
                json!({
                    "msg_type": "client.agents.list.response",
                    "id": msg.id,
                    "timestamp": current_timestamp(),
                    "payload": {
                        "status": "error",
                        "message": "Not authenticated"
                    }
                })
                .to_string(),
            ))));
        }

        let agents = self.agent_registry.list().await;

        let agents_json: Vec<serde_json::Value> = agents
            .iter()
            .map(|a| {
                json!({
                    "agent_id": a.agent_id,
                    "hostname": a.hostname,
                    "ip_address": a.ip_address,
                    "port": a.port,
                    "status": match a.status {
                        AgentStatus::Online => "online",
                        AgentStatus::Offline => "offline",
                        AgentStatus::Degraded => "degraded",
                    },
                    "session_count": a.session_count,
                    "active_sessions": a.active_sessions,
                    "last_heartbeat": a.last_heartbeat.to_rfc3339(),
                    "metadata": {
                        "nession_version": a.metadata.nession_version,
                        "tmux_version": a.metadata.tmux_version,
                        "os_version": a.metadata.os_version,
                    },
                })
            })
            .collect();

        info!(
            "Client requested agents list, returning {} agents",
            agents_json.len()
        );

        Ok(HandlerAction::Reply(Some(Message::Text(
            json!({
                "msg_type": "client.agents.list.response",
                "id": msg.id,
                "timestamp": current_timestamp(),
                "payload": {
                    "agents": agents_json
                }
            })
            .to_string(),
        ))))
    }

    /// Handle `client.sessions.list` - returns all sessions, optionally filtered by agent_id.
    async fn handle_client_sessions_list(
        &mut self,
        msg: ProtocolMessage<serde_json::Value>,
    ) -> anyhow::Result<HandlerAction> {
        if !self.authenticated_client {
            warn!("Unauthenticated client requested sessions list");
            return Ok(HandlerAction::Reply(Some(Message::Text(
                json!({
                    "msg_type": "client.sessions.list.response",
                    "id": msg.id,
                    "timestamp": current_timestamp(),
                    "payload": {
                        "status": "error",
                        "message": "Not authenticated"
                    }
                })
                .to_string(),
            ))));
        }

        let agent_id = msg.payload.get("agent_id").and_then(|v| v.as_str());

        let sessions = if let Some(aid) = agent_id {
            self.session_registry.list_by_agent(aid).await
        } else {
            self.session_registry.list().await
        };

        let sessions_json: Vec<serde_json::Value> = sessions
            .iter()
            .map(|s| {
                json!({
                    "session_id": s.session_id,
                    "agent_id": s.agent_id,
                    "session_name": s.session_name,
                    "status": match s.status {
                        SessionStatus::Active => "active",
                        SessionStatus::Detached => "detached",
                        SessionStatus::Recovering => "recovering",
                        SessionStatus::Orphaned => "orphaned",
                        SessionStatus::Zombie => "zombie",
                    },
                    "window_count": s.window_count,
                    "attached_clients": s.attached_clients,
                    "last_activity": s.last_activity.to_rfc3339(),
                })
            })
            .collect();

        info!(
            "Client requested sessions list, returning {} sessions",
            sessions_json.len()
        );

        Ok(HandlerAction::Reply(Some(Message::Text(
            json!({
                "msg_type": "client.sessions.list.response",
                "id": msg.id,
                "timestamp": current_timestamp(),
                "payload": {
                    "sessions": sessions_json
                }
            })
            .to_string(),
        ))))
    }

    /// Handle `client.session.attach` - returns P2P agent address or enters relay mode.
    ///
    /// In P2P mode, the response includes the agent's IP:port so the client can
    /// connect directly. In relay mode, the server opens a WebSocket to the agent
    /// and bidirectionally forwards terminal I/O.
    async fn handle_client_session_attach(
        &mut self,
        msg: ProtocolMessage<serde_json::Value>,
    ) -> anyhow::Result<HandlerAction> {
        if !self.authenticated_client {
            return Ok(HandlerAction::Reply(Some(Message::Text(
                json!({
                    "msg_type": "client.session.attach.response",
                    "id": msg.id,
                    "timestamp": current_timestamp(),
                    "payload": {
                        "status": "error",
                        "message": "Not authenticated"
                    }
                })
                .to_string(),
            ))));
        }

        let session_id = msg
            .payload
            .get("session_id")
            .and_then(|v| v.as_str())
            .unwrap_or("");
        let preferred_mode = msg
            .payload
            .get("preferred_mode")
            .and_then(|v| v.as_str())
            .unwrap_or("p2p");

        // Parse session_id as "agent_id:session_name"
        let (agent_id, session_name) = match session_id.split_once(':') {
            Some((aid, sname)) => (aid.to_string(), sname.to_string()),
            None => {
                return Ok(HandlerAction::Reply(Some(Message::Text(
                    json!({
                        "msg_type": "client.session.attach.response",
                        "id": msg.id,
                        "timestamp": current_timestamp(),
                        "payload": {
                            "status": "error",
                            "message": "Invalid session_id format. Expected 'agent_id:session_name'"
                        }
                    })
                    .to_string(),
                ))));
            }
        };

        // Look up the session in the registry
        let session = self.session_registry.get(session_id).await;
        if session.is_none() {
            return Ok(HandlerAction::Reply(Some(Message::Text(
                json!({
                    "msg_type": "client.session.attach.response",
                    "id": msg.id,
                    "timestamp": current_timestamp(),
                    "payload": {
                        "status": "error",
                        "message": format!("Session '{}' not found", session_id)
                    }
                })
                .to_string(),
            ))));
        }

        // Look up the agent
        let agent = self.agent_registry.get(&agent_id).await;
        let agent = match agent {
            Some(a) if a.status == AgentStatus::Online => a,
            Some(_) => {
                return Ok(HandlerAction::Reply(Some(Message::Text(
                    json!({
                        "msg_type": "client.session.attach.response",
                        "id": msg.id,
                        "timestamp": current_timestamp(),
                        "payload": {
                            "status": "error",
                            "message": format!("Agent '{}' is offline", agent_id)
                        }
                    })
                    .to_string(),
                ))));
            }
            None => {
                return Ok(HandlerAction::Reply(Some(Message::Text(
                    json!({
                        "msg_type": "client.session.attach.response",
                        "id": msg.id,
                        "timestamp": current_timestamp(),
                        "payload": {
                            "status": "error",
                            "message": format!("Agent '{}' not found or offline", agent_id)
                        }
                    })
                    .to_string(),
                ))));
            }
        };

        // Prefer the agent's declared connect_url (k8s ingress / public hostname),
        // falling back to a constructed URL for bare-metal / direct-access deployments.
        // Both produce a complete URL (e.g. "ws://agent.example.com/ws" or "ws://10.0.0.1:19090/ws")
        // so the frontend can use agent_address as-is without further splicing.
        let agent_ws_url = agent
            .connect_url
            .clone()
            .unwrap_or_else(|| format!("ws://{}:{}/ws", agent.ip_address, agent.port));
        let agent_address = agent_ws_url.clone();
        let connection_token = uuid::Uuid::new_v4().to_string();

        info!(
            "Client requested attach to session {} (mode: {}), agent at {}",
            session_id, preferred_mode, agent_ws_url
        );

        if preferred_mode == "relay" {
            // For relay mode, the server will proxy I/O between client and agent.
            // The handler loop must transition into relay mode.
            Ok(HandlerAction::Relay { agent_ws_url })
        } else {
            // P2P mode: return the agent's public WebSocket URL so the client
            // can connect directly. Uses connect_url when configured (k8s),
            // or the raw IP:port otherwise.
            Ok(HandlerAction::Reply(Some(Message::Text(
                json!({
                    "msg_type": "client.session.attach.response",
                    "id": msg.id,
                    "timestamp": current_timestamp(),
                    "payload": {
                        "status": "success",
                        "mode": "p2p",
                        "agent_address": agent_address,
                        "connection_token": connection_token,
                        "session_name": session_name
                    }
                })
                .to_string(),
            ))))
        }
    }

    /// Handle `client.session.create` — create a new session on a target agent.
    async fn handle_client_session_create(
        &mut self,
        msg: ProtocolMessage<serde_json::Value>,
    ) -> anyhow::Result<HandlerAction> {
        if !self.authenticated_client {
            return Ok(HandlerAction::Reply(Some(Message::Text(
                json!({
                    "msg_type": "client.session.create.response",
                    "id": msg.id,
                    "timestamp": current_timestamp(),
                    "payload": {
                        "success": false,
                        "error": "Not authenticated"
                    }
                })
                .to_string(),
            ))));
        }

        let agent_id = msg
            .payload
            .get("agent_id")
            .and_then(|v| v.as_str())
            .unwrap_or("");
        let name = msg
            .payload
            .get("name")
            .and_then(|v| v.as_str())
            .unwrap_or("");

        if agent_id.is_empty() || name.is_empty() {
            return Ok(HandlerAction::Reply(Some(Message::Text(
                json!({
                    "msg_type": "client.session.create.response",
                    "id": msg.id,
                    "timestamp": current_timestamp(),
                    "payload": {
                        "success": false,
                        "error": "agent_id and name are required"
                    }
                })
                .to_string(),
            ))));
        }

        // Check agent exists and is online
        let agent = self.agent_registry.get(agent_id).await;
        match agent {
            Some(a) if a.status == AgentStatus::Online => {}
            Some(_) => {
                return Ok(HandlerAction::Reply(Some(Message::Text(
                    json!({
                        "msg_type": "client.session.create.response",
                        "id": msg.id,
                        "timestamp": current_timestamp(),
                        "payload": {
                            "success": false,
                            "error": format!("Agent '{}' is offline", agent_id)
                        }
                    })
                    .to_string(),
                ))));
            }
            None => {
                return Ok(HandlerAction::Reply(Some(Message::Text(
                    json!({
                        "msg_type": "client.session.create.response",
                        "id": msg.id,
                        "timestamp": current_timestamp(),
                        "payload": {
                            "success": false,
                            "error": format!("Agent '{}' not found", agent_id)
                        }
                    })
                    .to_string(),
                ))));
            }
        }

        let request_id = uuid::Uuid::new_v4().to_string();

        // Optional env files selected for create-time injection.
        let env_refs: Vec<EnvFileRef> = msg
            .payload
            .get("env_files")
            .and_then(|v| serde_json::from_value(v.clone()).ok())
            .unwrap_or_default();

        let env_snapshots = if env_refs.is_empty() {
            Vec::new()
        } else {
            match self.resolve_snapshots(agent_id, &env_refs).await {
                Ok(s) => s,
                Err(e) => {
                    return Ok(HandlerAction::Reply(Some(Message::Text(
                        json!({
                            "msg_type": "client.session.create.response",
                            "id": msg.id,
                            "timestamp": current_timestamp(),
                            "payload": { "success": false, "error": e }
                        })
                        .to_string(),
                    ))));
                }
            }
        };

        info!(
            "Client requested session create on agent {}: name={}, env_files={}",
            agent_id,
            name,
            env_refs.len()
        );

        let rx = self
            .command_broker
            .send_command(
                agent_id,
                "server.session.create",
                &request_id,
                json!({
                    "request_id": request_id,
                    "name": name,
                    "width": 80,
                    "height": 24,
                    "env_snapshots": env_snapshots,
                }),
            )
            .await;

        match tokio::time::timeout(Duration::from_secs(10), rx).await {
            Ok(Ok(response)) => {
                let success = response
                    .get("success")
                    .and_then(serde_json::Value::as_bool)
                    .unwrap_or(false);
                let session_id = if success {
                    let sid = format!("{agent_id}:{name}");
                    // Immediately register the session so it shows up in list
                    // and attach requests without waiting for the agent's
                    // SessionWatcher poll cycle.
                    let session_info = crate::registry::session::SessionInfo {
                        session_id: sid.clone(),
                        agent_id: agent_id.to_string(),
                        session_name: name.to_string(),
                        status: crate::registry::session::SessionStatus::Detached,
                        window_count: 1,
                        attached_clients: 0,
                        created_at: chrono::Utc::now(),
                        last_activity: chrono::Utc::now(),
                    };
                    self.session_registry.update_session(session_info).await;
                    // Record create-time env usage for visibility + in-use lock.
                    if !env_refs.is_empty() {
                        self.env_service.usage.record_create(&sid, &env_refs, None);
                    }
                    Some(sid)
                } else {
                    None
                };
                let error = response
                    .get("error")
                    .and_then(|v| v.as_str())
                    .map(std::string::ToString::to_string);

                Ok(HandlerAction::Reply(Some(Message::Text(
                    json!({
                        "msg_type": "client.session.create.response",
                        "id": msg.id,
                        "timestamp": current_timestamp(),
                        "payload": {
                            "success": success,
                            "session_id": session_id,
                            "error": error,
                        }
                    })
                    .to_string(),
                ))))
            }
            Ok(Err(_)) => Ok(HandlerAction::Reply(Some(Message::Text(
                json!({
                    "msg_type": "client.session.create.response",
                    "id": msg.id,
                    "timestamp": current_timestamp(),
                    "payload": {
                        "success": false,
                        "error": "Agent disconnected"
                    }
                })
                .to_string(),
            )))),
            Err(_) => Ok(HandlerAction::Reply(Some(Message::Text(
                json!({
                    "msg_type": "client.session.create.response",
                    "id": msg.id,
                    "timestamp": current_timestamp(),
                    "payload": {
                        "success": false,
                        "error": "Timeout waiting for agent response"
                    }
                })
                .to_string(),
            )))),
        }
    }

    /// Handle `client.session.kill` — kill a session on its agent.
    async fn handle_client_session_kill(
        &mut self,
        msg: ProtocolMessage<serde_json::Value>,
    ) -> anyhow::Result<HandlerAction> {
        if !self.authenticated_client {
            return Ok(HandlerAction::Reply(Some(Message::Text(
                json!({
                    "msg_type": "client.session.kill.response",
                    "id": msg.id,
                    "timestamp": current_timestamp(),
                    "payload": {
                        "success": false,
                        "error": "Not authenticated"
                    }
                })
                .to_string(),
            ))));
        }

        let session_id = msg
            .payload
            .get("session_id")
            .and_then(|v| v.as_str())
            .unwrap_or("");

        let (agent_id, session_name) = match session_id.split_once(':') {
            Some((aid, sname)) => (aid.to_string(), sname.to_string()),
            None => {
                return Ok(HandlerAction::Reply(Some(Message::Text(
                    json!({
                        "msg_type": "client.session.kill.response",
                        "id": msg.id,
                        "timestamp": current_timestamp(),
                        "payload": {
                            "success": false,
                            "error": "Invalid session_id format. Expected 'agent_id:session_name'"
                        }
                    })
                    .to_string(),
                ))));
            }
        };

        // Check session exists in registry
        let session = self.session_registry.get(session_id).await;
        if session.is_none() {
            let agent = self.agent_registry.get(&agent_id).await;
            match agent {
                Some(a) if a.status != AgentStatus::Online => {
                    self.session_registry.remove(session_id).await;
                    return Ok(HandlerAction::Reply(Some(Message::Text(
                        json!({
                            "msg_type": "client.session.kill.response",
                            "id": msg.id,
                            "timestamp": current_timestamp(),
                            "payload": {
                                "success": true
                            }
                        })
                        .to_string(),
                    ))));
                }
                Some(_) => {
                    return Ok(HandlerAction::Reply(Some(Message::Text(
                        json!({
                            "msg_type": "client.session.kill.response",
                            "id": msg.id,
                            "timestamp": current_timestamp(),
                            "payload": {
                                "success": false,
                                "error": format!("Session '{}' not found", session_id)
                            }
                        })
                        .to_string(),
                    ))));
                }
                None => {
                    return Ok(HandlerAction::Reply(Some(Message::Text(
                        json!({
                            "msg_type": "client.session.kill.response",
                            "id": msg.id,
                            "timestamp": current_timestamp(),
                            "payload": {
                                "success": false,
                                "error": format!("Agent '{}' not found", agent_id)
                            }
                        })
                        .to_string(),
                    ))));
                }
            }
        }

        let request_id = uuid::Uuid::new_v4().to_string();

        info!(
            "Client requested session kill: {} (agent: {})",
            session_name, agent_id
        );

        let rx = self
            .command_broker
            .send_command(
                &agent_id,
                "server.session.kill",
                &request_id,
                json!({
                    "request_id": request_id,
                    "name": session_name,
                }),
            )
            .await;

        match tokio::time::timeout(Duration::from_secs(10), rx).await {
            Ok(Ok(response)) => {
                let success = response
                    .get("success")
                    .and_then(serde_json::Value::as_bool)
                    .unwrap_or(false);
                let error = response
                    .get("error")
                    .and_then(|v| v.as_str())
                    .map(std::string::ToString::to_string);

                if success {
                    self.session_registry.remove(session_id).await;
                    // Session destroyed: create-time env vars are gone with it
                    // (EC7) and any attach-time usage is now moot, so release
                    // all locks this session held.
                    self.env_service.usage.clear_session(session_id);
                }

                Ok(HandlerAction::Reply(Some(Message::Text(
                    json!({
                        "msg_type": "client.session.kill.response",
                        "id": msg.id,
                        "timestamp": current_timestamp(),
                        "payload": {
                            "success": success,
                            "error": error,
                        }
                    })
                    .to_string(),
                ))))
            }
            Ok(Err(_)) => Ok(HandlerAction::Reply(Some(Message::Text(
                json!({
                    "msg_type": "client.session.kill.response",
                    "id": msg.id,
                    "timestamp": current_timestamp(),
                    "payload": {
                        "success": false,
                        "error": "Agent disconnected"
                    }
                })
                .to_string(),
            )))),
            Err(_) => Ok(HandlerAction::Reply(Some(Message::Text(
                json!({
                    "msg_type": "client.session.kill.response",
                    "id": msg.id,
                    "timestamp": current_timestamp(),
                    "payload": {
                        "success": false,
                        "error": "Timeout waiting for agent response"
                    }
                })
                .to_string(),
            )))),
        }
    }

    /// Handle `agent.session.command.response` — resolve a pending command.
    async fn handle_agent_command_response(
        &mut self,
        msg: ProtocolMessage<serde_json::Value>,
    ) -> anyhow::Result<HandlerAction> {
        let agent_id = match &self.registered_agent_id {
            Some(id) => id.clone(),
            None => {
                warn!("agent.session.command.response from unregistered connection");
                return Ok(HandlerAction::Reply(None));
            }
        };

        let request_id = msg
            .payload
            .get("request_id")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .to_string();
        if request_id.is_empty() {
            warn!("agent.session.command.response missing request_id");
            return Ok(HandlerAction::Reply(None));
        }

        info!(
            "Received command response from agent {}: request_id={}, command={}",
            agent_id,
            request_id,
            msg.payload
                .get("command")
                .and_then(|v| v.as_str())
                .unwrap_or("unknown")
        );

        self.command_broker
            .resolve_command(&agent_id, &request_id, msg.payload)
            .await;

        Ok(HandlerAction::Reply(None))
    }

    // ========================================================================
    // Environment-variable file management
    // ========================================================================

    /// Send a command to an agent and await its response (10s timeout).
    /// Returns the response payload, or an error string on timeout/disconnect.
    async fn agent_command(
        &self,
        agent_id: &str,
        msg_type: &str,
        mut payload: serde_json::Value,
    ) -> Result<serde_json::Value, String> {
        let request_id = uuid::Uuid::new_v4().to_string();
        if let Some(obj) = payload.as_object_mut() {
            obj.insert("request_id".to_string(), json!(request_id));
        }
        let rx = self
            .command_broker
            .send_command(agent_id, msg_type, &request_id, payload)
            .await;
        match tokio::time::timeout(Duration::from_secs(10), rx).await {
            Ok(Ok(response)) => Ok(response),
            Ok(Err(_)) => Err("Agent disconnected".to_string()),
            Err(_) => Err("Timeout waiting for agent response".to_string()),
        }
    }

    /// Handle `client.env.list` — aggregate server env files with those from
    /// every online agent (EC6: same filename on both shows twice with badges).
    async fn handle_client_env_list(
        &mut self,
        msg: ProtocolMessage<serde_json::Value>,
    ) -> anyhow::Result<HandlerAction> {
        if !self.authenticated_client {
            return Ok(reply_json(
                &msg.id,
                "client.env.list.response",
                json!({ "files": [], "error": "Not authenticated" }),
            ));
        }

        let mut files = self.env_service.store.list().await.unwrap_or_default();

        // Query each online agent for its local files.
        for agent in self.agent_registry.list().await {
            if agent.status != AgentStatus::Online {
                continue;
            }
            match self
                .agent_command(&agent.agent_id, "server.env.list", json!({}))
                .await
            {
                Ok(resp) => {
                    if let Some(arr) = resp.get("files").and_then(|v| v.as_array()) {
                        for f in arr {
                            if let Ok(info) = serde_json::from_value::<
                                nession_common::protocol::EnvFileInfo,
                            >(f.clone())
                            {
                                files.push(info);
                            }
                        }
                    }
                }
                Err(e) => warn!("env.list from agent {} failed: {}", agent.agent_id, e),
            }
        }

        Ok(reply_json(
            &msg.id,
            "client.env.list.response",
            json!({ "files": files }),
        ))
    }

    /// Handle `client.env.get` — read one env file's content and report which
    /// sessions currently use it (for the in-use lock).
    async fn handle_client_env_get(
        &mut self,
        msg: ProtocolMessage<serde_json::Value>,
    ) -> anyhow::Result<HandlerAction> {
        if !self.authenticated_client {
            return Ok(reply_json(
                &msg.id,
                "client.env.get.response",
                json!({ "success": false, "error": "Not authenticated" }),
            ));
        }
        let (name, source, agent_id) = parse_env_ref(&msg.payload);
        if name.is_empty() {
            return Ok(reply_json(
                &msg.id,
                "client.env.get.response",
                json!({ "success": false, "error": "name is required" }),
            ));
        }

        let in_use_by = self
            .env_service
            .usage
            .sessions_using(&name, source, agent_id.as_deref());

        let result = match source {
            EnvSource::Server => self
                .env_service
                .store
                .read(&name)
                .await
                .map_err(|e| e.to_string()),
            EnvSource::Agent => match &agent_id {
                Some(aid) => self
                    .agent_command(aid, "server.env.get", json!({ "name": name }))
                    .await
                    .and_then(|resp| {
                        if resp.get("success").and_then(serde_json::Value::as_bool) == Some(true) {
                            Ok(resp
                                .get("content")
                                .and_then(|v| v.as_str())
                                .unwrap_or("")
                                .to_string())
                        } else {
                            Err(resp
                                .get("error")
                                .and_then(|v| v.as_str())
                                .unwrap_or("read failed")
                                .to_string())
                        }
                    }),
                None => Err("agent_id is required for agent files".to_string()),
            },
        };

        match result {
            Ok(content) => Ok(reply_json(
                &msg.id,
                "client.env.get.response",
                json!({ "success": true, "content": content, "in_use_by": in_use_by }),
            )),
            Err(e) => Ok(reply_json(
                &msg.id,
                "client.env.get.response",
                json!({ "success": false, "error": e, "in_use_by": in_use_by }),
            )),
        }
    }

    /// Handle `client.env.write` — create/overwrite an env file. Blocks writes
    /// to files currently in use by a running session (SC5/EC10).
    async fn handle_client_env_write(
        &mut self,
        msg: ProtocolMessage<serde_json::Value>,
    ) -> anyhow::Result<HandlerAction> {
        if !self.authenticated_client {
            return Ok(reply_json(
                &msg.id,
                "client.env.write.response",
                json!({ "success": false, "error": "Not authenticated" }),
            ));
        }
        let (name, source, agent_id) = parse_env_ref(&msg.payload);
        let content = msg
            .payload
            .get("content")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .to_string();
        let overwrite = msg
            .payload
            .get("overwrite")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(false);

        if name.is_empty() {
            return Ok(reply_json(
                &msg.id,
                "client.env.write.response",
                json!({ "success": false, "error": "name is required" }),
            ));
        }

        // In-use lock: an overwrite of a file bound to a running session is
        // refused with a clear message listing the sessions.
        if overwrite {
            let in_use = self
                .env_service
                .usage
                .sessions_using(&name, source, agent_id.as_deref());
            if !in_use.is_empty() {
                return Ok(reply_json(
                    &msg.id,
                    "client.env.write.response",
                    json!({
                        "success": false,
                        "error": format!(
                            "This file is in use by session(s): {}. Stop the session or detach before editing.",
                            in_use.join(", ")
                        )
                    }),
                ));
            }
        }

        let warnings = parse_env(&content).warnings;

        let outcome = match source {
            EnvSource::Server => self
                .env_service
                .store
                .write(&name, &content, overwrite)
                .await
                .map_err(|e| e.to_string()),
            EnvSource::Agent => match &agent_id {
                Some(aid) => self
                    .agent_command(
                        aid,
                        "server.env.write",
                        json!({ "name": name, "content": content, "overwrite": overwrite }),
                    )
                    .await
                    .map(|resp| {
                        // Agent returns success=true on write, exists=true when
                        // refused for lack of overwrite.
                        resp.get("success").and_then(serde_json::Value::as_bool) == Some(true)
                    }),
                None => Err("agent_id is required for agent files".to_string()),
            },
        };

        match outcome {
            Ok(true) => Ok(reply_json(
                &msg.id,
                "client.env.write.response",
                json!({ "success": true, "warnings": warnings }),
            )),
            Ok(false) => Ok(reply_json(
                &msg.id,
                "client.env.write.response",
                json!({ "success": false, "exists": true }),
            )),
            Err(e) => Ok(reply_json(
                &msg.id,
                "client.env.write.response",
                json!({ "success": false, "error": e }),
            )),
        }
    }

    /// Handle `client.env.delete` — delete an env file (blocked if in use).
    async fn handle_client_env_delete(
        &mut self,
        msg: ProtocolMessage<serde_json::Value>,
    ) -> anyhow::Result<HandlerAction> {
        if !self.authenticated_client {
            return Ok(reply_json(
                &msg.id,
                "client.env.delete.response",
                json!({ "success": false, "error": "Not authenticated" }),
            ));
        }
        let (name, source, agent_id) = parse_env_ref(&msg.payload);
        if name.is_empty() {
            return Ok(reply_json(
                &msg.id,
                "client.env.delete.response",
                json!({ "success": false, "error": "name is required" }),
            ));
        }

        let in_use = self
            .env_service
            .usage
            .sessions_using(&name, source, agent_id.as_deref());
        if !in_use.is_empty() {
            return Ok(reply_json(
                &msg.id,
                "client.env.delete.response",
                json!({
                    "success": false,
                    "error": format!(
                        "This file is in use by session(s): {}. Stop the session or detach before deleting.",
                        in_use.join(", ")
                    )
                }),
            ));
        }

        let outcome = match source {
            EnvSource::Server => self
                .env_service
                .store
                .delete(&name)
                .await
                .map_err(|e| e.to_string()),
            EnvSource::Agent => match &agent_id {
                Some(aid) => self
                    .agent_command(aid, "server.env.delete", json!({ "name": name }))
                    .await
                    .and_then(|resp| {
                        if resp.get("success").and_then(serde_json::Value::as_bool) == Some(true) {
                            Ok(())
                        } else {
                            Err(resp
                                .get("error")
                                .and_then(|v| v.as_str())
                                .unwrap_or("delete failed")
                                .to_string())
                        }
                    }),
                None => Err("agent_id is required for agent files".to_string()),
            },
        };

        match outcome {
            Ok(()) => Ok(reply_json(
                &msg.id,
                "client.env.delete.response",
                json!({ "success": true }),
            )),
            Err(e) => Ok(reply_json(
                &msg.id,
                "client.env.delete.response",
                json!({ "success": false, "error": e }),
            )),
        }
    }

    /// Resolve a set of env-file references into snapshots, capturing content at
    /// this moment (snapshot semantics). Server files are read locally; agent
    /// files are fetched from the owning agent. Missing files produce an error.
    async fn resolve_snapshots(
        &self,
        agent_id: &str,
        refs: &[EnvFileRef],
    ) -> Result<Vec<EnvSnapshot>, String> {
        let mut snapshots = Vec::new();
        for r in refs {
            let content = match r.source {
                EnvSource::Server => self.env_service.store.read(&r.name).await.map_err(|_| {
                    format!("Env file not found. It may have been deleted: {}", r.name)
                })?,
                EnvSource::Agent => {
                    // Agent files are read from the file's owning agent (which is
                    // normally the same agent hosting the session).
                    let owner = r.agent_id.as_deref().unwrap_or(agent_id);
                    let resp = self
                        .agent_command(owner, "server.env.get", json!({ "name": r.name }))
                        .await?;
                    if resp.get("success").and_then(serde_json::Value::as_bool) != Some(true) {
                        return Err(format!(
                            "Env file not found. It may have been deleted: {}",
                            r.name
                        ));
                    }
                    resp.get("content")
                        .and_then(|v| v.as_str())
                        .unwrap_or("")
                        .to_string()
                }
            };
            let parsed = parse_env(&content);
            snapshots.push(EnvSnapshot {
                name: r.name.clone(),
                source: r.source,
                agent_id: r.agent_id.clone(),
                vars: parsed.vars,
                warnings: parsed.warnings,
            });
        }
        Ok(snapshots)
    }

    /// Handle `client.session.env.apply` — apply env files to a running session.
    async fn handle_client_session_env_apply(
        &mut self,
        msg: ProtocolMessage<serde_json::Value>,
    ) -> anyhow::Result<HandlerAction> {
        if !self.authenticated_client {
            return Ok(reply_json(
                &msg.id,
                "client.session.env.apply.response",
                json!({ "success": false, "error": "Not authenticated" }),
            ));
        }
        let session_id = msg
            .payload
            .get("session_id")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .to_string();
        let refs: Vec<EnvFileRef> = msg
            .payload
            .get("env_files")
            .and_then(|v| serde_json::from_value(v.clone()).ok())
            .unwrap_or_default();

        let Some((agent_id, session_name)) = session_id.split_once(':') else {
            return Ok(reply_json(
                &msg.id,
                "client.session.env.apply.response",
                json!({ "success": false, "error": "Invalid session_id" }),
            ));
        };
        let agent_id = agent_id.to_string();
        let session_name = session_name.to_string();

        let snapshots = match self.resolve_snapshots(&agent_id, &refs).await {
            Ok(s) => s,
            Err(e) => {
                return Ok(reply_json(
                    &msg.id,
                    "client.session.env.apply.response",
                    json!({ "success": false, "error": e }),
                ));
            }
        };

        let warnings: Vec<String> = snapshots.iter().flat_map(|s| s.warnings.clone()).collect();

        let resp = self
            .agent_command(
                &agent_id,
                "server.session.env.apply",
                json!({ "name": session_name, "snapshots": snapshots }),
            )
            .await;

        match resp {
            Ok(r) if r.get("success").and_then(serde_json::Value::as_bool) == Some(true) => {
                self.env_service
                    .usage
                    .record_attach(&session_id, &refs, None);
                Ok(reply_json(
                    &msg.id,
                    "client.session.env.apply.response",
                    json!({ "success": true, "warnings": warnings }),
                ))
            }
            Ok(r) => Ok(reply_json(
                &msg.id,
                "client.session.env.apply.response",
                json!({
                    "success": false,
                    "error": r.get("error").and_then(|v| v.as_str()).unwrap_or("apply failed")
                }),
            )),
            Err(e) => Ok(reply_json(
                &msg.id,
                "client.session.env.apply.response",
                json!({ "success": false, "error": e }),
            )),
        }
    }

    /// Handle `client.session.env.unset` — remove attach-time env files from a
    /// running session (on detach).
    async fn handle_client_session_env_unset(
        &mut self,
        msg: ProtocolMessage<serde_json::Value>,
    ) -> anyhow::Result<HandlerAction> {
        if !self.authenticated_client {
            return Ok(reply_json(
                &msg.id,
                "client.session.env.unset.response",
                json!({ "success": false, "error": "Not authenticated" }),
            ));
        }
        let session_id = msg
            .payload
            .get("session_id")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .to_string();
        let refs: Vec<EnvFileRef> = msg
            .payload
            .get("env_files")
            .and_then(|v| serde_json::from_value(v.clone()).ok())
            .unwrap_or_default();

        let Some((agent_id, session_name)) = session_id.split_once(':') else {
            return Ok(reply_json(
                &msg.id,
                "client.session.env.unset.response",
                json!({ "success": false, "error": "Invalid session_id" }),
            ));
        };
        let agent_id = agent_id.to_string();
        let session_name = session_name.to_string();

        // Resolve the keys to unset from the current file content. Best-effort:
        // if a file is now missing, skip it rather than failing the detach.
        let snapshots = self
            .resolve_snapshots(&agent_id, &refs)
            .await
            .unwrap_or_default();
        let keys: Vec<String> = snapshots
            .iter()
            .flat_map(|s| s.vars.iter().map(|(k, _)| k.clone()))
            .collect();

        let resp = self
            .agent_command(
                &agent_id,
                "server.session.env.unset",
                json!({ "name": session_name, "keys": keys }),
            )
            .await;

        // Release the usage regardless of the agent's reply — the client's
        // intent to detach is authoritative for lock purposes.
        self.env_service
            .usage
            .remove_attach(&session_id, &refs, None);

        match resp {
            Ok(r) if r.get("success").and_then(serde_json::Value::as_bool) == Some(true) => {
                Ok(reply_json(
                    &msg.id,
                    "client.session.env.unset.response",
                    json!({ "success": true }),
                ))
            }
            Ok(r) => Ok(reply_json(
                &msg.id,
                "client.session.env.unset.response",
                json!({
                    "success": false,
                    "error": r.get("error").and_then(|v| v.as_str()).unwrap_or("unset failed")
                }),
            )),
            Err(e) => Ok(reply_json(
                &msg.id,
                "client.session.env.unset.response",
                json!({ "success": false, "error": e }),
            )),
        }
    }

    /// Handle `client.session.env.active` — list env files active on a session.
    async fn handle_client_session_env_active(
        &mut self,
        msg: ProtocolMessage<serde_json::Value>,
    ) -> anyhow::Result<HandlerAction> {
        if !self.authenticated_client {
            return Ok(reply_json(
                &msg.id,
                "client.session.env.active.response",
                json!({ "active": [], "error": "Not authenticated" }),
            ));
        }
        let session_id = msg
            .payload
            .get("session_id")
            .and_then(|v| v.as_str())
            .unwrap_or("");
        let active = self.env_service.usage.active_for(session_id);
        Ok(reply_json(
            &msg.id,
            "client.session.env.active.response",
            json!({ "active": active }),
        ))
    }
}

/// Build a `HandlerAction::Reply` with a standard protocol envelope.
fn reply_json(id: &str, msg_type: &str, payload: serde_json::Value) -> HandlerAction {
    HandlerAction::Reply(Some(Message::Text(
        json!({
            "msg_type": msg_type,
            "id": id,
            "timestamp": current_timestamp(),
            "payload": payload,
        })
        .to_string(),
    )))
}

/// Extract (name, source, agent_id) from an env-file reference payload.
fn parse_env_ref(payload: &serde_json::Value) -> (String, EnvSource, Option<String>) {
    let name = payload
        .get("name")
        .and_then(|v| v.as_str())
        .unwrap_or("")
        .to_string();
    let source = match payload.get("source").and_then(|v| v.as_str()) {
        Some("agent") => EnvSource::Agent,
        _ => EnvSource::Server,
    };
    let agent_id = payload
        .get("agent_id")
        .and_then(|v| v.as_str())
        .map(str::to_string);
    (name, source, agent_id)
}

fn current_timestamp() -> u64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

pub mod command_broker;
mod handler;
mod websocket;

pub use handler::{ConnectionHandler, HandlerAction};
pub use websocket::WebSocketServer;

use std::sync::Arc;
use tokio::net::TcpListener;
use tokio_rustls::TlsAcceptor;
use tokio_tungstenite::accept_async;
use tracing::{error, info};

use super::handler::{ConnectionHandler, HandlerAction};
use crate::db::Database;
use crate::env::EnvService;
use crate::registry::{AgentRegistry, AgentStatus, SessionRegistry};
use crate::server::command_broker::CommandBroker;
use nession_common::config::ServerConfig;

pub struct WebSocketServer {
    config: ServerConfig,
    agent_registry: Arc<AgentRegistry>,
    session_registry: Arc<SessionRegistry>,
    command_broker: Arc<CommandBroker>,
    env_service: Arc<EnvService>,
    db: Arc<Database>,
    listener: Option<TcpListener>,
}

impl WebSocketServer {
    pub async fn new(config: ServerConfig, db: Arc<Database>) -> anyhow::Result<Self> {
        let listener = TcpListener::bind(&config.listen_address).await?;
        let agent_registry = Arc::new(AgentRegistry::new(config.heartbeat_timeout_secs));
        let session_registry = Arc::new(SessionRegistry::new(Arc::clone(&db)));

        // Load persisted sessions from the database. They will be shown as
        // "recovering" until their agent reconnects and confirms them.
        session_registry.load_from_db().await;

        let command_broker = Arc::new(CommandBroker::new());

        let env_root = nession_common::paths::server_envs_dir()
            .unwrap_or_else(|_| std::path::PathBuf::from(".nession/server/envs"));
        let env_service = EnvService::new(env_root);

        Ok(Self {
            config,
            agent_registry,
            session_registry,
            command_broker,
            env_service,
            db,
            listener: Some(listener),
        })
    }

    pub async fn run(&mut self) -> anyhow::Result<()> {
        let listener = self
            .listener
            .take()
            .ok_or_else(|| anyhow::anyhow!("Server already running or not initialized"))?;

        info!("WebSocket server listening on {}", listener.local_addr()?);

        let tls_acceptor = if !self.config.tls_cert_path.is_empty() {
            Some(build_tls_acceptor(
                &self.config.tls_cert_path,
                &self.config.tls_key_path,
            )?)
        } else {
            None
        };

        let heartbeat_interval_secs = self.config.heartbeat_interval_secs;

        // Background sweeper: periodically mark agents that have missed their
        // heartbeat window as offline so clients stop targeting dead agents.
        // Sessions for offline agents are cleaned after a 30s grace period
        // to allow for agent reconnection.
        {
            let agent_registry = Arc::clone(&self.agent_registry);
            let session_registry = Arc::clone(&self.session_registry);
            let command_broker = Arc::clone(&self.command_broker);
            // Sweep at the heartbeat cadence (min 1s) so detection latency stays
            // close to the configured timeout.
            let sweep_period = std::time::Duration::from_secs(heartbeat_interval_secs.max(1));
            tokio::spawn(async move {
                let mut ticker = tokio::time::interval(sweep_period);
                ticker.tick().await; // consume the immediate first tick
                loop {
                    ticker.tick().await;
                    let offline = agent_registry.check_offline_agents().await;
                    for agent_id in offline {
                        info!("Agent {} marked offline (heartbeat timeout)", agent_id);
                        command_broker.unregister_agent(&agent_id).await;

                        // Schedule session cleanup after 30s grace period.
                        // If the agent reconnects before the grace period
                        // expires, its sessions are preserved.
                        let session_registry = Arc::clone(&session_registry);
                        let agent_registry = Arc::clone(&agent_registry);
                        let agent_id_clone = agent_id.clone();
                        tokio::spawn(async move {
                            tokio::time::sleep(std::time::Duration::from_secs(30)).await;
                            // Only clean if agent is still offline after grace period.
                            if let Some(agent) = agent_registry.get(&agent_id_clone).await {
                                if agent.status == AgentStatus::Offline {
                                    info!(
                                        "Cleaning sessions for offline agent {} (grace period expired)",
                                        agent_id_clone
                                    );
                                    session_registry.remove_by_agent(&agent_id_clone).await;
                                }
                            }
                        });
                    }
                }
            });
        }

        // Background sweep: periodically clean up orphaned sessions whose
        // agent has been unreachable for more than 24 hours.
        {
            let session_registry = Arc::clone(&self.session_registry);
            let db = Arc::clone(&self.db);
            // Run every hour — orphan cleanup is not latency-sensitive.
            let sweep_period = std::time::Duration::from_secs(3600);
            tokio::spawn(async move {
                let mut ticker = tokio::time::interval(sweep_period);
                ticker.tick().await; // consume the immediate first tick
                loop {
                    ticker.tick().await;
                    // 24 hours in seconds
                    let cutoff = 24 * 3600i64;
                    match db.list_sessions_older_than(cutoff).await {
                        Ok(rows) => {
                            if rows.is_empty() {
                                continue;
                            }
                            for row in &rows {
                                info!(
                                    "Cleaning orphaned session {} (agent: {}, last activity: {})",
                                    row.session_id, row.agent_id, row.last_activity
                                );
                                session_registry.remove(&row.session_id).await;
                            }
                            tracing::info!("Cleaned {} orphaned sessions", rows.len());
                        }
                        Err(e) => {
                            error!("Orphan session sweep failed: {:#}", e);
                        }
                    }
                }
            });
        }

        loop {
            let (tcp_stream, addr) = listener.accept().await?;
            info!("New connection from: {}", addr);

            let ctx = ServerContext {
                agent_registry: Arc::clone(&self.agent_registry),
                session_registry: Arc::clone(&self.session_registry),
                command_broker: Arc::clone(&self.command_broker),
                env_service: Arc::clone(&self.env_service),
                auth_token: self.config.auth_token.clone(),
                heartbeat_interval_secs,
            };
            let tls_acceptor = tls_acceptor.clone();

            tokio::spawn(async move {
                if let Err(e) = handle_connection(tcp_stream, tls_acceptor, ctx).await {
                    error!("Connection error: {}", e);
                }
            });
        }
    }

    pub fn local_addr(&self) -> anyhow::Result<std::net::SocketAddr> {
        self.listener
            .as_ref()
            .ok_or_else(|| anyhow::anyhow!("Server not initialized"))?
            .local_addr()
            .map_err(|e| anyhow::anyhow!("Failed to get local address: {e}"))
    }
}

fn build_tls_acceptor(cert_path: &str, key_path: &str) -> anyhow::Result<TlsAcceptor> {
    use rustls::pki_types::{CertificateDer, PrivateKeyDer};
    use rustls::ServerConfig;
    use rustls_pemfile::{certs, private_key};
    use std::fs::File;
    use std::io::BufReader;

    let cert_file = File::open(cert_path)?;
    let mut cert_reader = BufReader::new(cert_file);
    let cert_chain: Vec<CertificateDer<'static>> =
        certs(&mut cert_reader).collect::<Result<Vec<_>, _>>()?;

    let key_file = File::open(key_path)?;
    let mut key_reader = BufReader::new(key_file);
    let key: PrivateKeyDer<'static> =
        private_key(&mut key_reader)?.ok_or_else(|| anyhow::anyhow!("No private key found"))?;

    let config = ServerConfig::builder()
        .with_no_client_auth()
        .with_single_cert(cert_chain, key)?;

    Ok(TlsAcceptor::from(Arc::new(config)))
}

/// Shared, cheaply-cloneable state handed to each connection handler task.
#[derive(Clone)]
struct ServerContext {
    agent_registry: Arc<AgentRegistry>,
    session_registry: Arc<SessionRegistry>,
    command_broker: Arc<CommandBroker>,
    env_service: Arc<EnvService>,
    auth_token: String,
    heartbeat_interval_secs: u64,
}

async fn handle_connection(
    tcp_stream: tokio::net::TcpStream,
    tls_acceptor: Option<TlsAcceptor>,
    ctx: ServerContext,
) -> anyhow::Result<()> {
    if let Some(acceptor) = tls_acceptor {
        let tls_stream = acceptor.accept(tcp_stream).await?;
        handle_ws_stream(tls_stream, ctx).await
    } else {
        handle_ws_stream(tcp_stream, ctx).await
    }
}

async fn handle_ws_stream<S>(stream: S, ctx: ServerContext) -> anyhow::Result<()>
where
    S: tokio::io::AsyncRead + tokio::io::AsyncWrite + Unpin + Send + 'static,
{
    use crate::server::command_broker::WsMessageSender;
    use futures_util::SinkExt;
    use futures_util::StreamExt;

    let ServerContext {
        agent_registry,
        session_registry,
        command_broker,
        env_service,
        auth_token,
        heartbeat_interval_secs,
    } = ctx;

    let ws_stream = accept_async(stream).await?;
    let (mut write, mut read) = ws_stream.split();
    let mut handler = ConnectionHandler::new(
        agent_registry,
        session_registry,
        command_broker.clone(),
        env_service,
        auth_token,
        heartbeat_interval_secs,
    );

    // Create a channel-based sender for CommandBroker to send commands
    let (sender, mut rx) = WsMessageSender::new();

    // Spawn a relay task that drains the receiver and forwards to the actual
    // write sink. A periodic WebSocket Ping keeps the TCP path alive through
    // intermediaries and lets us detect a dead peer quickly.
    let ping_period = std::time::Duration::from_secs(heartbeat_interval_secs.max(1));
    let relay_task = tokio::spawn(async move {
        let mut ping_ticker = tokio::time::interval(ping_period);
        ping_ticker.tick().await; // consume the immediate first tick
        loop {
            tokio::select! {
                maybe_msg = rx.recv() => {
                    match maybe_msg {
                        Some(msg) => {
                            if let Err(e) = write.send(msg).await {
                                error!("Failed to send WebSocket message: {}", e);
                                break;
                            }
                        }
                        None => break,
                    }
                }
                _ = ping_ticker.tick() => {
                    if let Err(e) = write.send(tokio_tungstenite::tungstenite::Message::Ping(Vec::new())).await {
                        error!("Failed to send WebSocket ping: {}", e);
                        break;
                    }
                }
            }
        }
    });

    while let Some(msg) = read.next().await {
        let msg = msg?;

        // Track agent registration changes
        let prev_agent_id = handler.registered_agent_id().cloned();

        let action = handler.handle_message(msg).await?;

        // If a new agent just registered, register its sender with CommandBroker
        let new_agent_id = handler.registered_agent_id().cloned();
        if let Some(ref agent_id) = new_agent_id {
            if prev_agent_id.as_ref() != Some(agent_id) {
                command_broker
                    .register_agent(agent_id, sender.clone())
                    .await;
            }
        }

        match action {
            HandlerAction::Reply(Some(response)) => {
                sender.send(response)?;
            }
            HandlerAction::Reply(None) => {
                // No response needed, continue
            }
            HandlerAction::Relay { agent_ws_url } => {
                relay_bidirectional_via_channel(&mut read, sender.clone(), &agent_ws_url).await?;
                break;
            }
            HandlerAction::Close => {
                break;
            }
        }
    }

    // Clean up: unregister agent from CommandBroker on disconnect
    if let Some(agent_id) = handler.registered_agent_id() {
        command_broker.unregister_agent(agent_id).await;
    }

    // Drop the sender to signal the relay task to exit
    drop(sender);
    // Wait for the relay task to finish
    let _ = relay_task.await;

    Ok(())
}

/// Relay mode using channel-based sender for client writes.
/// Used when the write sink is managed by a relay task.
async fn relay_bidirectional_via_channel<RS>(
    client_read: &mut RS,
    sender: crate::server::command_broker::WsMessageSender,
    agent_ws_url: &str,
) -> anyhow::Result<()>
where
    RS: futures_util::Stream<
            Item = Result<
                tokio_tungstenite::tungstenite::Message,
                tokio_tungstenite::tungstenite::Error,
            >,
        > + Unpin,
{
    use futures_util::SinkExt;
    use futures_util::StreamExt;

    info!(
        "Entering relay mode, connecting to agent at {}",
        agent_ws_url
    );

    let (agent_ws, _) = tokio_tungstenite::connect_async(agent_ws_url).await?;
    let (mut agent_write, mut agent_read) = agent_ws.split();

    info!("Relay connection established");

    // Helper: detect terminal.input JSON messages.
    fn is_terminal_input(msg: &tokio_tungstenite::tungstenite::Message) -> bool {
        msg.to_text()
            .ok()
            .map(|t| t.contains("\"terminal.input\""))
            .unwrap_or(false)
    }

    // Forward client -> agent, with trailing-edge rate limiting on
    // terminal.input to protect against mouse-tracking floods.  Keyboard
    // input (also carried as terminal.input) is naturally slow enough
    // (< 20 Hz) that it always passes on the leading edge.
    const INPUT_THROTTLE_MS: u64 = 16;
    let mut last_terminal_input = std::time::Instant::now()
        .checked_sub(std::time::Duration::from_secs(60))
        .unwrap_or(std::time::Instant::now());

    let client_to_agent = async {
        while let Some(msg) = client_read.next().await {
            let msg = match msg {
                Ok(m) => m,
                Err(e) => {
                    error!("Error reading from client: {}", e);
                    break;
                }
            };

            // Non-terminal.input passes through immediately.
            if !is_terminal_input(&msg) {
                if let Err(e) = agent_write.send(msg).await {
                    error!("Failed to forward client message to agent: {}", e);
                    break;
                }
                continue;
            }

            // Terminal.input: trailing-edge throttle.  If within the window
            // from the last send, drain additional mouse events and keep
            // only the latest position.  Non-mouse messages that arrive
            // during the drain are forwarded immediately.
            let elapsed = last_terminal_input.elapsed();
            if elapsed < std::time::Duration::from_millis(INPUT_THROTTLE_MS) {
                let drain_deadline =
                    last_terminal_input + std::time::Duration::from_millis(INPUT_THROTTLE_MS);
                let mut latest = msg;

                loop {
                    let remaining =
                        drain_deadline.saturating_duration_since(std::time::Instant::now());
                    if remaining.is_zero() {
                        break;
                    }
                    match tokio::time::timeout(remaining, client_read.next()).await {
                        Ok(Some(Ok(m))) if is_terminal_input(&m) => {
                            latest = m; // keep only latest mouse event
                        }
                        Ok(Some(Ok(m))) => {
                            // Non-terminal.input message during drain:
                            // forward it now, then break to send latest.
                            let _ = agent_write.send(m).await;
                            break;
                        }
                        Ok(Some(Err(e))) => {
                            error!("Error reading from client: {}", e);
                            break;
                        }
                        Ok(None) | Err(tokio::time::error::Elapsed { .. }) => {
                            break; // stream ended or timeout
                        }
                    }
                }

                // Send the latest buffered terminal.input.
                if let Err(e) = agent_write.send(latest).await {
                    error!("Failed to forward client message to agent: {}", e);
                    break;
                }
                last_terminal_input = std::time::Instant::now();
            } else {
                // Outside throttle window — send immediately (leading edge).
                last_terminal_input = std::time::Instant::now();
                if let Err(e) = agent_write.send(msg).await {
                    error!("Failed to forward client message to agent: {}", e);
                    break;
                }
            }
        }
    };

    // Forward agent -> client (via channel sender)
    let agent_to_client = async {
        while let Some(msg) = agent_read.next().await {
            match msg {
                Ok(msg) => {
                    if let Err(e) = sender.send(msg) {
                        error!("Failed to forward agent message to client: {}", e);
                        break;
                    }
                }
                Err(e) => {
                    error!("Error reading from agent: {}", e);
                    break;
                }
            }
        }
    };

    tokio::select! {
        _ = client_to_agent => {
            info!("Client to agent relay ended");
        }
        _ = agent_to_client => {
            info!("Agent to client relay ended");
        }
    }

    info!("Relay mode ended");
    Ok(())
}
